window.HB_TR["proverbs"]["ks"]=["1. اسرٲیلُک بادشاہ داؤد سُند نیچو سُلیمان سُند محاورٕ۔\n2. حکمت تہٕ ہدایت زانٕنۍ؛ سمجھن ہٕندِس لفظس سمجُن؛\n3. حکمت، انصاف تہٕ فیصلہٕ تہٕ برابری ہٕنز تعلیم حٲصل کرٕنۍ۔ {ایکویٹی: ہیب۔ ایکویٹیز}\n4.\\tسادس تہ نوجوانس علم تہ صوابدید دِنۍ۔ {صوابدید: یا، مشورہٕ}\n5.\\tاکھ عقلمند {انسان} بوزِ تہٕ کرِ ہیچھنس منز اضافہٕ۔ تہٕ سمجھدار انسان گژھہِ دانشمندانہ مشورن تام حٲصل:\n6. اکھ ضرب المثل تہٕ تشریح سمجھنہٕ خٲطرٕ؛ دانشمندن ہٕندِ کلام، تہٕ تِہٕندِ سیاہ کلام۔ {تشریح: یا، اکھ فصیح تقریر}\n7. خداوند سُند خوف {چُھ} علمُک آغاز: {مگر} بیوقوف چھِ حکمت تہٕ تعلیمہٕ سٍتـ̡ حقارت کران۔ {آغاز: یا، اہم حصہٕ}\n8.\\tمیانہِ نیچو، پننِس مٲلہِ سٕنز ہدایت بوزو، تہٕ پننہِ ماجہ ہٕندِس شریعت سٍتـ̡ تراوُن نہٕ:\n9. تِم گژھن تُہٕندِس کلَس خٲطرٕ فضل ہُند زیور تہٕ تُہنزِ گردنَس سٍتـ̡ زنجیر۔ {an...: Heb. اکھ اضافہ}\n10.\\tمیانہِ نیچو، اگر گۅنہگار تہِ آمادہ کٔرِتھ تہِ گژھہِ نہٕ رضامندی دِنہٕ۔\n11. اگر تِم ونان چھِ، اسہِ سٍتـ̡ یِو خونُک انتظار کرُن، أسـ̡ بے گناہ لوکن ہٕندِ خٲطرٕ رٔلِتھ روزُن:\n12. أسۍ گِلہِ تِم قبرِ ہٕندۍ پٲٹھۍ زِندٕ نِنہٕ۔ تہٕ پوٗرٕ پٲٹھۍ، یِتھٕ پٲٹھۍ یِم گڑھس منٛز وسان چھِ:\n13.\\tاسہِ میلہِ سارِنٕے قٕمتی چیز، أسۍ کرو پنٕنـ̡ گَرٕ لوُٹ سٍتـ̡ بٔرِتھ:\n14. پَنُن لاٹ کٔرِو اسہِ مَنٛز تراوُن؛ اسہِ سارِنٕے آسہِ اکھ پرس:\n15.\\tمیانہِ نیچو، تِمن سٍتـ̡ پٔکِتھ پٔکِتھ پٔکِتھ پٔکِتھ تہنزِ وتہِ نِش رُکٲوِو پَنُن قدم رُکُن:\n16.\\tتِہٕندِس کھۅر چھِ بُرِس کُن ژلان، تہٕ خوُن رَسنہٕ خٲطرٕ جلدی کٔرِتھ۔\n17.\\tیقینا چھہ کانہہ تہِ جاناوار نظرِ منز جال پھہلاونہ یوان۔ {منز...: ہیب۔ پریتھ کانہہ چیز یُس پکھہ آسہِ}\n18.\\tتہٕ تِم ٲسۍ پننِس خونس انتظار۔ تِم چھِ پننہِ {پنٕنۍ} زِنٛدگی خٲطرٕ رازدٲری سان روزان۔\n19.\\tیتھے پاٹھۍ چھہِ پریتھ کٲنسہِ سٕندِ وتہِ یُس نفعُک لالچ آسہِ۔ {یُس} چُھ امِکۍ مٲلکَن ہٕنز زِندگی نِوان۔\n20. حکمت چِھ نیبر چُھ فریاد کران؛ سُہ چُھ سڑکن منز پنٕنۍ آواز بولان: {حکمت: ہیب۔ حکمت، یعنی بہترین حکمت}\n21.\\tسُہ چُھہ دروازن ہٕندِس دروازس مَنٛز وَنان۔ شہرس مَنٛز چھے سُہ پَنٕنہِ کَتھٕ کَران، {وَن}۔\n22.\\tاے سادہ لو، ژیہ کٲژا تام سادگی پسند؟ تہٕ طنز کرن وٲلۍ چھِ پننہِ حقارت منٛز خۄش گژھان، تہٕ بیوقوف چھِ علمس سۭتۍ نفرت؟\n23.\\tمیانہِ ملامت کٔرِتھ پھیُر: وُچھ، بہٕ کٔرٕ ژے پنُن روح ژے تام واتناوُن، بہٕ کرٕ ژے پنٕنۍ کتھ زان۔\n24.\\tکیازِ میہ چُھہ بُلاونہٕ آمُت، تہٕ ژے کٔر انکار۔ مے چھُ پنُن اَتھٕ بڑاومُت، تہٕ کٲنسہ تہِ اوس نہٕ انسانس سٍتۍ غور کٔرِتھ۔\n25.\\tمگر ژے چُھہ میانہِ سارِنٕے مشورٕ کٔرِتھ تہٕ میانہِ کُنہِ تہِ ملامت کٔرِتھ:\n26. بہٕ تہِ اسُن چانہِ آفتس پیٹھ۔ بہٕ کٔرٕ ٹھٹھہٕ ییٚلہِ چانہِ خوف ییہِ۔\n27. یێلہِ تُہُند خوف ویران گژھہِ، تہٕ تُہٕنز تباہی وُپھ ہٕندِس پٲٹھۍ؛ ییٚلہِ تۄہہِ مُصیبت تہٕ دَکھ یِیہِ۔\n28. تیلہِ گژھن تِم میہ بلاون، مگر بہٕ کرٕ نہٕ جواب۔ تِم ژھانڈن میہ سُلہٕ، مگر تِم لٔبِتھ نہٕ مےٚ:\n29.\\tامہ مۅکھہ ٲسۍ تِمو علمس سٍتـ̡ نفرت، تہٕ خدایہ سُند خوف ژٲرُکھ نہٕ:\n30.\\tتِم ٲسۍ نہٕ میانہِ سارِنٕے ملامت سٍتۍ نفرت۔\n31.\\tتێلہِ گژھن تِم پننہِ طریقہٕ کِس پھلہٕ سٍتـ̡ کھٮ۪ن، تہٕ پنہٕ نـ̡ پنہٕ نـ̡ بٔرِتھ بٔرِتھ۔\n32.\\tتکیازِ سادہ لوکن ہُند پتھ پھیرنہٕ سٍتـ̡ مارِ تِم تہٕ بیوقوفن ہٕنزِ خوشحالی کرِ تِمن تباہ ۔ {پھیرُن...: یا، سادٕچ آسانی}\n33. مگر یُس تہِ میانہِ کتھ بوزِ، سُہ روزِ بُردی ہٕندِ خوفہٕ سٍتـ̡ خاموش روزُن۔","1. میانہِ نیچو، اگر ژے میٲنۍ کلام رٔٹِتھ تہٕ میٲنۍ حُکمن پانس سٍتـ̡ ژوٗرِ تھاوٕنـ̡ ۔\n2. یُتھ زن ژے پنُن کَن حکمتس کُن مائل کٔرِتھ، {تہٕ} پَنُن دِل کٔرِو فِکرس کُن استعمال۔\n3. آ، اگر ژیہ علمہٕ پتہٕ فریاد کٔرِو، {تہٕ} سمجھنہٕ خٲطرٕ تُلِو پنٕنۍ آواز۔ {liftest...: Heb. پنٕنۍ آواز دِیُو}\n4.\\tاگر ژیہ أمس رۅپہِ ہٕندِ پٲٹھۍژھانڈان چھِ، تہٕ ژھانڈِتھ ژھانڈِو۔\n5. تیلہِ گژھہِ خداوند سُند خوف سمجُن، تہٕ خدایہ سُند علم حٲصل کرُن۔\n6. کیازِ خداوند چُھ حکمت دِوان: پننہِ ٲسہِ سٍتـ̡ چُھ علم تہٕ فہم دِوان۔\n7.\\tسُہ چُھ نیک لوکن ہٕندِ خٲطرٕ صحیح حکمت پیش کران: {سُہ} چُھہ تِمن ہٕندِ خٲطرٕ یُس سیدِ پٲٹھـ̡ پکان چُھ۔\n8. سُہ چُھ فیصلٕچ وَتھ برقرار تھاوان، تہٕ پَنٕنِس مُقدسن ہٕنزِ وتہٕ رژھراوان چُھ۔\n9. تیلہِ گژھہِ نیکی تہٕ انصاف تہٕ انصاف سمجُن۔ {آ}، پرتھ اصل وتھ۔\n10. ییلہِ حکمت تُہندِس دِلس مَنٛز اژِتھ تہٕ علم چُھہ تُہٕندِس روحس خۅش گَژھان۔\n11.\\tصوابدید کرِ تۅہہ رژھرتھ، سمجھ تھاوِ توہ:\n12. بد کار سٕنزِ وتہِ نِش بچاونہٕ خٲطرٕ، یُس بدکار کتھ کران چُھ، تٔمِس انسانس نِش بچاونہٕ خٲطرٕ۔\n13.\\tیُس سیدِ وتہِ ترٲوِتھ اندھیرے ہٕنزِ وتہِ پکان چھُ۔\n14.\\tیُس بد کار کٔرِتھ خوش سپدان چھُ، {تہٕ} بدکارن ہٕنزِ شرارتس سٍتـ̡ خوش سپدان۔\n15.\\tیِمن ہٕنزِ وتہٕ چھِ ٹیڑھ تہٕ تِم چھِ پنہٕ نِس وتہٕ وَتہٕ پٲٹھۍ:\n16.\\tژے نِش نجات دِنہٕ خٲطرٕ، {حتی} اجنبی نِش یُس تٔمۍ سٕندِس کلامَس سٍتـ̡ خوشامد کران چُھ؛\n17. یُس پننہِ جوانی ہٕندِس رہنُما سٍتـ̡ تراوان چُھ، تہٕ پننِس خدایہ سُند عہد مٔشِل کران چُھ۔\n18.\\tتٔمۍ سٕندِس گرس سٍتـ̡ چُھہ موتس کُن رُکاونہٕ آمُت، تہٕ تٔمۍ سٕنزِ وَتہٕ چُھہ مُردن کُن۔\n19. یُس نہٕ أمِس دُبارٕ واپسس کُن گژھان چھُ، سُہ چُھ نہٕ زندگی ہٕنزِ وتہٕ رٔٹِتھ۔\n20. یُتھ زِ تُہۍ گژھِو نیک انسانن ہٕنزِ وتہِ پٔکِتھ، تہٕ نیکوکارن ہٕنزِ وتہٕ پٔکِتھ۔\n21.\\tتکیازِ نیک روزِ زمینس منز روزُن، تہٕ کامل روزِ اَتھ مَنٛز روزُن۔\n22. مگر بدکار یِن زمینہٕ نِش ژٹنہٕ، تہٕ نافرمان یِن اَتھ مَنٛز موٗل کڈنہٕ۔ {روٹڈ: یا، تُلنہٕ آمُت}","1. میانہِ نیچو، میون قانون مہ مٔشِد گژھُن۔ مگر پنُن دِل تھاوُن میٲنۍ حکم:\n2. دۅہن ہٕندِس زیچھرس تہٕ زیچھر وٲنسہِ تہٕ سُکوٗن خٲطرٕ گژھن تِم ژے ہُند اضافہٕ۔ {زیٹھ...: ہیب۔ زندگی ہٕنٛدۍ ؤری}\n3. رحم تہٕ سچائی گژھ نہٕ تراوُن: تِم تھٲوِو پننہِ گردنَس مَنٛز۔ تِم لیکھِو پننہِ دِل کِس میزس پیٹھ:\n4. یێلہِ پٲٹھـ̡ تہٕ خدایہِ سٕندِس نظرس مَنٛز میلہِ احسان تہٕ رٔژ فہم ۔ {اصل...: یا، جان کامیابی}\n5. خداوند سٕندِس سٍتـ̡ کٔرِو پَنٕنہِ دِلہٕ سٍتـ̡ بھروسہٕ۔ تہٕ پننہ فہم کُن گژھ نہٕ جھکُن۔\n6. پنہٕ نِس سارِنٕے طریقو سٍتـ̡ کٔرِو أمِس تسلیم تہٕ سُہ کرِ تُہنزِ وتہِ ہٕنز وَتہٕ۔\n7. پننین نظرن منز گژھہِ نہ عقلمند: خداوند سٍتـ̡ کھوژُن، تہٕ بدی نِش گژھِو دور۔\n8. یہ گژھہِ چانہِ نافہِ صحت تہٕ اڈجن ہُند مَرٕ۔ {صحت: ہیب۔ دوا} {میرو: ہیب۔ آب دِنہٕ، یا، نم کَرُن}\n9. خداوند سُند احترام کرُن پنہٕ نِس مالہٕ سٍتـ̡ تہٕ پنہٕ نِس سارِنٕے اضافہٕ سٍتـ̡ گۅڈنِکِس پھلَس سٍتـ̡\n10. یِتھٕ پٲٹھۍ گژھن چانہِ کوٹھہٕ سٍتـ̡ بٔرِتھ، تہٕ تُہٕندِس دباونہٕ سٍتـ̡ نوِ شرابٕ سٍتـ̡ پھٔٹِتھ پھٔٹِتھ۔\n11.\\tمیانہِ نیچو، خداوند سٕندِس عذابس سٍتـ̡ گژھ نہٕ حقارت۔ تٔمۍ سٕنزِ اصلاح نِش گژھِ نہ تھکان :\n12. یٔمِس سٍتـ̡ خداوند محبت کران چُھ، سُہ چُھ اصلاح کران۔ یوتام زِ مٲل سُند نیچو {یمس} سُہ خوش چُھ کران۔\n13.\\tخوش چھہ {یُس} انسان {یُس} عقل میلان تہ انسان {یہ} سمجھ میلان چھُ۔ {یہ گیتھ...: ہیب۔ یُس سمجھ نیران چھُ}\n14.\\tامہِ کِس تجارتس سٍتـ̡ چُھہ رۄپہٕ سٕندِ تِجارتہٕ کھۅتہٕ بہتر، تہٕ اَمہ سٍتـ̡ چُھہ سُہ سۄنہٕ سٍتـ̡ بہتر تہٕ اَمہ سٍتـ̡ حٲصل سپدُن۔\n15.\\tسۅ چھیہ یاقوت کھوتہ زیادہ قیمتی تہ یمن سارِنٕے چیزن ہُند موازنہٕ گژھِ نہٕ أمس سٍتـ̡ کرنہٕ یُن۔\n16. دۅہن ہند زیچھر {چھُ} دچھنہِ اتھس منز۔ {تہ} تٔمۍ سٕندِس کھوورِ اتھس منز دولت تہٕ عزت۔\n17.\\tتسٕنزِ وتہٕ چھِ خۅش گَژھنٕچ وَتھ، تہٕ تٔمۍ سٕنزِ سارِنٕے وَتہٕ چھِ سُکُن۔\n18.\\tسۅ چھیہ تمن ہندِ خاطرہ زندگی ہند کُل یُس تس تھپھ کران چھہِ، تہ خوش چھہ پریتھ کانہہ یُس تس رژھراوان چھہ۔\n19. خداوند چُھ حکمت سٍتـ̡ زمینہِ ہٕنز بنیاد تھٲومٕژ۔ سمجھہٕ سٍتـ̡ چُھ تٔمۍ آسمانہٕ قایم کورمُت۔ {قائم: یا، تیار}\n20.\\tتمۍ سندِ علمہ مطابق چھہ سرٛنٮ۪ر پھٹان تہ اوٚبرہ چھہ شبنم پیوان۔\n21. میانہِ نیچو، تِم گژھ نہٕ پننہِ نظرِ نِش دور گژھُن: صحیح حکمت تہٕ صوابدید تھاوُن:\n22. یِتھٕ پٲٹھۍ گژھن تُہٕندِس روحس خٲطرٕ زندٕگی تہٕ تُہنزِ گردنہِ خٲطرٕ فضل آسن۔\n23. تیلہِ پٔکِو پَنٕنہِ وَتہِ پَکُن محفوٗظ پٲٹھۍ، تہٕ تُہٕندِس کھۄر گژھِ نہٕ ٹھوکر کھسنہٕ۔\n24.\\tییلہ تہِ ژیہ لوٚگِتھ روزِو، ژیہ گژھہِ نہ کھوژُن: آ، ژیہ گژھہِ شوٚنگتھ تہ نندر گژھہِ میٹھۍ۔\n25.\\tاچانک خوفہٕ سٍتـ̡ گژھہِ نہٕ خوفہٕ سٍتـ̡ تہٕ بدکارن ہٕنزِ ویرٲنی سٍتـ̡ کھوژُن۔\n26.\\tیِکیازِ خداوند گژھہِ تُہُند اعتماد تہٕ تھاوِ تُہٕندِس کھۅر رٹنہٕ نِش۔\n27.\\tتِمن نِش گژھِ نہٕ نیکی رُکاونہٕ یِمن ہُند واجب آسہِ، یێلہِ یہِ کرُن تُہٕندِس اتھس مَنٛز آسہِ۔ {تِم...: ہیب۔ امکۍ مٲلک}\n28.\\tپننِس ہمساین یہ نہ ونُن، گژھ تہٕ بییہ یِن، تہٕ پگہہ بہٕ دِیہ۔ ییلہ ژیہ یہ پانس سیتۍ آسہِ۔\n29.\\tپننِس ہمساین سٍتـ̡ کٔرِو نہٕ بُرٕچ سازش، یێلہِ سُہ چُھہ تۅہہِ سٍتـ̡ رٔسِتھ روزان۔ {Devise...: یا، کٔرِو نہٕ بُردی ہُند عمل کٔرِتھ}\n30.\\tکٲنسہِ شخصس سٍتـ̡ کٔرِو نہٕ بےٚ وجہ کوشش، اگر تٔمِس نہٕ تۅہہِ کانہہ نقصان واتنوومُت آسہِ۔\n31.\\tظالمس سٍتـ̡ کرو نہٕ حسد تہٕ تٔمۍ سٕندِس وتہٕ سٍتـ̡ ژٲرِو نہٕ۔ {ظالم: ہیب۔ تشددُک انسان}\n32.\\tبدکار سٍتـ̡ چُھہ خداوند سٕندِ خٲطرٕ ناپسندیدگی: مگر تٔمۍ سُند راز چُھہ صالحن سٍتـ̡ ۔\n33.\\tخداوند سُند لعنت چُھہ بدکارن ہٕندِس گرس مَنٛز، مگر سُہ چُھ نیک سٕندِس مکانس سٍتـ̡ برکت دِوان۔\n34.\\tیقینا چھُ سُہ طنز کٔرِتھ حقارت کران، مگر سُہ چُھ کمزورن ہٕندِس فضل دِوان۔\n35.\\tدانشمندَن میلہِ جلال مگر بیوقوفن ہٕنز ترقی گژھہِ شرم ۔ {گژھہِ...: ہیب۔ بیوقوفن ہٕنز بلندی دِیُن}","1. اے بچہٕ، مٲلۍ سٕنز ہدایت بوزو، تہٕ سمجھ زاننہٕ خٲطرٕ کرو حاضر۔\n2. تکیازِ بہٕ چُھس ژے اصل نظریہ دِوان، تہٕ میٲنۍ شریعت تراوُن نہٕ۔\n3.\\tکیازِ بہٕ اوسُس پننِس مٲلہِ سُند نیچو، نرم تہٕ وٲحِد پننہ ماجہ ہٕندِس نظرس منز۔\n4.\\tتٔمۍ ہیچھناوُن میہ تہِ، تہٕ وونُن زِ پنُن دِل تھاوُن میٲنۍ کلام: میٲنۍ حکمہٕ تھاوُن تہٕ زندٕ۔\n5. حکمت حٲصل کرُن، سمجھ حٲصل کرُن: {یہ} مٔشِد کرُن نہٕ؛ نہ تہِ چھہ میانہِ لفظہ نشہِ انکار۔\n6. أمِس گژھِ نہٕ تراوُن، تہٕ سُہ کرِ تۅہہِ رژھرُن: أمِس محبت کرُن، تہٕ سُہ تھاوِ ژےٚ رژھرٕ۔\n7. حکمت {چِھ} اہم چیز۔ {لہذا} کٔرِو حکمت: تہٕ پننہِ سارِنٕے حِصس سٍتـ̡ کٔرِو فہم حٲصِل۔\n8.\\tأمِس کٔرِو تٔمِس عزت، تہٕ سُہ کرِ تۅہہِ عزت، ییلہ تہٕ ژے أمِس گلے لگٲوِو۔\n9. سُہ دِیہِ تُہٕندِس کلَس فضل ہُند زیور: سُہ دِیہِ تۅہہِ ہُند تاج۔ {اکھ تاج...: یا سۅ کرِ ژیہ جلال ہُند تاج}\n10. اے میانہِ نیچو، بوزو تہٕ میٲنۍ کتھ قبول کرٕنۍ۔ تہٕ تۅہہِ ہٕندِ زندگی ہٕندِ ؤری آسن واریاہ ۔\n11. مے چھے ژے حکمت ہٕنزِ وتہِ سٍتـ̡ ہیچھناوٕنـ̡ ۔ مے چُھ ژے صحیح وتن پیٹھ نِمُت۔\n12.\\tییلہ ژیہ نیرِو، تۅہہِ گژھہِ نہ تُہند قدم رُکاونہٕ یُن۔ تہٕ ییلہ ژیہ ژلہِ، تیلہِ گژھہِ نہ ٹھوکر کھسنہِ۔\n13. ہدایتس پیٹھ رٔٹِو مضبوط۔ {أمِس} گژھ نہٕ گژھُن: سُہ تھاوُن۔ تکیازِ سۅ چھیہ تہنز زندگی۔\n14. بدکارن ہٕنزِ وتہِ منز گژھ نہٕ اژُن، تہٕ بد کار سٕنزِ وتہِ منز گژھ نہٕ۔\n15.\\tاَتھ نِش بچُن، اَتھ نِش گژھِو نہٕ پٔکِتھ، اَتھ نِش پھیُرِو تہٕ گزرُن۔\n16.\\tتِکیازِ تِم چھِ نہٕ شۄنگنہٕ یوان، یوٚت تام تِمو شرارت کٔرمٕژ آسہِ۔ تہٕ تِمن ہٕنزِ نِندٕر چھِ نِنہٕ یوان، یوٚت تام نہٕ تِم {کیٚنٛہہ} پیٚیہِ۔\n17.\\tتِکیازِ تِم چھِ بدکٲری ہٕنز روٹی کھیوان تہٕ تشددُک شراب۔\n18.\\tمگر صالحچ وتھ چھیہ چمکدار گاشکۍ پاٹھۍ یُس کامل دۅہس تام زیادٕ کھوتہ زیادٕ روشن سپدان چھہ۔\n19.\\tبدکار سُند وتھ چُھہ انہِ گٹہِ ہُند پٲٹھۍ: تِمن چھیہ نہ پتاہ زِ تم کیا ٹھوکر کھیوان۔\n20. میانہِ نیچو، میانہِ کلامَس پیٹھ توجہ دِیُن؛ میانین کتھن کُن کٔرِو کٔرِتھ۔\n21. تِم گژھن نہٕ تُہنزِ أچھن نِش دور گژھن۔ تِم تھٲوِو پنہٕ نِس دِلس منز۔\n22.\\tتکیازِ تِمن ہٕندِ خٲطرٕ چھِ زندگی تہٕ تِمن سارِنٕے مازس صحت بخشان۔ {صحت: ہیب۔ دوا}\n23. پَنُن دِل تھاوُن پوٗرٕ محنتہٕ سٍتـ̡ ۔ تکیازِ اتھ منز چھہِ زندگی ہندۍ مسلہ۔ {with...: Heb. سارِوٕے کھۄتہٕ زیادٕ تھاوُن}\n24.\\tژے نِش کٔرِو گٔژھ وُپھ تہٕ وُپھ وُٹھ ژٔٹِتھ ژٔٹِتھ دوٗر کٔرِتھ۔ {اکھ فراورڈ...: ہیب۔ ٲسٕچ شرارت تہٕ وٕٹھن ہٕنٛز خرابی}\n25.\\tپَنٕنۍ أچھ پَنٕنۍ أچھ وُچھِن تہٕ پَنٕنۍ أچھ ٹٲرۍ گژھن پانس برونہہ کُن نظر۔\n26.\\tپننین قدمن ہٕنزِ وتہِ پیٹھ غور کرُن، تہٕ پَنٕنـ̡ سارِنٕے وَتہٕ گٔژھِو قایم کرنہٕ۔ {چلُن...: نتہٕ چانہِ سارِنٕے وَتہٕ یِن صحیح ترتیب دِنہٕ}\n27.\\tدٔچِھنہِ اتھس کُن تہٕ نہ کھوورِ کُن پھیرُن: پَنُن کھوٚر ہٹٲوِو بد نِش ۔","1. میانہِ نیچو، میانہِ حکمتُک خیال تھاوُن، {تہٕ} میانہِ فہم کُن کٔرِو کَن:\n2.\\tتاکہ تۅہہِ کرِ صوابدید تہٕ تُہند وُٹھ روزِ علم۔\n3.\\tعجیب زنانہِ ہندِ چپنہِ پیٹھ تراوُن {as} شہد چھہ تہ ٲسس چھہ تیلہ کھۅتہ زیادہ نرم: {ٲس: ہیب۔ تالو }\n4.\\tمگر تٔمۍ سُند اند چھُ کۅکرِ ہیوٗ تلوار، دوٚن دھار تلوارِ ہیوٗ تیز۔\n5. تٔمۍ سٕندِ کھۅر چھِ مرنس تام گژھان۔ تٔمۍ سٕندۍ قدم چھِ جہنمس پیٹھ رٔٹان۔\n6.\\tزندگی ہنزِ وتہِ پیٹھ غور نہ کرُن، تمۍ سنزِ وتہِ چھیہ حرکت پذیر آسان، {یہ} ژیہ ہیکہِ نہ زانان {تِم}۔\n7. تَمہِ مۄکھٕ بوٗزِو، اے بچہٕ، تہٕ میانہِ کتھہٕ نِش گژھ نہٕ ہٹان۔\n8.\\tپنٕنۍ وَتھ ہٹٲوِو أمِس نِش، تہٕ گژھ نہٕ تٔمۍ سٕندِس گَرٕ کِس دروازس نزدیک۔\n9. یێلہِ کٔرِو پَنُن عزت، تہٕ پَنٕنـ̡ ؤری دِیہِ ظالمن سٍتـ̡ ۔\n10. یێلہِ گٔژھِو تُہٕندِس دولتس سٍتـ̡ بٔرِتھ بێیہِ۔ تہٕ تہنز محنت آسہٕ أکِس اجنبی سٕندِس گرس منز؛ {تُہند دولت: ہیب۔ تُہند طاقت}\n11.\\tتہٕ تُہُند ماز تہٕ تُہُند جسم کھٮ۪نہٕ وِزِ ٲخٕرِس مَنٛز ماتم کٔرِتھ،\n12.\\tتہٕ ونُن، میہ کِتھہ کٔنۍ چھُ ہدایتس سۭتۍ نفرت، تہٕ میٲنس دِلس کٔر ملامت نفرت۔\n13.\\tتہٕ کٔر نہٕ میانین استادن ہٕنزِ آوازِ ہٕنز فرمانبرداری، تہٕ نہ کٔر تِمن کُن کُن یِمو مےٚ ہیچھناوُن دِژمُت!\n14.\\tبہٕ اوسُس جماعت تہٕ مجلسس منز تقریباً سارِنٕے بُرِس مَنٛز۔\n15. پنہٕ نِس حوضہٕ منزٕ آب پییُن، تہٕ پننہِ کۅرٕ منزٕ آب پییُن۔\n16.\\tچانۍ چشمہ گژھن نیبر کُن پھہلاونہٕ، تہٕ سڑکن منز گژھن آبٕکۍ دریاو۔\n17.\\tتِم گژھن صرف پنٕنـ̡ تہٕ اَمہ سٍتـ̡ آسٕنـ̡ تہٕ تُہٕندِس سٍتـ̡ گٔژھِتھ تہٕ یێلہ\n18.\\tچانہِ چشمہٕ گژھہِ برکت تہٕ پننہِ جوانی ہٕنزِ زنانہِ سٍتـ̡ شاد۔\n19.\\t{سۅ گژھہِ پیاری ہِندِ تہٕ خۅش گُرِ ہٕندِس پٲٹھۍ﴾۔ تٔمۍ سٕندِس سینس کٔرِن پرٮ۪تھ ساتہٕ تسٕندِس سینس تسلی دِنہٕ۔ تہٕ تٔمۍ سٕندِس محبتس سٍتۍ روزُن ہمیشہٕ۔ {تسلی بخش...: ہیب۔ آب ژے} {بی تو...: ہیب۔ ژے چھکھ ہمیشہ تٔمۍ سٕندِس عشقس منز}\n20.\\tتہٕ ژے کیازِ کٔرِکھ أکِس اجنبی زنانہِ سٍتـ̡ رٔٹِتھ تہٕ أکِس اجنبی سٕندِس سینس رٔٹِتھ؟\n21.\\tانسان سٕنزِ وتہٕ چِھہ خداوند سٕنزِ نظرِ برونہہ کُن، تہٕ سُہ چُھ پنہٕ نِس سارِنٕے حرکتس پیٹھ غور کران۔\n22.\\tتٔمۍ سٕندِ بدکار سٍتـ̡ رٔٹِتھ تہٕ سُہ گژھہِ پننین گۅنہن ہٕنزِ رسہٕ سٍتـ̡ رٔٹِتھ رٔٹِتھ۔ {گناہ: ہیب۔ گۅناہ }\n23. سُہ گژھِ ہدایتٕ ورٲے مرُن۔ تہٕ پننہِ حماقت ہٕنزِ عظمتس منز گژھہِ سُہ گمراہ گٔژھِتھ۔","1.\\tمیانہِ نیچو، اگر ژیہ پننِس یارس سٍتۍ ضامن آسہِ، {اگر} ژیہ کٲنسہِ اجنبی سٍتۍ پنُن اتھہ مارمُت،\n2. ژے چُھکھ پننہِ ٲسٕکۍ کلامَن سٍتـ̡ پھسنہٕ آمُت، تہٕ ژے چُھکھ پننہِ ٲسٕچ کَلامَو سٍتـ̡ رٔٹِتھ ۔\n3. یێلہِ کٔرِو وۅنۍ یێلہِ پَنُن یارٕ سٕندِس اتھس منز یِنہٕ وِزِ پَنُن پان بچٲوِو۔ گژھ پنُن پان عاجز تہٕ پنُن یار۔ {تہٕ بناوُن...: یا، یِتھٕ پٲٹھۍ کٔرِو ژے پننِس یارس سٍتۍ}\n4.\\tپننہِ أچھن نِندٕرِ تہٕ نہ دِیُن أچھ ٹٲرۍ۔\n5.\\tشکارۍ سٕندِ اتھہٕ نِش کٔرِو پنُن پان رُکُن تہٕ جاناوار سٕندِ اتھہٕ نِش بچاوُن۔\n6.\\tکُنہِ تٔمۍ سٕندِس طٔریٖقَس پیٹھ غور کٔرِو، تہٕ بٔنِو\n7. یُس نہٕ رہنُما، نگران یا حکمران آسہِ،\n8.\\tریتہٕ کالہِ ماز فراہم کرُن، {تہٕ} فصلس مَنٛز کھٮ۪ن جمع کٔرِتھ۔\n9.\\tژیہ کوتاہ کالس چُھکھ شوٚنگتھ، اے سُست؟ ژیہ کر نیرِتھ نیرِتھ؟\n10.\\tرژھ رژھ نندر رژھ رژھ نندر رژھ\n11.\\tتۅہہ گژھہِ تۅہہِ غریبی یُس سفر کران آسہِ، تہٕ تۅہہِ ہٕندِس ہتھیار بند سٍتـ̡ یژھان۔\n12.\\tاکھ شرارتی شخص، اکھ بدکار انسان، چھہ بدکار ٲستھ پکان۔\n13.\\tسُہ چُھ أچھو سٍتـ̡ أچھ کٔرِتھ، سُہ چُھہ پننیو کھۅرو سٍتـ̡ کتھ کران، سُہ چُھ پننیو اونگجہِ سٍتـ̡ ہیچھناوان ۔\n14.\\tشرارت چھہ پننس دلس منز شرارت کران تہ سہ چھہ مسلسل شرارت کران۔ سُہ چُھ اختلاف پٲدٕ کران۔ {سوتھ: ہیب۔ کاسٹ فورتھ}\n15. تَمہِ مۄکھٕ گژھہِ تٔمۍ سٕنز آفت اچانک۔ اچانک گژھہِ سُہ پھُٹُن بغٲر علاج۔\n16.\\tیِم شیہ {چیز} چِھ خداوند نفرت: آ، ستھ {چِھ} أمِس خٲطرٕ اکھ مکروہ کُن: {to...: Heb. تٔمۍ سٕندِس روحُک }\n17.\\tاکھ فخر نظر، اکھ اپُز زبان تہٕ اتھہٕ یُس معصوم خون تراوان چھُ، {اکھ فخر...: ہیب۔ مغرور أچھ}\n18.\\tاکھ دِل یُس شرارت کُن دِوان چھُ، کھۅر یُس شرارت کُن دوڑان چھُ،\n19.\\tاکھ اپُز گواہ {یُس} چُھ اپُز بولان تہٕ یُس بٲے درمِیان اختلاف کران چُھ۔\n20. میانہِ نیچو، پننِس مٲلہِ سُند حُکُم تھاوُن تہٕ پننہِ ماجہ ہُند قانون تراوُن نہٕ:\n21.\\tیِم تھٲوِو پننِس دِلس سٍتـ̡ گٔنڈِتھ، {تہٕ} گٔنڈِو پننہِ گردنہِ سٍتـ̡ ۔\n22. ییلہ ژیہ نیرِ، سُہ کرِ تۅہہِ نِش۔ ییلہ ژیہ نندر آسہِ، یہ روزِ ژیہ رژھرتھ۔ تہٕ {ییلہ} ژیہ بیدار گژھہِ، یہ کرِ توے سٍتۍ کتھ کرنہٕ۔\n23.\\tحکم {چُھ} چُھہ شمع۔ تہٕ قانون {چُھ} گاش؛ تہٕ ہدایتٕچ ملامت {چِھ} طرز زندگی: {چراغ: یا، شمع}\n24.\\tژے بد زنانہِ نِش بچاوُن، أکِس اجنبی زنانہِ ہٕنزِ زبانہِ ہٕنزِ خوشامد نِش۔ {منز...: یا، عجیب زبانہِ}\n25.\\tپننہِ دِلس منز گژھ نہ تٔمۍ سٕنزِ خوبصورتی ہٕنز ہوس کٔرِتھ۔ نہ گژھہِ سۅ اچھ ٹٲرۍ سیتۍ نِن۔\n26.\\tیِکیازِ زَن زنانہٕ سٍتـ̡ چُھہ مردس سٍتـ̡ روٹی ہٕندِس ٹُکرس سٍتـ̡ اننہٕ یِوان: تہٕ زٲنِہ کرِ قیمتی زُوٕ خٲطرٕ شکار۔ {زناکار: ہیب۔ مردٕ سٕنز زنانہٕ، یا مردٕ سٕنز زنانہٕ}\n27.\\tکیا انسان ہیکہِ پننِس سینس منز نار نِتھ، تہٕ پلو گژھِ نہٕ زالنہٕ؟\n28.\\tکیا کٲنسہِ ہیکہِ تپنہٕ سٍتـ̡ تٔمِس کھورِ سٍتـ̡ زالنہٕ یِتھ؟\n29.\\tیُس ہمسایہ سٕنزِ زنانہِ نِش گژھِ۔ یُس تہِ أمِس اَتھٕ لاگہِ سُہ گژھِ نہٕ معصوم۔\n30.\\t{انسان} چھہ نہ چورس حقارت کران، اگر سہ بھوک آسنہ وِزِ پننہِ روح مطمئن کرنہ خاطرہ ژورِ نِتھ۔\n31.\\tمگر اگر سُہ لبنہٕ ییہِ، سُہ گژھہِ سَتھ گنہٕ بحال کرنہٕ۔ سُہ دِیہِ پنٕنِس گرُک سورُے سامان۔\n32.\\t{مگر} یُس زنانہِ سٍتـ̡ زنا کران چُھ، سُہ چُھ نہٕ سُہ پانس سٍتـ̡ تباہ کٔرِتھ۔ {سمجھ: ہیب۔ دِل}\n33.\\tتس گژھہِ زخم تہٕ بے عزتی میلہِ۔ تہٕ تٔمۍ سُند ملامت گژھِ نہٕ مٹاونہٕ۔\n34.\\tحسد چھہ انسان سُند غصہ تہ لہذا روزِ نہ سُہ انتقام کس دۅہس منز بخشان۔\n35. سُہ کرِ نہٕ کُنہِ تہِ فدیہ ہُند خیال ۔ نہ روزِ سُہ مطمئن، حالانکہ ژے واریاہ تحفہٕ دِتھ۔ {سُہ کرِ...: ہیب۔ سُہ کرِ نہٕ کُنہِ تہِ رِعایہ ہُند بُتھ قبول}","1. میانہِ نیچو، میٲنۍ کلام تھاو تہٕ میٲنۍ حُکُم تھاوُن پانس سٍتـ̡ ۔\n2. میٲنۍ حُکُم تھاوٕن، تہٕ زندٕ روزُن؛ تہٕ میون قانون چُھس چانہِ اچھن ہُند تارٕ پٲٹھۍ۔\n3.\\tتِم تھٲوِو پننہِ اونگجہِ پیٹھ، لیکھِو پننہِ دِل کِس میزس پیٹھ۔\n4.\\tحکمتس وَنُن، تہٕ چُھہ میانہِ بینہِ ہٕندِس سٍتـ̡ تہٕ وَنُن سمجھُن {پنُن} رشتہٕ دار:\n5.\\tتاکہ تِم تھاوَن تۅہہِ اجنبی زنانہِ نِش، یُس تٔمۍ سٕندِس کلامَس سٍتۍ خوشامد کران چھُ۔\n6.\\tتکیازِ میہ کٔر پننہِ مکانہ چہ دارِ پیٹھ نظر،\n7.\\tتہٕ وُچھِتھ وُچھ میہ نوجوانَن مَنٛز اکھ نوجوان یُس سمجھ نِش خالی اوس، {نوجوان: حب۔ سنز}\n8. تٔمۍ سٕندِس کونس نکھٕ سڑکہٕ کِنۍ گزرُن۔ تہٕ سُہ گوٚو أمۍ سٕندِس مکانس کُن وَتھ،\n9.\\tشامس منز، سیاہ تہٕ سیاہ رٲژ منز: {شام: ہیب۔ دۅہن ہٕندِس شامس منز}\n10.\\tتہٕ وچھ أمِس سمکھے اَکھ زنانہٕ یُس فاحشہِ ہُند لباس، تہٕ دِل ہُند لطیف۔\n11.\\t(سۅ چھیہ بَڑِ تہٕ ضد کٔرِتھ، تٔمۍ سٕندِس گَرَس مَنٛز چھُنہٕ تٔمۍ سٕندِس قدمن ہُند روزُن:\n12.\\tوۅنۍ چھیہ سۅ نیبر، وۅنۍ سڑکن منز، تہ پریتھ کونس پیٹھ پیار۔)\n13.\\tتہ تس رٔٹتھ تہ بوسہ دِژُن، {تہِ} گستاخ بُتھس سٍتۍ وونُن أمس {سٍتۍ...: ہیب۔ تمۍ کٔر پنن بُتھ مضبوط تہ وونُن}\n14.\\t{میہ سٍتـ̡ چُھہ امن ہٕنز پیشکش۔ اَمہِ دۄہ کوٚر مےٚ پنُن عہد پورٕ۔ {میہ چُھ...: ہیب۔ امنٕچ پیشکش چھِ میہ پیٹھ}\n15. تێمہِ کِنۍ آو بہٕ ژےٚ مِلنہٕ خٲطرٕ، تُہند بُتھ ژھارنہٕ خٲطرٕ، تہٕ مے لوٚب ژے ۔\n16.\\tمیہ چھُ پنُن بسترٕ ٹیپسٹری سٍتۍ سجٲومُت، مصرٕکۍ عمدہ کُنہِ کُنہِ سٍتۍ۔\n17.\\tمیہ کٔر پننِس بسترس مِر، ایلو تہٕ دالچیٖن سٍتۍ خوشبو۔\n18.\\tآو، اسہِ کرو صبحس تام پنُن محبتہ پورُن: اسۍ کرو محبتو سٍتۍ تسلی دِوان۔\n19. نیک انسان سٕندِ خٲطرٕ چُھ نہٕ گَرِ منز، سُہ چُھ اکھ زیوٹھ سفر:\n20.\\tأمِس نِش چُھ پونسہٕ ہُند اکھ بیگ نِمُت، {تہٕ} مُقرر کرنہٕ آمُت دۅہہٕ گَرٕ یِیہِ۔ {with...: Heb. تٔمۍ سٕنٛدس اتھس منٛز} {دۅہ...: یا، نٔو زونہٕ}\n21.\\tپننہِ سیٹھا منصفانہ کتھِ سٍتۍ کٔر أمس ہتھیار تہ وٹھن ہنز خوشامد کٔرِتھ کٔر تس مجبور۔\n22.\\tسُہ چُھ أمِس پَتہٕ سیوٚد پَتہٕ نیران، یِتھٕ پٲٹھۍ بیل ذبح کُن گژھان چُھ، یا بیوقوف سٕندِس پٲٹھۍ، ذٲژ ہٕنزِ اصلاح کُن چھُ۔ {سیدِ وے: ہیب۔ اچانک}\n23. یوٚت تام تٔمۍ سٕندِس جگرس منز اکھ ڈارٹ ٹاس دِنہٕ۔ یتھہ پاٹھۍ اکھ جاناوار چھہ جالس منز جلدی کران تہ یہ چھہ نہ زانان زِ یہ چھہ تسنزِ زندگی ہندِ خاطرہ۔\n24. تَمہِ کِنۍ کٔرِو میانہِ کتھ بوزو، اے بچہٕ، تہٕ میانہِ کتھِ ہٕندِس کلامَس سٍتـ̡ توجہ دِیُو۔\n25. پَنُن دِل گژھِ نہٕ تٔمۍ سٕنزِ وَتہِ کُن گٔژھِتھ، تٔمۍ سٕنزِ وَتہِ مَنٛز گژھِ نہٕ گَژھنہٕ۔\n26. تکیازِ تٔمۍ چھِ واریاہ زخمی: آ، واریاہ مضبوٗط {مرد} چھِ أمِس مارنہٕ آمٕتۍ۔\n27. تٔمۍ سُند گرٕ چُھ جہنمٕچ وَتھ، یُس موت کِس کمرس تام واتان چُھ۔","1. کیا حکمت چھے نہٕ رووان؟ تہٕ سمجھ دِژ تٔمۍ سٕنز آواز؟\n2.\\tسۅ چھیہ تھدٮ۪ن جاین پیٹھ کھڑا روزان، وتہِ وتہِ پیٹھ۔\n3.\\tسۅ چھے دروازن پیٹھ، شہرس منز اژنس پیٹھ، دروازن پیٹھ اژنس پیٹھ رووان۔\n4. اے انسان، بہٕ چُھس بلاوان۔ تہٕ میٲنۍ آواز {چُھ} انسان سٕندِس فرزندس تام۔\n5.\\tاے سادہ سادٕ، عقل سمجِو: تہٕ بیوقوفو، تم گژھو سمجھن وٲلِس دِلٕچ دِل۔\n6. بوزُن؛ تکیازِ بہٕ کرٕ بہترین چیزن ہنز کتھ کرنہٕ۔ تہٕ میانہِ چپنہِ کھُلُن {گژھہِ} صحیح چیز۔\n7. تکیازِ میانہِ ٲسس گژھہِ پزر کتھ کرنہٕ۔ تہٕ بدکاری چھیہ میانین وٹھن پیٹھ اکھ مکروہ ۔ {an...: Heb. میانہِ چپنہِ ہنز نفرت\n8.\\tمیانہِ زبانہِ ہندۍ سٲری لفظ چھہِ نیکی منز؛ {یِمَن مَنٛز چھُنہٕ کانٛہہ تہِ گڑبڑ یا غلط فہم۔ {فراورڈ: ہیب۔ گلدست}\n9. تِم چھِ تٔمِس سٍتـ̡ سیدِ سیدِ سٍتـ̡ یُس سمجھان چُھ، تہٕ تِمن ہٕندِ خٲطرٕ چُھ صحیح۔\n10. میٲنۍ تعلیم حٲصل کرٕن، رۄپہٕ نہٕ۔ تہٕ سۄنہٕ بجایہ علم۔\n11. حکمت {چُھ} یاقوت کھوتہٕ بہتر۔ تہٕ یمن سارِنٕے چیزن ہُند موازنہٕ گژھِ نہٕ اتھ سٍتۍ کرنہٕ یُن۔\n12. بہٕ چُھس دانشمندی سٍتۍ روزان، تہٕ مزاحیہ ایجاداتن ہُند علم حٲصل کٔرِتھ۔ {دانشمند: یا، باریک}\n13.\\tخداوند سُند خوف چُھہ بدی سٍتـ̡ نفرت: غرور، تکبر، تہٕ بد وتہٕ، تہٕ بدکار ٲس، بہٕ چُھس نفرت۔\n14.\\tمشورٕ {is} میون تہٕ صحیح حکمت: بہٕ چُھس {چُھ} سمجھان۔ میہ چھیہ طاقت۔\n15.\\tمیانہِ ذریعہٕ چھِ بادشاہن ہٕندِ حُکوٗمت تہٕ شہزادٕ چھِ انصاف دِوان۔\n16. میانہِ ذریعہٕ چھِ شہزادن ہٕنز حکوٗمت، تہٕ رئیس، {حتیٰ کہ} زمینہٕ کِس سارِنٕے قاضیَن ہٕندِس سٍتـ̡ ۔\n17. بہٕ چُھس تِمن سٍتـ̡ محبت کران یُس میہ محبت کران چُھ؛ تہٕ یِم مےٚ سُلی ژھانڈان چھِ، تِم چھِ مےٚ ژھانڈان۔\n18.\\tدولت تہٕ عزت﴾ چُھس میہ سٍتـ̡ {آ}، پایدار دولت تہٕ نیکی ۔\n19.\\tمیون پھل {چُھ} سۄنہٕ کھۅتہٕ بہتر، آ، عمدہ سۄنہٕ کھۅتہٕ بہتر۔ تہٕ میون آمدنی، ژٲر رۄپہٕ۔\n20. بہٕ چُھس نیکی ہٕندِس وتہِ پى۪ٹھ، فیصلہٕ کِس وتہِ منز: {لیڈ: یا، پَکُن}\n21. یُتھ بہٕ کرٕ تِمن لوکن ہُند وراثت حٲصِل کٔرِتھ یُس مےٚ محبت کران چھُ۔ تہٕ بہٕ کرٕ تِہُند خزانہٕ بٔرِتھ۔\n22. خداوند اوس میہ پننہِ وتہِ ہندس آغازس منز، پرانہِ کامہِ برونہہ کُن۔\n23. بہٕ اوسُس ازل پیٹھٕ قٲیم کرنہٕ آمُت، شروع پیٹھٕ، یا کُنہِ تہِ زمینہٕ ٲس۔\n24.\\tییلہ نہ کانہہ گہرایی ٲس، میہ آو برونہہ کُن اننہ۔ ییلہ {اتہِ} آسہِ نہٕ آبہٕ سٍتۍ بٔرِتھ چشمہٕ۔\n25. پہاڑ آباد گژھنہٕ برونہہ، بالہٕ برونہہ کُن آو بہٕ:\n26. ییلہ زن وُنیُک تام اوس نہ تٔمۍ زمین، نہ کھیت تہٕ نہ دنیاہٕچ گردِ ہُند تھوٚد حصہٕ بنٲومُت۔ {فیلڈ: یا، اوپن پلیس} {ساروی کھوتہٕ زیادٕ...: یا، اہم حصہٕ}\n27.\\tییلہ تمۍ آسمانس تیار کٔر، میہ اوس تتہِ: ییلہ تمۍ سرٛنٮس بُتھس پیٹھ کمپاس تھوو: {اکھ کمپاس: یا، اکھ دٲیر}\n28.\\tییلہ تٔمۍ ہیرِ کُن اوٚبر قایم کٔرِتھ: ییلہ تٔمۍ سرٛونٕکۍ چشمہٕ مضبوٗط کٔرۍ:\n29.\\tییلہ تٔمۍ سمندرس پنُن حکم دِیُت زِ آبس گژھہِ نہٕ تٔمۍ سُند حکم دِنہٕ:\n30. اَمہ پتہٕ اوسُس بہٕ أمِس سٍتـ̡ پرورش کٔرِتھ، تہٕ بہٕ اوسُس دۅہہٕ خۅش سپدان تہٕ أمِس برونہہ کُن خۅش سپدان۔\n31. پننہِ زمینہِ ہٕندِس قٲبلِ رہٲیشی حصس مَنٛز خۅش گژھُن۔ تہٕ میٲنۍ خوشی ٲس انسانن ہٕندٮ۪ن نیٚچوٮ۪ن سٍتۍ۔\n32.\\tتێلہِ کٔرِو میانہِ کتھہِ بوزو، اے بچہٕ، تکیازِ تم چھہِ میانہِ وتہِ رژھراوان چھِ۔\n33.\\tہدایت بوزِو، تہٕ عقلمند روزُن، تہٕ اَتھ کٔرِو نہٕ انکار کرنہٕ۔\n34.\\tبابرکت چھہ سُہ انسان یُس میہ بوزان چھُ، روزانہٕ میانین دروازن پیٹھ وچھان، میانین دروازن پیٹھ انتظار کران چھُ۔\n35. یُس تہِ میہ لبان چُھ، سُہ چُھ زندگی میلان تہٕ خداوند سُند فضل حٲصل کرِ۔ {حاصل: ہیب۔ برونہہ کُن انُن}\n36. مگر یُس میانہِ خلاف گناہ کران چُھ، سُہ چُھ پننِس روحس سٍتـ̡ ظلم کران: یُس میہ سٍتـ̡ نفرت کران چُھ، تم چِھ موتس محبت کران۔","1. حکمتَن چھُ پنُن گرٕ بنوومُت، تٔمۍ چھِ پنٕنۍ سَتھ تھَم ژٔٹِمٕژ:\n2. تٔمۍ کٔر پَنٕنۍ درندٕ مٲرِتھ۔ تٔمۍ کٔر پنٕنۍ شراب۔ تمۍ چھہ پنن ٹیبل تہِ سجٲومُت۔ {تٔمۍ سٕندِس درندٕ: ہیب۔ تٔمۍ سُنٛد قتل}\n3. تٔمۍ سوزمٕژ پَنٕنہِ کورِیہِ، سُہ چُھ شہرٕ کِس تھزرس پیٹھ فریاد کران،\n4.\\tیُس تہِ سادہ آسہِ، سہ گژھہِ یور پھیُرُن: یُس سمجھ یژھان چھُ، سۅ چھیہ تس ونان\n5.\\tآ، میٲنۍ روٹی کھیوٚو تہٕ شرابُک پییہِ {یُس} یُس میہ رٔلِتھ چُھس۔\n6. بیوقوفن ترٲوِو تہٕ زندٕ روزُن؛ تہٕ سمجھنہٕ کِس وتہِ منٛز گژھُن۔\n7. یُس بدکار ملامت کران چُھ، سُہ چُھ پانس شرم کٔرِتھ، تہٕ یُس بدکار سُند ملامت کران چُھ، سُہ چُھ پانس بدنام کران۔\n8.\\tأکِس طنزس کٔرِو نہٕ ملامت کرنہٕ، متان، سُہ کرِ تۅہہِ سٍتـ̡ نفرت: أکِس دٲنِس نفرس کٔرِو ملامت تہٕ سُہ کرِ ژےٚ محبت۔\n9.\\tأکِس عقلمند {انسان} دِیُن {ہدایت}، تہٕ سُہ گژھہِ وُنہِ تہِ عقلمند: أکِس عادل {انسان} ہیچھناوُن، تہٕ سُہ گژھہِ ہیچھنس منز ہُریر۔\n10. خداوند سُند خوف چُھ حکمتُک آغاز: تہٕ پاک سُند علم چُھ سمجھ۔\n11. تکیازِ میانہِ ذریعہٕ گژھن چانۍ دۅہ بڑاونہٕ، تہٕ چانہِ زندگی ہٕندۍ ؤری گژھن بڑاونہٕ۔\n12.\\tاگر ژیہ عقلمند آسہِ، تیلہِ گژھہِ پننہِ خاطرہ عقلمند روزُن، مگر {یێلہ} توے حقارت کٔرِو، تیلہِ گژھہِ تۅہہ صرف یہ برداشت کرُن۔\n13.\\tاکھ بیوقوف زنانہِ چھیہ شرارت کران: {سۅ چھیہ} سادہ تہ کانہہ زان چھیہ نہ۔\n14.\\tتکیازِ سۅ چھیہ پننہِ مکانہ کس دروازس پیٹھ بِہتھ، شہر کین تھزرن پیٹھ اکس نشستس پیٹھ،\n15. تِم مسافرَن فون کَرُن یِم پَنٕنہِ وَتہِ پَکان چھِ:\n16.\\tیُس تہِ سادہ آسہِ، سُہ گژھہِ یور پھیُرُن: تہٕ یُس سمجھ یژھان چھُ، سُہ چھُ أمِس وَنان۔\n17. ژوٗرِ نِنہٕ آمُت آب چُھ موٚدُر تہٕ روٹی چُھ خۅش آسان۔ {کھیوٚن...: ہیب۔ آف سیکریس}\n18.\\tمگر تس چھہ نہ پتاہ زِ مرُن چھہ تتہِ۔ {تہٕ یہ} تٔمۍ سٕندۍ مہمان {چھِ}جہنم کِس گہرایی منٛز۔","1. سلیمان سٕندۍ محاورٕ۔ عقلمند نیچو چھہ خۅش مول بناوان، مگر بیوقوف نیچو چھہ ماجہ ہند وزن۔\n2. بدکاری ہٕندِ خزانہٕ سٍتـ̡ چُھہ نہٕ کانہہ فٲیدٕ دِوان: مگر نیکی چُھ موتہٕ نِش نجات دِوان۔\n3. خداوند کرِ نہٕ صالحن ہٕندِس روحس فاقہٕ کُن دِنہٕ، مگر سُہ چُھ بدکارن ہُند مال ضایع کران۔ {مادہ...: یا، بدکار پننہِ بدکاری خٲطرٕ}\n4. سُہ چُھ غریب بنان یُس سُہ سُند اَتھٕ سٍتـ̡\n5.\\tیُس ریتہٕ کالہِ منز جمع سپدان چُھ، سُہ چُھ عقلمند نیچو: {مگر} یُس فصلس منز شوٚنگان چُھ، سُہ چُھ سُہ نیچو یُس شرمندگی ہُند سبب بنان چُھ۔\n6.\\tدُعا چھُ نیک سٕندِس کلس پیٹھ: مگر بدکارن ہٕندِس ٲسس پیٹھ چھُ تشدد آسان۔\n7.\\tنیک سُند یاداشت چھُ بابرکت مگر بدکار سُند ناو گژھہِ سڑُن۔\n8.\\tدِلس منز دِلہٕ وٲلِس دِلہٕ سٍتـ̡ حُکُم میلہِ، مگر یێلہِ پۯاوُن بیوقوف پۯاوُن۔ {اکھ پرٹینگ...: ہیب۔ اکھ بیوقوف} {فال: ہیب۔ مارنہٕ یِن}\n9.\\tیُس سیدِ پٲٹھـ̡ پکان چُھ، سُہ چُھ یقینا پکان سُہ چُھہ پٲٹھـ̡ پٲٹھـ̡ پکان مگر یُس پنہٕ نـ̡ وتہٕ پھیران چُھہ سُہ گژھہِ زاننہٕ یِوان۔\n10.\\tیُس أچھ سٍتـ̡ اچھ دِوان چُھہ سُہ دکھ دِوان: مگر یُس بیوقوف پۯاوُن۔ {زوال: ہیب۔ مارنہٕ یِن}\n11.\\tنیک انسان سُند ٲسُن چُھ زندگی ہُند کۅرُن، مگر بدکارن ہٕندِس ٲسس منز چھُ تشدد آسان۔\n12.\\tنفرتس سٍتـ̡ چُھہ کشمکش پٲدٕ کران: مگر محبتہٕ چُھ سارِنٕے گۅناہ ہُند احاطہ کران۔\n13.\\tیُس سمجھ آسہِ تٔمِس سٕندِس وَٹھس مَنٛز چھُ حکمت لبنہٕ یِوان، مگر تٔمِس سٕندِس کمرس خٲطرٕ چھُ اکھ لٔر یُس سمجھ نِش خالی آسہِ۔ {تفہیم: ہیب۔ دِلُک}\n14.\\tعقلمند {انسان} چھہ علم تھاوان: مگر بیوقوفن ہند اوس اوس تباہی نزدیک۔\n15. امیر سُند دولت {چُھ} تٔمۍ سُند مضبوط شہر: غریبن ہٕنز تباہی {چِھ} تِہنز غربت۔\n16.\\tنیک سٕنزِ محنت: بدکارن ہُند پھل گۅنہٕ کُن۔\n17.\\tسُہ چُھ زندگی ہٕندِس طریقس منز یُس ہدایتُک عمل تھاوان چُھ، مگر یُس انکار کران چُھ، سُہ چُھ غلطی کران۔ {erreth: or, causeth to error}\n18.\\tیُس نفرتُک دَرٕ ژوٗرِ تھاوان چُھ، تہٕ یُس بہتان کٔرِتھ چھُ، سُہ چُھ بیوقوف۔\n19.\\tلفظن ہٕندِس کثرتس مَنٛز چُھنہٕ کانہہ گۅناہ یژھان، مگر یُس پنہٕ نِس وَٹھ رُکٲوِتھ چُھہ سُہ چُھ عقلمند آسان۔\n20.\\tعادل سٕنز زبان چُھہ ژٲر رۄپہٕ: بدکار سُند دِل چُھ کم قٲبل۔\n21.\\tنیک سٕندِ وٕٹھ چھِ واریاہن ہُند کھٮ۪وان مگر بیوقوف چھِ دانشمندی ہٕندِ کٔمی سٍتـ̡ مران۔ {حکمت: ہیب۔ دِلُک}\n22. خداوند سٕنز برکت چھے امیر بناوان، تہٕ سُہ چُھہ نہٕ اتھ سٍتـ̡ کانہہ غم تہِ دِوان۔\n23.\\tیہ چھہ بیوقوفس شرارت کرُن کھیل مگر سمجھدار انسان چھہ دانایی آسان۔\n24.\\tبدکارن ہُند خوف گژھہِ تس سٍتـ̡ یێلہِ بێیہِ تہٕ نیکوکارن ہٕنز خواہش ییہِ پورٕ کرنہٕ۔\n25.\\tیُتھ واو پکان چُھ، تِتھے پٲٹھـ̡ چُھہ بدکار تہِ {زیادٕ} بێیہِ بێیہِ {زیادٕ} مگر نیک {چُھ} اکھ ابدی بنیاد۔\n26.\\tیتھے پاٹھۍ چھہ دندن تہ اچھن ہند دھوکہ، تتھے پاٹھۍ چھہ سُہ سوزان تہِ۔\n27.\\tخداوند سُند خوف چُھ دۅہن زیٹھراوان مگر بدکارن ہٕندِ ؤری گژھن کم کرنہٕ۔ {طوالت: ہیب۔ addeth}\n28.\\tنیک سنز وۅمید گژھہِ خوشی، مگر بدکارن ہنز وۅمید گژھہِ ختم۔\n29. خداوند سُند وتھ چُھہ سیدِ سٍتـ̡ قوت، مگر بدکارن ہٕندِ خٲطرٕ گژھہِ تباہی۔\n30. نیکوکار گژھِ نہٕ زانہہ ہٹاونہٕ، مگر بدکار گژھِ نہٕ زمینس منز روزُن۔\n31.\\tعادل سٕندِ ٲسِس سٍتـ̡ چُھہ حکمت پٲدٕ کران، مگر بدکار زبان گژھہِ ژٹنہٕ یِنـ̡ ۔\n32.\\tنیکن ہٕندِس چپنہٕ سٍتـ̡ چُھہ زانان زِ بدکار سٕندِس ٲسس چُھہ بد اخلاقی کتھ کران۔ {frowardness: Heb. شرارت}","1.\\tاکھ اپُز توازن {چُھ} خداوند سٕندِ خٲطرٕ مُنفرت: مگر اکھ عادل وزن {چُھ} تٔمۍ سٕنز خوشی۔ {اکھ غلط...: ہیب۔ دھوکہ دہی ہند توازن} {صرف...: ہیب۔ کامل پتھر}\n2.\\tییلہ غرور سپدِ، تیلہِ چھہ شرم یوان: مگر حقیر {چُھ} دانایی سٍتۍ۔\n3.\\tنیک سٕنز دیانت دِیہِ تِمن ہٕنز رہنمایی مگر نافرمان سٍتـ̡ گٔیہِ تِمن تباہ کرنہٕ۔\n4. غصہٕ کِس دۅہس منز چُھنہٕ دولتُک فٲیدٕ حٲصل سپدان، مگر نیکی چِھ موتہٕ نِش نجات دِوان۔\n5.\\tکامل سٕنز نیکی کرِ تٔمۍ سٕنزِ وتہِ ہدایت: مگر بدکار گژھہِ پننہِ بدکاری سٍتـ̡ پنہٕ نِس سٍتـ̡ پنہٕ نِس وتہٕ سٍتـ̡ پنہٕ نِس وتہٕ سٍتـ {ڈایریکٹ: ہیب۔ rectify}\n6.\\tنیک سٍتـ̡ دِیہِ تِمن نجات دِنہٕ، مگر نافرمان گژھن شرارتس سٍتـ̡ رٔٹنہٕ۔\n7.\\tییلہ بدکار انسان مران چُھ، {تٔمِس} وۅمید گژھہِ ختم: تہٕ ناانصافی سٕنز وۅمید ختم گٔیہِ۔\n8. نیک چُھ مصیبت نِش نجات دِنہٕ یوان، تہٕ بدکار چُھ أمِس بدلہٕ یوان۔\n9.\\tمنافق چُھ پننِس ہمساین تباہ کران: مگر علمہٕ سٍتـ̡ گژھہِ عادل نجات دِنہٕ۔\n10.\\tییلہ یہِ نیکوکارن سٍتـ̡ رژھ\n11.\\tراست سٕنزِ برکت سٍتـ̡ چُھ شہر تھزراونہٕ یوان، مگر یہِ چُھ بدکارن ہٕندِ ٲسِس سٍتـ̡ ختم سپدان۔\n12.\\tیُس عقل نِش خالی چُھ، سُہ چُھ پننِس ہمساین سٍتـ̡ حقارت کران: مگر سمجھدار سُہ چُھ پَنُن سکوُن تھاوان۔ {خٲلی...: ہیب۔ دِلُک بے سہارا }\n13.\\tافسانہ نگار چھہ راز فاش کران، مگر یُس وفادار روح آسہِ سہ چھہ یہ معاملہ ژوٗرِ تھاوان۔ {اکھ افسانہٕ نگار: ہیب۔ یُس پکان چُھ، افسانہٕ نگار آسنہٕ کِنۍ}\n14.\\tییتہِ نہٕ کانہہ وکیل {چُھ}، لُکھ چھُ پٮ۪وان: مگر مشیرن ہٕندِس تعدادس مَنٛز چُھ حفاظت۔\n15.\\tیُس اجنبی سٕندِ خٲطرٕ ضامن آسہِ، سُہ گژھہِ ہوشیار تہٕ یُس ضمانتس سٍتـ̡ نفرت کرِ، سُہ چُھ پَکہٕ پٲٹھۍ۔ {سمارٹ: ہیب۔ دَگ پھُٹُن} {ضمانت: ہیب۔ یِم اَتھٕ ماران چھِ}\n16.\\tاکھ مہربان زنانہ چھیہ عزت برقرار تھاوان: تہٕ مضبوط {مرد} چھہ دولت برقرار تھاوان۔\n17. رحم دل انسان چُھ پننِس روحس سٍتـ̡ خیر کٔرِتھ، مگر یُس ظالم چُھہ پننِس مازس سٍتـ̡ دِوان۔\n18.\\tبدکار چھہ دھوکہ دہی کٲم کران، مگر یُس نیکی دِوان آسہِ سہ گژھہِ یقینی انعام۔\n19.\\tیِتھے پٲٹھـ̡ یُس بدی ہُند تعاقب کران چُھ، سُہ چُھ پننِس مرنس تام۔\n20. یِم دِل دِل چِھہ خداوند سٕندِ خٲطرٕ مکروہ آسان، مگر {یِتھ﴾ یِمن ہٕندِس طریقس سٍتـ̡ سیدِ سٍتـ̡ چِھہ تٔمۍ سٕنزِ خوشی ہٕندِس سٍتـ̡ ۔\n21. {اَتھٕ سٍتـ̡ {رٔلِتھ} اَتھٕ سٍتـ̡ گژھہِ نہٕ بدکارن سٍتـ̡ سزا دِنہٕ یُن، مگر نیکوکارن ہُند بیول ییہِ نجات دِنہٕ۔\n22.\\tسور سٕندِس ناورس منز سۄنہٕ سُند جوہر، {تِتھے پٲٹھۍ} چھے اکھ گور زنانہٕ یۄس نہٕ صوابدید آسہِ۔ {بغیر: ہیب۔ روانہٕ گٔیہ}\n23.\\tصالحن ہنز خواہش چھیہ صرف اصل: {مگر}بدکار سنز وۅمید چھیہ {چھہ} قہر ۔\n24. سُہ چُھ بکھرِتھ تہٕ توتہِ چُھ ہُران۔ تہٕ {تتہِ} چُھ یُس پورٕ کھوتہٕ زیادٕ روکُن چُھ، مگر {یہٕ چُھ} غریبی کُن رُکاونہٕ یوان۔\n25.\\tفراخ دل روح گژھہِ موٹۍ بناونہ یُن: یُس آب دِوان چھُ، سہ گژھہِ پانس تہِ آب دِنہٕ۔ {لبرل...: ہیب۔ برکت ہُند روح}\n26.\\tیُس مَکُل رُکٲوِتھ، سُہ کرِ أمِس لعنت، مگر یُس کٕننہٕ وٲلِس سٕندِس کلس سٍتـ̡ دُعا دِنہٕ آسہِ۔\n27. یُس محنت سان نیکی ژھاران چُھ، سُہ چُھ احسان حٲصل کران، مگر یُس شرارت ژھاران چُھ، سُہ گژھہِ أمِس نِش واتہٕ۔\n28.\\tیُس پننِس دولتس پیٹھ بھروسہٕ کرِ، سُہ گژھہِ پنہٕ نِس دولتس پیٹھ بھروسہٕ کرُن، مگر نیک گژھہِ اکہِ لُکہِ ہٕندِس پٲٹھۍ۔\n29.\\tیُس پننِس گرس پریشان کرِ، سُہ گژھہِ واو ہُند وٲرث: تہٕ بیوقوف آسہِ دِل دِل دِل سُند خادم۔\n30. نیک سُند پھل چُھ زندگی ہُند کُل؛ تہٕ یُس روح زینان چُھ، سُہ چُھ دانشمند۔ {ونیتھ: ہیب۔ taketh}\n31.\\tوچھو صالحن ہُند بدلہٕ میلہِ زمینس مَنٛز: بدکار تہٕ گۅنہگار تہٕ زیادٕ زیادٕ۔","1.\\tیُس یُس تعلیم پسند کران چُھ، سُہ چُھ علمس محبت کران: مگر یُس ملامت سٍتـ̡ نفرت کران چُھ، سُہ چُھ وحشی۔\n2.\\tاکھ نیک انسان چُھ خداوند سُند احسان حٲصل کران، مگر بدکار انسان کرِ سُہ مذمت۔\n3. انسان گژھِ نہٕ بدکاری سٍتـ̡ قایم سپدُن، مگر نیکوکارن ہُند مول گژھہِ نہٕ ہُراونہٕ یُن۔\n4. نیک زنانہٕ چھے پننِس خاوندس خٲطرٕ تاج: مگر یُس شرم کران چھُ سُہ چھُ تٔمۍ سٕنزِ أڈجہِ ہٕندِس سٍتـ̡ گٔژھان۔\n5.\\tنیک سُند خیال {چُھ} صحیح: {مگر} بدکارن ہٕندِ مشورٕ {چِھ} دھوکہٕ۔\n6.\\tبدکارن ہٕندِ کلامَن ہٕندِ کَلام چُھہ خونُک انتظار کرُن، مگر نیک سُند ٲسُن دِیہِ تِمن نجات دِنہٕ۔\n7.\\tبدکار چھہِ ختم سپدان، تہٕ {چھہِ} نہٕ، مگر نیکوکارن ہُند گرٕ گژھہِ کھڑا روزُن۔\n8.\\tانسان گژھہِ پننہِ حکمت مطٲبق تعریف کرنہٕ یُن، مگر یُس بدکار دِل آسہِ تس گژھہِ حقارت کرنہٕ یُن۔ {of a...: Heb. دِلُک گڑبڑ}\n9.\\tیُس حقیر آسہِ، تہٕ یُس خادم آسہِ، سُہ چُھ تٔمِس کھوتہٕ بہتر یُس پانس عزت کران آسہِ، تہٕ روٹی آسہِ نہٕ۔\n10. نیک انسان چُھ پننِس درندٕ سٕنزِ زندگی ہُند خیال تھاوان: مگر بدکارن ہٕنز نرم رحمتہٕ چھے ظالمانہٕ۔ {ٹینڈر...: یا، بویلز}\n11.\\tیُس پننہِ زمینہِ ہُند کاشتکار کرِ، سُہ گژھہِ روٹی سٍتـ̡ مطمئن سپدُن، مگر یُس بیکار سٍتـ̡ پیروی کرِ، سُہ چُھ نہٕ سمجھہٕ نِش خالی۔\n12.\\tبدکار چُھ بد کار سٕندِس جالس ہُند خواہش، مگر نیکوکارن ہُند مول چُھ {پھل} دِوان۔ {نیٹ: یا، قلعہ}\n13.\\tبدکار چُھہ چُھہ وُٹھن ہٕنزِ گُزاری سٍتـ̡ پھسنہٕ یوان: مگر عادل گژھہِ مصیبت منزٕ نیران۔ {بدکار...: ہیب۔ بدکار سُند جال چُھ وٕٹھن ہٕندِس خلاف ورزی منز}\n14.\\tانسان گژھہِ پننہِ ٲسہِ سٍتـ̡ نیکی سٍتـ̡ مطمئن: تہٕ انسان سٕندِ اتھن ہُند بدلہٕ ییہِ أمِس دِنہٕ۔\n15.\\tبیوقوف سُند وتھ چُھ تٔمۍ سٕنزِ نظرِ منز صحیح، مگر یُس مشورٕ بوزان چُھ، سُہ چُھ عقلمند آسان۔\n16.\\tبیوقوف سُند غصہٕ چُھ وُنکینس زاننہٕ یوان: مگر اکھ ہوشیار {انسان} چھُ شرم دِوان۔ {وٕنکین: ہیب۔ تمہ دۅہہ}\n17. یُس پزر بولان چُھ، سُہ چُھ نیکی ہاوان: مگر اپُز گواہ چُھ دھوکہٕ دِوان۔\n18.\\tسُہ چھُ تلوار ہٕندِس زَد ہٕندۍ پٲٹھۍ، مگر دانشمند سٕنز زبان چھِ صحت۔\n19.\\tحقیقتُک وُٹھ گژھہِ ہمیشہٕ خٲطرٕ قایم سپدُن، مگر اپُز زبان {چُھ} مگر کینژس کالس خٲطرٕ۔\n20.\\tدھوکہ دِنہٕ آمُت تِمن ہٕندِس دِلس مَنٛز یُس بُرُک تصور کران چُھ، مگر امن ہٕندِس مُشیرن ہٕندِ خٲطرٕ چُھ خوشی۔\n21. عادلن سٍتـ̡ گژھہِ نہٕ کانہہ بُرٕ سپدُن، مگر بدکار گژھہِ شرارت سٍتـ̡ بٔرِتھ۔\n22.\\tاپُز چُھہ خداوند سٕندِ خٲطرٕ مُنفرِتھ: مگر یِم پٔزۍ پٲٹھۍ تٔمۍ سٕنزِ خوشی سٍتـ̡ سٍتـ̡ سپدان چھِ۔\n23.\\tہوشیار انسان چھہ علم ژوٗرِ تھاوان، مگر بیوقوفن ہند دل چھہ بیوقوفی ہند اعلان کران۔\n24.\\tمحنتی سُند اَتھٕ گژھہِ حکمرٲنی کرُن: مگر سُست گژھہِ خراج دِنہٕ یُن۔ {کاہلی: یا، دھوکہٕ}\n25.\\tانسان سندِس دلس منز وزن آسنہ کنۍ چھہ یہ خۅش کران۔\n26.\\tنیک چُھ پننِس ہمساین کھۅتہٕ زیادٕ بہتر، مگر بدکار سُند وتھ چُھ تِمن ورٲے دِوان۔ {بہترین: یا، وافر}\n27.\\tکُنہِ سٍتـ̡ یُس شکارس منز نِوان چُھ، سُہ چُھہ نہٕ سُہ سٍتـ̡ سٍتـ̡ قۭمتی آسان۔\n28.\\tنیکی ہٕندِس وتہِ منز چُھ زندگی؛ تہٕ {منز} وتہِ {تمہِ منز} چھہ نہ کانہہ موت۔","1. عقلمند نیچو چُھ پننِس مٲلہِ سٕنز ہدایت بوزان مگر بدکار چُھ نہٕ ملامت بوزان۔\n2.\\tانسان گژھہِ پننہِ ٲسہِ سٍتـ̡ رژھ کھٮ۪ن، مگر نافرمان سُند روح گژھہِ تشددٕ کھٮ۪وان۔\n3. یُس پَنُن چُھس رژھراوان چُھ، سُہ چُھ پَنُن زُو رژھراوُن: {مگر} یُس پَنُن وُٹھ پھُلِتھ چُھہ تباہی سپدِ۔\n4.\\tسُست سُند روح چُھ یژھان، تہٕ {چُھ} نہٕ کیٚنٛہہ، مگر محنتی سُند روح گژھہِ موٹ۔\n5. نیک انسان چُھ اپُز سٍتـ̡ نفرت: مگر بدکار {انسان} چُھ نفرت تہٕ شرمندہ سپدان۔\n6. نیکی چُھ وتہِ منز سیدِ پٲٹھـ̡ تھاوان، مگر بدکاری چُھ گۅنہگار سٍتـ̡ ختم کران۔ {گۅنہگار: ہیب۔ گۅناہ }\n7. یُس پانس امیر بناوان چُھ، توتہِ چُھ نہٕ کانہہ تہِ: {تِتھ} چُھ یُس پانس غریب بناوان چُھ، توتہِ چُھ {چُھ} واریاہ دولت۔\n8.\\tانسان سٕنزِ زندگی ہُند فدیہ چھُ تٔمۍ سٕندِس دولتس سٍتـ̡ مگر غریبٕ چُھہ نہٕ ملامت بوزان۔\n9. نیکوکارن ہُند گاش چُھ خۅش گژھان، مگر بدکارن ہُند شمع گژھہِ ژھیتہٕ کرنہٕ۔ {چراغ: یا، شمع}\n10.\\tصرف غرور سٍتۍ چھہ تنازعہ سپدان: مگر نصیحت کرنہٕ آمٕژ حکمت سٍتۍ۔\n11.\\tباطلس سٍتۍ حٲصل سپدن وول دولت گژھہِ کم سپدُن، مگر یُس محنتہٕ سٍتۍ جمع کرِ، سُہ گژھہِ ہُرراوُن۔ {بذریعہ لیبر: ہیب۔ اَتھٕ سٍتۍ}\n12.\\tوۅمید سٍتـ̡ چُھ دِل بیمار بناوان: مگر {ییلہ} خواہش ییہِ ، {یہ} چُھ زندگی ہُند کُل آسان۔\n13.\\tیُس تہِ کُنہِ کلامس حقارت کرِ، سُہ گژھہِ تباہ سپدُن، مگر یُس حکمس سٍتـ̡ خوفزدہ آسہِ، سُہ گژھہِ بدلہٕ دِنہٕ۔ {یِیہٕ انعام دِنہٕ: یا، گژھ امن سٍتۍ}\n14. دانشمندن ہُند قانون چُھ زندگی ہُند چشمہٕ، یُس موت کِس جالس نِش نیرُن چُھ۔\n15.\\tاصل فہم چھہ احسان دِوان: مگر نافرمان سُند وتھ چھہ مشکل۔\n16.\\tپریتھ دانشمند انسان چھہ علمس سیتۍ وابستہ: مگر بیوقوف چھہ پننہِ حماقت کھولان۔ {layeth...: Heb. پھٔلِتھ}\n17.\\tبدکار پیغمبر چھہ شرارتس منز مبتلا سپدان: مگر اکھ وفادار سفیر چھہ صحت مند۔ {اکھ وفادار...: ہیب۔ وفاداریُک سٔفیٖر}\n18.\\tغفلت تہٕ شرم گژھہِ تٔمِس سٍتـ̡ یُس تعلیمہٕ نِش انکار کرِ، مگر یُس ملامت کرِ، سُہ گژھہِ عزت کرنہٕ۔\n19.\\tیُس خٲہش پوٗرٕ سپدان چھُ، سُہ چُھ روحس خٲطرٕ میٹھ، مگر بیوقوفن ہٕندِ خٲطرٕ چُھ بدی نِش نیرُن مُنفرت۔\n20.\\tیُس عقلمند سٍتـ̡ پکان چُھہ سُہ گژھہِ عقلمند آسان، مگر بیوقوفن ہُند سٲتھی گژھہِ تباہ کرنہٕ۔ {تباہ: ہیب۔ پھُٹمُت}\n21.\\tبُرٕ چُھ گۅنہگارن ہُند تعاقب کران: مگر نیکوکارن ہُند بدلہٕ یِیہِ دِنہٕ۔\n22.\\tاکھ نیک انسان چُھ پننین بچن ہٕندِس بچس وراثت تراوان: تہٕ گۅنہگار سُند مال چُھ عادل سٕندِ خٲطرٕ تراونہٕ یوان۔\n23.\\tغریبن ہٕندِس کاشتس منز چُھ واریاہ کھٮ۪نہٕ آمُت: مگر اَتھ منز چُھ {یعنی} فیصلہٕ نہ آسنہٕ کِنۍ تباہ کرنہٕ آمُت۔\n24.\\tیُس پَنُن لٔر بچاوان چُھ، سُہ چُھ پننِس نیچوِس سٍتـ̡ نفرت کران، مگر یُس أمِس محبت کران چُھ، سُہ چُھ أمِس سٍتـ̡ سزا دِوان۔\n25. نیک چُھ پننہِ روحٕچ تسلی خٲطرٕ کھٮ۪وان: مگر بدکار سُند یٔڈ چُھ یژھان۔","1. پرٮ۪تھ دانشمند زنانہٕ چھے پنُن گرٕ بناوان، مگر بیوقوف چھُ یہِ پننیو اتھو سٍتۍ ژٹان۔\n2. یُس پنہٕ نِس سیدِ پٲٹھـ̡ پکان چُھہ سُہ چُھ خداوند سُند خوف تھاوان، مگر یُس پنہٕ نِس طریقس مَنٛز بدکار چُھ، سُہ چُھ أمِس حقارت کران۔\n3.\\tبیوقوف سٕندِس ٲسِس مَنٛز چُھہ فخرٕچ لٔرِتھ، مگر دانشمندن ہٕندِس چپنہٕ سٍتـ̡ رژھراوٕنـ̡ ۔\n4.\\tییتہِ نہٕ داند {چھِ}، کۅنگہٕ {چُھ} صاف آسان: مگر بیلہٕ سٕندِ طاقتہٕ سٍتۍ چُھ واریاہ ہُرراوان {چُھ}۔\n5. اکھ وفادار گواہ کرِ نہٕ اپُز مگر اکھ اپُز گواہ کرِ اپُز۔\n6.\\tاکھ بدمعاش چھہ حکمت ژھاران تہ {یہ لبان چھہ} مگر علم چھہ سہل آسان یُس سمجھان آسہِ۔\n7.\\tأکِس بیوقوف سٕندِ حٲضِری نِش گژھِو یێلہِ نہٕ تۅہہِ عٔلِمٕچ وُٹھ وُچھِو۔\n8.\\tہوشیار سٕنز حکمت چھے تٔمۍ سٕنزِ وتھ سمجھنہٕ خٲطرٕ، مگر بیوقوفن ہٕنز حماقت چھِ دھوکہٕ۔\n9.\\tبیوقوف چھِ گۅنہٕ سٍتـ̡ مذاق بناوان: مگر نیکوکارن مَنٛز چُھ احسان آسان۔\n10. دِل چُھ پنٕنۍ تلخی زانان۔ تہٕ اکھ اجنبی چھُنہٕ أمۍ سٕنزِ خوشی منٛز مداخلت کران۔ {پنُن...: ہیب۔ تمۍ سندِ روحچ تلخی}\n11.\\tبدکارن ہُند گرٕ گژھہِ پھُٹاونہٕ یُن، مگر پاکیزہ سُند خیمہ گژھہِ پھۅلُن۔\n12.\\tاکھ وتھ چھہ یُس انسانس صحیح باسان چھہ مگر امیک اند چھہ موتچ وتھ۔\n13.\\tاسنس منز تہِ چھہ دل غم۔ تہٕ تمہِ خوشی ہند اند {چُھ} وزن۔\n14.\\tدِلس منز گژھہِ پتھ کُن پنہٕ نِس طریقس سٍتۍ بٔرِتھ تہٕ نیک انسان گژھہِ پانس نِش مطمئن۔\n15.\\tسادہ چھہ پریتھ لفظس پیٹھ یقین تھاوان، مگر ہوشیار انسان چھہ پننس گژھنس پیٹھ رژھران۔\n16.\\tعقلمند انسان چھہ بدی نِش کھوژان تہٕ بدی نِش دور گژھان، مگر بیوقوف چھہ غصہ کران تہٕ یقین تھاوان۔\n17.\\tیُس یُس غصہٕ سٍتـ̡ سٍتـ̡ چُھہ بیوقوفی سٍتـ̡ بێوُن سٍتـ̡ سٍتـ̡ بد کار سٍتـ̡ نفرت۔\n18.\\tسادٕ حماقت چھِ وراثت: مگر دانشمندَن چھِ علمہٕ سٍتۍ تاج لاگنہٕ یِوان۔\n19. بد چھُ نیکی برونہہ کُن کمان؛ تہٕ بدکار چھِ نیکوکارن ہٕندِس دروازس پیٹھ۔\n20.\\tغریبس چھہ پننین ہمساین سٍتۍ تہِ نفرت: مگر امیر چھہِ واریاہ دوس۔ {امیر...: ہیب۔ واریاہ چھہِ امیرن ہندۍ عاشق}\n21.\\tیُس پننِس ہمساین حقارت کران چُھ، سُہ چُھ گۅناہ کران: مگر یُس غریبن پیٹھ رحم کرِ، سُہ چُھ خوش گناہ۔\n22.\\tکیا تِم چھِنہٕ غلطی کران یِم بُرٕ بناوان چھِ؟ مگر رحم تہٕ سچائی گژھہِ تِمن خٲطرٕ یِم نیکی ہُند منصوبہ بناوان چھِ۔\n23.\\tسارِنٕے محنتس منز چُھ نفع آسان: مگر وُٹھن ہٕنز کتھ چھے صرف مفلسی کُن۔\n24.\\tدانشمندَن ہُند تاج چھُ تِہُند دولت: {مگر}بیوقوفن ہٕنز بیوقوفی چھِ حماقت۔\n25. پٔزۍ گواہ چُھ روٝحہِ نجات دِوان: مگر اکھ دھوکہ دِنہٕ وول {گواہ} چُھ اپُز بولان۔\n26. خداوند سٕندِس خوفس مَنٛز چُھ سٮ۪ٹھاہ اعتماد: تہٕ تٔمۍ سٕندِس شُرِس میلہِ پناہ گاہ۔\n27.\\tخداوند سُند خوف چُھ زندگی ہُند چشمہٕ، یُس موتٕکِس جالس نِش نیرنہٕ خٲطرٕ چُھ۔\n28.\\tلُکن ہٕندِس تعدادس منز چُھ بادشاہ سُند عزت: مگر لوکن ہٕندِس محتاجس منز چُھ شہزادٕ سٕنز تباہی۔\n29.\\t{یُس} یُس غصہٕ کُن سُہ چُھہ سُہ سُہ بٔڈ فہم تھاوان چُھ، مگر {یُس} یُس روحُک عجلت چُھ کران سُہ چُھ حماقتس سٍتـ̡ بڑاوان۔ {جلدی...: ہیب۔ کم از کم روح}\n30.\\tصحت مند دِل چُھ مازٕچ زندگی: مگر أڈجن ہٕنزِ گڑنٕچ حسد کٔرِتھ۔\n31. یُس غریبس پیٹھ ظلم کران چُھ، سُہ چُھ پننِس خالقس ملامت کران، مگر یُس أمِس عزت کران چُھ، سُہ چُھ غریبن پیٹھ رحم کران۔\n32.\\tبدکار چُھ پننہِ بدکاری سٍتـ̡ ژلنہٕ یوان، مگر نیکوکارس چُھ پننِس مرنس سٍتـ̡ وۅمید تھاوان۔\n33.\\tعقل چُھ تٔمِس سٕندِس دِلس مَنٛز آسان یُس عقل آسہِ، مگر یُس بیوقوفن منز چُھ آسان سُہ چُھ ظٲہر سپدان۔\n34.\\tنیکی چھے قومس تھزراونہٕ یوان: مگر گۅناہ چُھ کُنہِ تہِ لُکہٕ خٲطرٕ ملامت آسان۔ {کُنہِ تہِ...: ہیب۔ قومن تام}\n35.\\tبادشاہ سُند احسان چُھ أکِس عقلمند خادمس سٍتـ̡ ، مگر تٔمِس سُند غصہٕ چُھ تٔمِس سٍتـ̡ یُس شرمندہ کران چُھ۔","1.\\tاکھ نرم جواب چھہ غصہ دور کران: مگر غمگین لفظ چھہِ شرارت وۅتلان۔\n2.\\tدانشمند سٕنز زبان چھے علمس صحیح پٲٹھـ̡ استعمال کران، مگر بیوقوفن ہٕندِس ٲسس سٍتـ̡ بیوقوفی کڈان۔ {پورتھ: ہیب۔ بیلچتھ، یا، بلبلتھ}\n3. خداوند سٕنزِ أچھ چھے پریتھ جایہ بد تہٕ نیکی وُچھان۔\n4.\\tصحت مند زبان چھہ زندگی ہند کُل، مگر اتھ منز چھہ بدکاری روحس منز اکھ خۅد قدم۔ {اکھ صحت مند...: ہیب۔ زبانۍ ہند شفا}\n5.\\tبیوقوف چُھ پننِس مٲلہِ سٕنزِ ہدایتس حقارت کران، مگر یُس ملامت کران چُھ سُہ چُھ دانشمند۔\n6.\\tنیک سٕندِس گرس مَنٛز چُھ واریاہ خزانہٕ: مگر بدکارن ہٕندِس مٲلِس مَنٛز چُھ مصیبت۔\n7.\\tدانشمند سٕندِ وٕٹھ چھِ علمس پھہلاوان، مگر بیوقوفن ہُند دِل چُھ نہٕ یہِ کران۔\n8.\\tبدکار سٕنز قربانی چُھ خداوند سٕندِ خٲطرٕ مُنفرِتھ، مگر راست سُند دُعا چُھ تٔمۍ سٕنز خوشی ۔\n9. بدکار سُند وتھ چُھ خداوند سٕندِ خٲطرٕ ناپسندیدٕ، مگر سُہ چُھ تٔمِس سٕندِس سٍتـ̡ محبت کران یُس نیکی پَتہٕ پٲٹھـ̡ پٲٹھـ̡ چُھ۔\n10.\\tاصلاح چھہ تٔمِس سٍتـ̡ تکلیف دہ یُس وتھ تراوان چُھ: {تہٕ} یُس ملامت سٍتـ̡ نفرت کرِ، سُہ چُھ مرُن۔ {تصحیح: یا، ہدایت}\n11.\\tجہنم تہٕ تباہی چُھہ خداوند سٕندِس برونہہ کُن: انسان سٕندِس اولادس ہٕندِس دلس منز کوتاہ زیادٕ؟\n12.\\tبدکار چھہ نہ تس محبت کران یُس أمس ملامت کرِ، تہ نہ گژھہِ عقلمندن نِش۔\n13.\\tخۅش دل چھہ خۅش بُتھ بناوان، مگر دِل سٍتۍ چھہ روح پھٹان۔\n14.\\tیُس سمجھ آسہِ سُند دِل چُھ علمس ژھاران مگر بیوقوفن ہُند دِل چُھ بیوقوفی ہُند شکار سپدان۔\n15.\\tمُصیبت زدہ سٕندِ سارِنٕے دۅہہٕ چِھ بُر، مگر یُس خۅش دِل آسہِ، سُہ چُھ لگاتار دعوت دِوان۔\n16. خداوند سٕندِ خوفہٕ سٍتـ̡ چُھہ بٔڈۍ خزانہٕ تہٕ پریشٲنی کھۅتہٕ کم بہتر۔\n17.\\tبہتر چھہ جڑی بوٹین ہُند ڈنر ییتہِ محبت آسہِ، اَمہ سٍتۍ رُکاونہٕ آمٕتۍ بیل تہٕ نفرتس کھۅتہٕ چھُ بہتر۔\n18.\\tاکھ غصہ وول انسان چھہ کشمکش کران مگر {یُس} شرارتس منز چھہ لوٚت سُہ چھہ کشمکش کران۔\n19.\\tسُند وتھ چُھہ کانٹٮن ہٕندِس پٲٹھۍ، مگر نیکوکارن ہٕنز وتھ چھیہ سیدِ سیود کرنہٕ آمٕژ۔ {بنیومُت...: ہیب۔ کاز کس طورس پیٹھ چُھ پرورش کرنہٕ آمُت}\n20.\\tعقلمند نیچو چھہ خۅش مول بناوان، مگر بیوقوف چھہ پننہِ ماجہ سیتۍ حقارت کران۔\n21.\\tحماقت چھیہ {یُس} عقلہِ نِش محروم آسنہ کِنۍ خوشی مگر سمجھدار انسان چھہ سیدِ سیود پکان آسان۔ {بے چارہ...: ہیب۔ دِلُک خٲلی}\n22.\\tمشورٕ ورٲے چھُ مقصد مایوسی سپدان: مگر مشیرن ہٕندِس تعدادس منز چھِ یِم قایم سپدان۔\n23.\\tانسان چھہ پننہِ ٲسک جواب سٍتۍ خوشی حٲصل سپدان: تہٕ اکھ لفظ {بولنہٕ} وقتس منز، کوتاہ اصل چھہ یہِ! {وجہ سٍتۍ...: ہیب۔ تٔمۍ سُنٛد موسم}\n24.\\tزندگی ہُند طریقہ چُھ دانشمندن ہٕندِ خٲطرٕ ہیرِ پیٹھ، یُتھ سُہ جہنم نشہِ نیرِ۔\n25. خداوند کرِ مغرور سُند گرٕ تباہ مگر سُہ کرِ بیواہ سُند سرحد قایم۔\n26.\\tبدکار سُند خیال چُھہ خداوند سٕندِ خٲطرٕ مکروہ مگر {پاک﴾ سٍتـ̡ چِھہ خۅش گُزار۔ {خوشگوار...: ہیب۔ خۅش گَژھنٕکۍ کَلام}\n27. یُس نفعہٕ حٲصل کرنُک لالچ چُھ، سُہ چُھ پننِس گرس پریشان کران۔ مگر یُس تحفن سۭتۍ نفرت کرِ، سُہ روزِ زندٕ۔\n28.\\tنیک سُند دِل چُھ جواب دِنہٕ خٲطرٕ پران مگر بدکار سُند اوس بد کار کُن تراوان۔\n29. خداوند چُھ بدکارن نِش دور، مگر سُہ چُھ نیکوکارن ہٕنز دعا بوزان۔\n30.\\tاچھن ہُند گاش چھُ دِل خۅش کران: {تہٕ} رٔژ خبر چھے أڈجن موٚٹۍ بناوان۔\n31.\\tزندگی ہنز ملامت بوزان چھہ سہ چھہ دانشمندن منز روزان۔\n32.\\tیُس ہدایتُک انکار کران چُھ، سُہ چُھ پننِس نفسس حقارت کران، مگر یُس ملامت بوزان چُھ، سُہ چُھ سمجھ حٲصل کران۔ {ہدایت: یا، تصحیح } {بوزُن: یا، اطاعت کٔرتھ} {گیتھ...: ہیب۔ اکھ دِل چُھ}\n33. خداوند سُند خوف چُھہ حکمتٕچ تعلیم۔ تہٕ عزتَس برونہہ کُن چھُ عاجزی۔","1.\\tانسانس منز دِلٕچ تیاری تہٕ زبانہِ ہُند جواب، {چُھ} خداوند سٕندِ طرفہٕ۔ {تیاری: یا، ڈسپوزنگ}\n2.\\tانسان سٕندِ سٲری وتہٕ چھِ پننین نظرن منز صاف آسان۔ مگر خداوند چُھ روحن تولان۔\n3. پَنٕنہِ کامہِ کٔرِو خداوند سٕندِس سٍتـ̡ ، تہٕ تُہٕندِس خیالس گٔژھِو قٲیِم۔ {Commit: Heb. رول}\n4. خداوند چُھ سارِنٕے چیٖز پانس خٲطرٕ بنوومُت: آ، بدکار تہِ بد دۅہہٕ خٲطرٕ۔\n5. پرٮ۪تھ کانہہ {یُس}دِلس مَنٛز مغرور چُھہ {چُھ} خداوند سٕندِ خٲطرٕ مُنفرِتھ: {حالانکہ} اَتھٕ {رَلاونہٕ} سٍتـ̡ گژھِ نہٕ سُہ سزا دِنہٕ یُن۔ {غیر سزا: ہیب۔ بے گناہ قرار دِنہٕ}\n6. رحمتہٕ تہٕ سچٲئی سٍتـ̡ چُھ بدکاری پاک سپدان: تہٕ خداوند سٕندِ خوفہٕ سٍتـ̡ چُھہ بدی نِش دور سپدان۔\n7. یێلہِ اِنسان سٕندِ وَتہٕ چُھہ خداوند خوش کران، سُہ چُھ پَنٕنـ̡ دُشمن تہِ پانس سٍتـ̡ امن کَران۔\n8.\\tحقہ ورٲے بٔڈ آمدنی کھوتہ بہتر چھہ نیکی سٍتۍ۔\n9.\\tانسان سُند دِل چُھ پنٕنۍ وتھ بناوان: مگر خداوند چُھ پَنٕنـ̡ قدمن ہُند ہدایت دِوان۔\n10.\\tبادشاہ سٕندِس وٹھس مَنٛز چھُ خدایہ جملہٕ: تٔمۍ سٕندِس ٲسس چھُنہٕ فٲصلس مَنٛز پامال سپدان۔ {اکھ خدایہ...: ہیب۔ Divination}\n11.\\tاکھ عادل وزن تہٕ توازن {چھ} رب سُند: بیگُک سٲری وزن {چھِ} تسٕنزِ کٲم۔ {وزن: ہیب۔ دی سٹون}\n12.\\tبادشاہن ہٕندِ خٲطرٕ بدکار کرُن چُھ ناپسندیدٕ، تکیازِ تخت چُھ نیکی سٍتـ̡ قایم سپدان۔\n13.\\tنیک وٹھ چھہِ بادشاہن ہنز خوشی۔ تہٕ تِم چھِ أمِس محبت کران یُس صحیح کتھ کران چھُ۔\n14.\\tبادشاہ سُند قہر چُھ موتُک قاصد مگر عقلمند کرِ أمِس تسلی دِنہٕ۔\n15.\\tبادشاہ سٕندِس بُتھِس مَنٛز {چُھ} زندگی؛ تہٕ تٔمۍ سُند احسان {چُھ} پٔتمِس روٗدُک اوٚبر۔\n16. سۄنہٕ کھۅتہٕ کوتاہ بہتر چھُ حکمت حٲصِل کرُن! تہٕ رۄپہٕ بدلہٕ ژارنہٕ بجایہ سمجھ حٲصل کرُن!\n17.\\tبدکار سٕنزِ وتہِ چُھہ بدی نِش نیرُن: یُس پنٕنـ̡ وتھ رژھراوان چُھہ سُہ چُھ پَنُن روح رژھران۔\n18. تباہی برونہہ غرور تہٕ زوال برونہہ اکھ مغرور روح۔\n19.\\tغنیمت کُن بٲگراونہٕ کھۅتہٕ چھُ بہتر زِ یہ گژھہِ کمتر سٍتـ̡ عاجز آسُن۔\n20. یُس کُنہِ معاملس دانشمندی سان سنبھالان چُھ، سُہ میلہِ خیر تہٕ یُس خداوند پیٹھ بھروسہٕ کرِ، سُہ چُھ خوش گَژھان۔ {ہینڈلتھ...: یا، اکھ معاملہ سمجھان}\n21.\\tدِلٕچ دانشمند یِن ہوشیار وننہٕ یُن: تہٕ وٕٹھن ہٕنزِ مٹھاس سٍتۍ چھُ ہیچھنس منز ہُرٮ۪ر سپدان۔\n22.\\tسمجُن چُھ تٔمِس سٕندِ خٲطرٕ زندگی ہُند سرچشمہٕ، مگر بیوقوفن ہٕنز تعلیم چھِ حماقت۔\n23.\\tعقلمند سُند دِل چُھ أمِس ٲسس ہیچھناوان تہٕ چُھس وُٹھن سٍتـ̡ ہیچھناوان ۔ {ہیچھن: ہیب۔ عقلمند بناوُن}\n24.\\tخۅش گۅنم لفظ چھہِ شہد کٔرِتھ تہ روحس مٔٹھۍ تہ اڈین صحت بخشان۔\n25.\\tاکھ وتھ چھہ یُس انسانس صحیح باسان چھہ مگر امیک اند چھہ موتچ وتھ۔\n26. یُس محنت کران چُھ، سُہ چُھ پننہِ خٲطرٕ محنت کران۔ تکیازِ تمۍ سندِ ٲسس چھہ أمس نِش رژھران۔ {یہ...: ہیب۔ تٔمۍ سُند روح یُس} {craveth...: Heb. أمِس کُن کٔرِو سجاوُن}\n27.\\tاکھ بدکار انسان چھہ بد کار کڈان تہ تمۍ سندِس وٹھس منز چھہ دزُن نار۔ {an...: Heb. بیلیالُک اکھ انسان}\n28.\\tاکھ بدمعاش انسان چھُ جھگڑٕ وُچھان: تہٕ اکھ سرگوشی کرن وول چھُ اہم یارن الگ کران۔ {سوتھ: ہیب۔ سُہ چُھ فورتھ}\n29.\\tاکھ ظالم انسان چھہ پننس ہمساین پھیران تہ تس اتھ وتہِ پیٹھ واتناوان یُس نہ اصل چھہ۔\n30.\\tسُہ چُھ أچھ بند کٔرِتھ بدکار چیز بناوان: وُٹھ پھیرِتھ چُھ سُہ بُرٕ وُچھان۔\n31.\\tہُرِ کلہٕ {چُھ} جلال ہُند تاج، {یێلہ} یہِ نیکی ہٕندِس وتہِ مَنٛز لبنہٕ ییہِ۔\n32.\\t{یُس شرارت کُن سُہ چُھہ سُہ طاقتور کھوتہ بہتر}۔ تہٕ یُس پننِس روحس پیٹھ راج کران چُھ، سُہ چُھ شہر رٹان۔\n33.\\tلاٹ چھہ گودس منز تراونہ یوان۔ مگر امیک سورُے انتظام چُھ خداوند سُند۔","1.\\tاکھ خشک گرہ تہ خاموشی چھیہ قربانیو سیتۍ بٔرِتھ گرہ کھوتہ بہتر {چھُ}۔ {قربانی: یا، گڈ چیر}\n2.\\tعقلمند خادم گژھہِ أکِس نیچوس پیٹھ حکمرٲنی کرُن یُس شرم ہُند باعث بٔنِتھ آسہِ، تہٕ أمِس آسہِ بٲے سٕندِس وراثتس منز حِصہٕ۔\n3. رۄپہٕ خٲطرٕ چُھہ بٹھہٕ تہٕ سۄنہٕ خٲطرٕ، مگر خداوند چُھ دلن آزماوان۔\n4. بدکار چُھ اپُز وٕٹھن پیٹھ توجہ دِوان۔ {تہ} اکھ اپُز چھُ شرارتی زبانہِ بوزان۔\n5. یُس غریبس ٹھٹھہٕ کران چُھ، سُہ چُھ پننِس خالقس ملامت کران: {تہٕ} یُس آفتن پیٹھ خوش آسہِ، سُہ گژھِ نہٕ سزا دِنہٕ۔ {غیر سزا: ہیب۔ بے گناہ قرار دِنہٕ}\n6. بچن ہٕندِ شُرۍ {چِھ} بُزرگَن ہُند تاج۔ تہٕ شُرین ہُند جلال چھُ تِہندِ مول ۔\n7.\\tعمدہ کلام چھہ نہ بیوقوف بنان تہ اپُز وُٹھ تہِ چھہ نہ شہزادہ بنان۔ {بہترین...: ہیب۔ اکھ وٹھ آف ایکسیلنس} {اپُز...: ہیب۔ اپُزُک اکھ وُٹھ}\n8.\\tاکھ تحفہٕ چُھ تٔمِس سٕندِس نظرِ منز اکھ قیمتی پتھر: ییتہِ تہِ یہ پھیرِ، سُہ چُھ ترقی کران۔ {اکھ قیمتی...: ہیب۔ فضل ہُند اکھ پتھر}\n9.\\tیُس گناہ پردہ کران چُھ، سُہ چُھ محبت ژھاران۔ مگر یُس کُنہِ معاملس دہراوان چُھ، سُہ چُھ الگ یار آسان۔ {ژھانڈو: یا، حاصل}\n10.\\tملامت چھہ عقلمند انسانس منز ہتھ کھۅتہ زیادہ دٲخل سپدان۔ {اژُن...: یا، ہتھ لٹہِ بیوقوفس مارنہٕ کھۅتہٕ زیادٕ عقلمند چھُ}\n11.\\tاکھ بد انسان چھہ صرف بغاوت ژھاران تہ امہ مۅکھہ گژھہِ تس خلاف اکھ ظالم رسول سوزنہ۔\n12.\\tیُس ریچھ پننہِ بیوقوفی منز بیوقوفہ بجایہ أکِس مردس سٍتۍ میلہِ۔\n13.\\tیُس بُرِس نیکی بدلہٕ دِیہِ، سُہ گژھِ نہٕ بُرٕ سٕندِس گَرٕ منزٕ نیرُن۔\n14.\\tتنازعہ ہند آغاز چھہ یتھے پاٹھۍ ییلہ کانہہ آب نیبر نیران چھہِ: لہذا تراوِ تنازعہ تراوُن، امہ برونہہ زِ اتھ منز گژھہِ مداخلت کرنہ۔\n15.\\tیُس بدکارن انصاف کران چُھ، تہٕ یُس عادل سُند مذمت کران چُھ، تِم تہِ چِھ دۅنوے خداوند سٕندِ خٲطرٕ مکروہ ۔\n16.\\tعقل حٲصل کرنہ خاطرہ کیازِ چھہ بیوقوف سندِس اتھس منز کانہہ قیمت، یہ وچھتھ زِ {أمِس چھُنہ} کانہہ دِل چھُ؟\n17.\\tدوس چھہ پریتھ ساعتہ محبت کران، تہ اکھ بوے چھہ مصیبت خاطرہ پیدہ گژھان۔\n18.\\tیُس انسان سمجھ نِش خالی آسہِ، سُہ چُھ پننِس یارس سٕندِس حضورس منز ضامن بنان۔ {سمجھ: ہیب۔ دِل}\n19.\\tسُہ چُھ تِمن خلاف ورزی سٍتـ̡ محبت کران یُس لڑایہِ سٍتـ̡ محبت کران چُھہ: {تہٕ} یُس پَنُن دروازٕ تھزرٲوِتھ چُھ، سُہ چُھ تباہی یژھان۔\n20.\\tیُس دِل بدکار آسہِ، تس چھہ نہ کانہہ خیر میلان تہ یُس بدکار زبان آسہِ سہ چھہ شرارتس منز مبتلا گژھان۔ {یُس گڑبڑ چُھ...: ہیب۔ دِلُک فراورڈ}\n21.\\tیُس بیوقوفس پیدہ کران چُھ، سُہ چُھہ پننِس غمس سٍتـ̡ بێوُن تہٕ بیوقوف سٕندِس مٲلِس چُھنہٕ کانہہ خۅش سپدان۔\n22.\\tخۅش دِل چُھہ رژھران۔ {پٲٹھۍ: یا، to}\n23.\\tاکھ بدکار {انسان} چُھ فیصلہ کِس طریقس پھیُراونہٕ خٲطرٕ چھُ چھُ سنہٕ منزٕ تحفہٕ کڈان۔\n24.\\tحکمت چھیہ تٔمِس برونہہ کُن یُس سمجھ آسہِ۔ مگر بیوقوف سٕنز أچھ چھِ زمینہٕ کِس اندس پیٹھ۔\n25.\\tبیوقوف نیچو چُھ مٲلِس سٍتـ̡ غم تہٕ تٔمِس سٍتـ̡ تلخی یُس أمِس زَن دِوان چُھ۔\n26.\\tعدلس سزا دِنہٕ خٲطرٕ {چھُ} نہٕ اصل، {نَہ} شہزادن انصاف خٲطرٕ مارنہٕ خٲطرٕ۔\n27.\\tیُس علم آسہِ سُہ چُھ پَنٕنـ̡ کَتھٕ سٍتـ̡ بچاوان: {تہٕ} سمجھدار انسان چُھ اکھ بہترین روح۔ {an...: یا، اکھ ٹھنڈ}\n28.\\tبیوقوف تہِ ییلہ سُہ پَنُن سکون تھاوان چُھ، سُہ چُھ عقلمند ماننہٕ یوان: {تہٕ} یُس چُھہ وُٹھ بند کٔرِتھ {سُہ چُھہ سمجھدار ماننہٕ یِوان۔","1.\\tخواہش سٍتۍ چھہ انسان پانس الگ کٔرِتھ تمام دانشمندی سٍتۍ مُداخلت کران۔ {ذریعہ...: یا، یُس پانس الگ کران چُھ، سُہ چُھ پننہِ مرضی مطٲبق ژھانڈان، تہٕ پرتھ کُنہِ کاروبارس منز مداخلت کران چُھ}\n2.\\tبیوقوفس چھہ نہ سمجھنس منز کانہہ خۅش آسان، مگر یہ زِ تسند دل گژھہِ پانس دریافت کرنہ۔\n3.\\tییلہ بدکار یِوان چھُ، {تیلہِ} تہِ چھُ حقارت تہٕ بے عزتی سٍتـ̡ یِوان کرنہٕ۔\n4.\\tانسان سٕندِ ٲسٕکۍ لفظ چھِ سرٛوٚن آبہٕ ہٕندۍ پٲٹھۍ، {تہٕ}حکمتُک چشمہٕ {یِتھ} وسوُن نالہٕ۔\n5.\\tبدکار سُند شخص قبول کرُن چُھہ نہٕ اصل۔\n6.\\tبیوقوف سٕندِس وُٹھ چھُ تنازعس منز دٲخل سپدان تہٕ أمِس چُھس چُھس ٹاس دِوان۔\n7.\\tبیوقوف سُند اوس تٔمۍ سُند تباہی تہٕ تٔمۍ سٕندِس وُٹھس چھُ تٔمۍ سٕندِس روحُک جال۔\n8.\\tافسانہ نگار سٕندۍ لفظ چھہِ زخمن ہٕندۍ پٲٹھۍ، تہٕ یِم چھِ یٔڈ کِس اندرمِس حصس منز وسان ۔ {افسانہٕ بردار: یا، سرگوشی} {زخم پٲٹھۍ: یا، یتھے پاٹھۍ ییلہ انسان زخمی چھہِ} {زیادٕ...: ہیب۔ چیمبرز}\n9.\\tسُہ تہِ یُس پننہِ کامہِ منز سُست چُھ، سُہ چھُ أمِس بٲے یُس اکھ بوٚڈ فضول چُھ۔\n10. خداوند سُند ناو چُھہ اَکھ مضبوٗط مینار: نیک چُھ اَتھ مَنٛز ژلان تہٕ چُھہ محفوٗظ۔ {محفوظ: ہیب۔ سیٹ اَلفٹ کٔرِو}\n11. امیر سُند دولت چُھ تٔمۍ سُند مضبوط شہر، تہٕ پننِس غرورس منٛز اکھ تھدِ دیوار ہٕندۍ پٲٹھۍ۔\n12.\\tتباہی برونہہ چھہ انسان سند دل غرور تہ عزتس برونہہ چھہ عاجزی۔\n13.\\tیُس کُنہِ معاملس بوزنہٕ برونہہ جواب دِیہ، سُہ چُھ تٔمِس خٲطرٕ حماقت تہٕ شرمندگی۔ {جواب...: ہیب۔ واپس}\n14.\\tانسان سُند روح روزِ تسٕنزِ کمزوری برقرار تھاون۔ مگر اکھ زخمی روح یُس برداشت ہیکہِ کٔرتھ؟\n15. ہوشیار سُند دِل چُھ علمس حٲصل کران۔ تہٕ دانشمند سُند کَن چھُ علمٕچ تلاش کران۔\n16. انسان سُند تحفہٕ چُھ أمِس خٲطرٕ جاے بناوان، تہٕ سُہ چُھ بڑین نفرن برونہہ کُن انان۔\n17.\\t{سُہ یُس} گۅڈٕ پننِس مقصدس منز {سیمیتھ} منصف۔ مگر تٔمۍ سُند ہمسایہ آو تہٕ أمِس ژھانڈان۔\n18.\\tسٍتـ̡ چُھہ تنازعہ ختم سپدان تہٕ طاقتورن درمیان الگ سپدان۔\n19.\\tاکھ بٲے ناراض {زینُن چُھ مشکل} أکِس مضبوٗط شہرس کھۅتہٕ زیادٕ مشکل: تہٕ {تِہُند} تنازعہ {چُھ} قلعہ کین سلاخن ہٕندۍ پٲٹھۍ۔\n20.\\tانسان سُند پیٹ گژھہِ ٲسِس پھلہٕ سٍتـ̡ مطمئن۔ {تہ} چپنہِ ہٕندِس ہُررس سٍتۍ گژھہِ سُہ بٔرِتھ۔\n21. موت تہٕ زندگی چِھ زبانہِ ہٕندِس اختیارس منز: تہٕ یُس اتھ محبت کران چُھ، تم گژھن اَمہ سُند پھل کھٮ۪ن۔\n22. {یُس} زنانہِ لبان چُھہ سُہ چُھ رٔسِتھ تہٕ خداوند سُند عنایت حٲصِل کٔرِتھ۔\n23.\\tبیچارہ چھہ التجا ورتاوان۔ مگر امیر چھہ تقریبا جواب دوان۔\n24.\\tانسان یُس یارس آسہِ پانس دوستی کرُن: تہٕ اکھ دوس چھہ یُس بٲے کھوتہ زیادہ نزدیک روزان آسہِ۔","1.\\tسُہ غریب، یُس پننہِ دیانت منز پکان آسہِ، سہ چھہ بہتر یُس پننہِ وٹھس منز بدکار آسہِ، تہ بیوقوف۔\n2.\\tتہِ چھہ {یہ} روح علمہ ورٲے {بنہِ}، {یہ} چھہ نہ اصل۔ تہٕ یُس پنہٕ نِس قدمو سٍتـ̡ جلدی کران چُھ، سُہ چُھ گناہ کران۔\n3. انسان سٕنز بیوقوفی چھے تٔمِس وتہِ رُٹان: تہٕ تٔمۍ سُند دِل چُھ خداوند سٕندِس سٍتـ̡ پریشان۔\n4. دولت چھِ واریاہ دوس بناوان۔ مگر غریب چھہ ہمساین نِش الگ سپدان۔\n5. اپُز گواہ گژھِ نہٕ سزا دِنہٕ یُن، تہٕ یُس اپُز بولان آسہِ سُہ گژھِ نہٕ ژلِتھ۔ {غیر سزا: ہیب۔ بے گناہ قرار دِنہٕ}\n6. واریاہ چھِ شہزادٕ سٕندِ عنایت ہٕنز درخواست کران: تہٕ پرٮ۪تھ کانہہ انسان چُھ تٔمِس سُند دوس آسان یُس تحفہٕ دِوان چُھ۔ {ہم...: ہیب۔ تحفن ہُند انسان}\n7.\\tغریبن ہٕندِ سارِنٕے بٲے چھِ أمِس سٍتـ̡ نفرت: تٔمۍ سٕندِس یارس کوتاہ زیادٕ چھِ أمِس نِش دور۔ سُہ چُھ {تِمن ہٕندِس لفظس سٍتـ̡ تعاقب کران، {توتہِ} چُھ تِم {أمِس} یژھان۔\n8.\\tیُس عقل حٲصل کران چُھہ سُہ چُھ پننِس روحس سٍتـ̡ محبت کران: یُس سمجھ تھاوان چُھ، سُہ میلہِ نیکی ۔ {حکمت: ہیب۔ اکھ دل}\n9.\\tاپُز گواہ گژھِ نہٕ سزا دِنہٕ یُن، تہٕ یُس اپُز بولہِ سُہ گژھِ فنا سپدُن۔\n10.\\tبیوقوفس خٲطرٕ چھُنہٕ خوشی لایق۔ أکِس نوکر سٕندِ خٲطرٕ چھُ شہزادن پیٹھ حکمرٲنی کرُن واریاہ کم۔\n11. انسان سٕنز صوابدید چھے تٔمۍ سٕندِس غصس موخر کران۔ تہٕ {یہ} چُھ تٔمۍ سُند جلال زِ سُہ چُھ کُنہِ خلاف ورزی پیٹھ گزرُن۔ {صوابدید: یا، دانشمند}\n12.\\tبادشاہ سُند غصہٕ چُھ شیر سٕندِ گُرجہٕ ہٕندۍ پٲٹھۍ۔ مگر تٔمۍ سُند احسان {چُھ} گاسہٕ پیٹھ شبنم ہٕندۍ پٲٹھۍ۔\n13.\\tبیوقوف نیچو چھہ پننس مٲلس سُند آفت تہ زنانہِ ہند استدلال چھہ مسلسل تراوان۔\n14.\\tگرٕ تہٕ دولت چھِ مٲلن ہٕنز وراثت: تہٕ خداوند سٕندِ طرفہٕ اکھ ہوشیار خانٛدارِنہِ {چُھ}۔\n15.\\tسُہ چُھس سٍتـ̡ تہٕ بیکار روح گژھہِ فاقہٕ کھسنہٕ۔\n16. یُس حکمس پیٹھ عمل کران چُھ، سُہ چُھ پنُن روح رژھران۔ {مگر} یُس تٔمۍ سٕنزِ وتہِ سٍتـ̡ حقارت کرِ، سُہ چُھ مَرُن۔\n17. یُس غریبس پیٹھ رحم چُھ کران سُہ چُھ خداوند سُند دِل دِوان۔ تہٕ یُس تٔمۍ دِیُت سُہ دِیہِ سُہ دُبارٕ دِنہٕ۔ {سُہ یُس...: یا، تٔمۍ سُند عمل}\n18.\\tوۅمید آسنہ کِنۍ کٔرِو پننِس نیچوِس سزا تہٕ تٔمۍ سٕندِس روٝحہٕ سٍتـ̡ گژھہِ نہٕ پنُن روح بچاونہٕ۔ {for...: یا، تٔمۍ سٕنزِ تباہی خٲطرٕ: یا، أمس مرُن}\n19.\\tسٍتـ̡ سٍتـ̡ یێلہِ یێلہِ تہٕ یێلہِ تہِ دُبارٕ دُبارٕ کٔرِو۔ {do: Heb. add}\n20.\\tمشورٕ بوزِو، تہٕ ہِدایَت حٲصِل کٔرِو، یُتھ زِ تُہۍ گژھِو پَنٕنِس ٲخری کِس نتیجس مَنٛز عقلمند بٔنِتھ۔\n21.\\tانسان سندِس دلس منز چھہِ واریاہ آلہ آسان۔ بہر حال خداوند سُند مشورٕ، یُس کھڑا روزُن۔\n22.\\tانسان سٕنز خواہش چھے تٔمۍ سٕنز مہربانی تہٕ غریب انسان چھُ اپزٕ کھۅتہٕ بہتر۔\n23. خداوند سُند خوف {زندگی کُن} تہٕ {یُس یہِ آسہِ} روزِ مطمئن۔ أمِس گژھِ نہٕ بُرٕ سٍتۍ وابستہٕ۔\n24.\\tکُنہِ\n25.\\tکُنہِ تہِ کٔرِتھ تہٕ سُہ کرِ عٔلِم سمجُن۔ {خبردار روزُن: ہیب۔ ہوشیار آسہِ}\n26.\\tیُس یُس پننِس مٲلِس ضایع کران چُھ، {تہٕ} سُہ چُھ سُہ نیچو یُس شرم کٔرِتھ تہٕ ملامت کران چھُ۔\n27.\\tمیانہِ نیچو، یہ ہدایت بوزُن بند کرُن {یُس علمہ کین کلامَن سٍتـ̡ غلطی ہُند سبب بنان چھُ۔\n28.\\tاکھ بد گَواہ چُھ فٲصلس حقارت کران: تہٕ بدکار سُند اوس بدکار سُند منہ گُرِ کھیوان۔ {an...: Heb. بیلیال سُند گواہ\n29.\\tفیصلہٕ چھِ بیوقوفن ہٕندِ خٲطرٕ تیار کرنہٕ آمٕتۍ، تہٕ بیوقوفن ہٕندِ خٲطرٕ چھِ دِنہٕ یِوان۔","1.\\tشرابہٕ چُھہ ٹھٹھہٕ کَرُن، تَخلیٖق کَرنہٕ آمُت، تہٕ یُس تہٕ یُس دھوکہٕ دِنہٕ یِوان چُھ، سُہ چُھ نہٕ عقلمند۔\n2. بادشاہ سُند خوف چُھ شیر سٕندِ گُرجہٕ سٕندِس پٲٹھۍ: {یُس} چُھ أمِس غصہٕ دِنہٕ خٲطرٕ اِشارٕ دِوان سُہ چُھ پننِس روحس خلاف گۅناہ کران۔\n3. {یہِ} چھُ أکِس انسانس خٲطرٕ عزت، مگر پرٮ۪تھ کانہہ بیوقوف آسہِ مداخلت کران۔\n4.\\tسردی کنۍ چھہ نہ کُنہِ {لہذا} گژھہِ سُہ فصلس منز منگُن، تہٕ {آسہِ} نہٕ کیٚنٛہہ۔ {سرد: یا، وند}\n5. انسان سٕندِس دِلس مَنٛز مشورٕ {چُھ} سرٛنِس آبس ہیوٗ ؛ مگر اکھ سمجھدار انسان کرِ یہ نیبر۔\n6.\\tاکثر انسان چھہِ پریتھ کٲنسہِ پننہِ نیکی ہند اعلان کران: مگر اکھ وفادار انسان یُس ژھانڈِتھ ہیکہِ؟ {نیکی: یا، نعمت}\n7. عادل {انسان} چُھ پننہِ دیانت سٍتـ̡ پَکُن: تٔمۍ سٕندِ شُرِ {چھِ} أمِس پتہٕ بابرکت ۔\n8. یُس بادشاہ یُس فیصلہٕ کِس تختس پیٹھ بِہِتھ چُھ، سُہ چُھ پنٕنِس أچھو سٍتـ̡ سارِنٕے بُرٲیی ژٔٹِتھ دِوان۔\n9. کُس ہیکہِ ؤنِتھ، میہ چُھہ پنُن دِل صاف کورمُت، بہٕ چُھس پنُن گۅنہٕ نِش پاک؟\n10.\\tمختلف وزن، {تہٕ} مختلف وزن، یم دۅشوے چھہِ خداوند سندِ خاطرہ ہِوۍ مکروہ ۔ {متنوع وزن: ہیب۔ اکھ کنہ تہٕ اکھ کن} {divers پیمانہٕ: Heb. اکھ ایفا تہٕ اکھ ایفاہ}\n11.\\tشُر تہِ چھہ پننہِ عملہِ سٍتۍ زاننہ یوان، چاہے تمۍ سنز کٲم خالص آسہِ، تہ کیا یہ چھہ صحیح۔\n12.\\tبوزُن کُن تہٕ وُچھن وٲلِس أچھ، خداوند چھُ یِم دۅشوے تہِ بنٲومٕتۍ۔\n13.\\tنِندرِ سٍتـ̡ گژھہِ نہٕ محبت، یێلہِ گژھہِ غریبی ہُند شکار سپدُن۔ پَنٕنۍ أچھ کھولِو، {تہٕ} تہٕ ژٕ روزٕ روٹی سٍتۍ مطمعین۔\n14.\\t{یہِ} چُھہ نہٕ، {یہِ چُھ} نہٕ، خٔریٖدار چُھ ونان: مگر ییلہ سُہ پننہِ وتہِ نیرِ، تیلہِ چُھ سُہ فخر کران۔\n15.\\tسۄن تہٕ سُہ چُھہ واریاہ یاقوت: مگر علمُک وُٹھ چُھہ اکھ قیمتی جوہر۔\n16.\\tتٔمۍ سُند پلو رٔٹِتھ یُس أکِس اجنبی سٕندِ خٲطرٕ ضامن آسہِ: تہٕ أمِس نِش کٔرِو أکِس اجنبی زنانہِ ہٕندِ خٲطرٕ عہدٕ۔\n17.\\tدھوکہ دہی ہٕنز روٹی چھیہ انسانس خٲطرٕ میٹھۍ۔ مگر امہ پتہ گژھہِ تس ٲسس بٔرِتھ بٔرِتھ۔ {دھوکہٕ: ہیب۔ اپُز، یا، اپُز}\n18. {پرٮ۪تھ کُنہِ} مقصد چُھ مُشیرٕ سٍتۍ قایم سپدان: تہٕ اصل مشورٕ سٍتۍ کٔرِو جنگ۔\n19.\\tیُس افسانہٕ نگار یُس اندۍ پکھۍ گژھان چُھ، سُہ چھُ راز ظٲہر کران: لہذا گژھ نہٕ تس سٍتـ̡ مداخلت یُس تٔمۍ سٕندِس چپنہٕ سٍتـ̡ خوشامد کران چُھ۔ {چاپلوسی: یا، لالچ}\n20. یُس تہِ پننِس مٲلِس یا ماجہِ بد دُعا کرِ، تٔمۍ سُند شمع گژھہِ مبہم گٹہِ مَنٛز ژھیوراونہٕ۔ {چراغ: یا، شمع}\n21.\\tاکھ وراثت {ہیکہِ ٲسِتھ} یُس شروعاتس منز جلدی سان حٲصل سپدِ۔ مگر اَمہ کِس اندس گژھہِ نہٕ برکت دِنہٕ۔\n22. یہ نہ ونُن، بہٕ کرٕ بدی ہُند بدلہٕ۔ {مگر} خداوند سُند انتظار کرُن، تہٕ سُہ کرِ تۅہہ بچاو۔\n23.\\tمختلف وزن چھہ خدایہ سندِ خاطرہ مکروہ آسان۔ تہٕ اکھ غلط توازن {چُھ} چُھ نہٕ اصل۔ {اکھ غلط...: ہیب۔ دھوکہ دہی ہند توازن}\n24.\\tانسان سُند چُھہ خداوند سٕندِس سٍتـ̡ {چُھ}۔ تیلہِ کِتھ کٔنۍ ہیکہِ انسان پنُن طریقہٕ سمجِتھ؟\n25. {یہ} چُھ تٔمِس شخصس خٲطرٕ اکھ جال {یُس} یُس {یُس} مقدس چُھ، تہٕ پرژھہ گٲر کرنُک عہد کران چُھ۔\n26.\\tاکھ عقلمند بادشاہ چُھ بدکارن پھٔٹِتھ تہٕ تِمن پیٹھ چکرٕ انان۔\n27.\\tانسان سُند روح چُھ خداوند سٕنز شمع، یُس یٔڈ ہٕندِس سارِنٕے اندرمِس حِصس ژھانڈان چُھ۔ {موم بتی: یا، چراغ}\n28.\\tرحم تہٕ سچائی چھِ بادشاہس رژھراوان تہٕ تٔمۍ سُند تخت چھُ رحمتہٕ سٍتۍ رژھران۔\n29.\\tجوانن ہُند جلال چھُ تِہُند طاقت: تہٕ بُزرگ سٕنز خوبصورتی چھِ سُرِ کلہٕ۔\n30.\\tزخمُک نیل چھُ بُرِس صاف کران: یِتھٕ پٲٹھۍ چھُ یٔڈ کِس اندرمِس حِصس کٔرِتھ۔ {صفائی...: ہیب۔ اتھ خلاف چُھ صاف کرنُک دوا}","1. بادشاہ سُند دِل چُھ خداوند سٕندِس اتھس منز، یِتھٕ پٲٹھـ̡ آبہٕ کِس دریاوَس مَنٛز: سُہ چُھ یێتہِ تہِ پھیران۔\n2. انسان سُند پریتھ طریقہ چُھ تٔمۍ سٕنزِ نظرِ منز صحیح، مگر خداوند چُھ دلن پیٹھ غور کران۔\n3. انصاف تہٕ فیصلہٕ کرُن چُھہ قربانی کھۅتہٕ زیادٕ قبول۔\n4.\\tاکھ تھدِ نظر، تہٕ اکھ مغرور دِل، {تہٕ} بدکارن ہُند ہل چلاوُن، {چُھ} گۅناہ۔ {an...: Heb. اچھن ہند غرور} {ہل چلان: یا گاش}\n5. محنتی ہٕندِس خیالس چھُ صرف کثرت کُن۔ مگر پریتھ کٲنسہِ ہُند {یعنی} چھُ صرف یژھان۔\n6.\\tخزانہٕ حٲصل کرُن چھہ اکھ باطل یُس موت ژھاران چھُ۔\n7.\\tبدکارن ہٕندِ لوٹ مار سٍتـ̡ گژھہِ تِم تباہ کرنہٕ۔ تکیازِ تم چھہِ فیصلہ کرنہ نش انکار کران۔ {تباہ...: ہیب۔ وُچھمُت، یا تمن سٍتۍ روزُن}\n8.\\tانسان سند طریقہ چھہ بے راہ روی تہ عجیب مگر {یوت تام پاک} چھہ تسند کٲم {صحیح}۔\n9.\\tیہ چھہ مکانہ کس کونس منز روزُن بہتر، بٔڈۍ مکانس منز لڑایہِ زنانہِ سیتۍ روزُن۔ {اکھ لڑایہ...: ہیب۔ اکھ زنانہٕ تنازعہٕ} {a wide...: Heb. معاشرک اکھ گھر}\n10.\\tبدکار سُند روح چُھ بد خواہش: تٔمۍ سٕندِس ہمساین چھُنہٕ أمِس نظرِ منز کانہہ احسان میلان۔ {findeth...: ہیب۔ چُھ نہٕ پسندیدٕ}\n11.\\tییلہ بدمعاشس سزا دِنہٕ ییہِ، سادٕ چھُ عقلمند بناونہٕ یوان: تہٕ ییلہ دانشمندس ہدایت دِنہٕ ییہِ، سُہ چُھ علم حٲصل کران۔\n12.\\tنیک {انسان} چُھ بدکارن ہٕندِس گرس سٍتـ̡ عقلمندی سان سمجھان: {مگر خدا} چُھ بدکارن {تِہندِ} بدکارس سٍتـ̡ ختم کران۔\n13.\\tیُس غریبن ہٕندِس فریاد سٍتـ̡ کُن رُکٲوِتھ چُھہ سُہ تہِ روُن، مگر بوزنہٕ ییہِ نہٕ۔\n14.\\tاکھ تحفہٕ یُس ژوٗرِ پٲٹھـ̡ غصہٕ دوٗر کران چُھ: تہٕ سٍتـ̡\n15.\\tانصاف کرن والٮ۪ن ہٕندِ خٲطرٕ چُھ خوشی مگر بدکار کارن ہٕندِ خٲطرٕ گژھہِ تباہی۔\n16.\\tیُس انسان سمجھہٕ کِس وتہِ نِش نیران چُھ، سُہ گژھہِ مرن ہٕنزِ جماعتس مَنٛز روزُن۔\n17.\\tیُس لذتُک محبت کرُن آسہِ سُہ گژھہِ غریب: یُس شرابس تہٕ تیٖلس محبت کران آسہِ سُہ گژھہِ نہٕ امیر آسُن۔ {خوشی: یا، کھیل}\n18.\\tبدکار گژھہِ نیکوکارن ہٕندِ خٲطرٕ فدیہ تہٕ بدکار بنہِ نیکوکارن ہٕندِ خٲطرٕ۔\n19.\\tبیابانس منز روزُن چھہ بہتر زِ اکس متنازعہ تہ شرارتی زنانہِ سیتۍ روزُن۔ {منز...: ہیب۔ صحرا کِس سرزمینس منز}\n20.\\tعقلمندن ہٕندِس مکانس مَنٛز چھُ خزانہٕ تہٕ تیٖل۔ مگر اکھ بیوقوف انسان چُھ یہٕ خرچ کران۔\n21. یُس نیکی تہٕ رحمتہٕ پتہٕ پیروی کران چُھ، سُہ چُھ زندگی، راستبازی تہٕ عزت میلان۔\n22.\\tاکھ دانا {انسان} چُھ طاقتورن ہٕندِس شہرس پیٹھ کھسان، تہٕ اَمہ سٕندِس اعتمادُک طاقت کم کٔرِتھ۔\n23. یُس پَنُن ٲسِس تہٕ زبان تھاوان چُھ، سُہ چُھ پنٕنِس روحس مصیبت نِش بچاوان ۔\n24.\\tمغرور {تہٕ} مغرور چھُ تٔمۍ سُند ناو، یُس فخرس سٍتۍ وابستہٕ چھُ۔ {فخر...: ہیب۔ فخرٕ کِس قہر منٛز}\n25. سُہ چُھ سُہ ماران۔ تکیازِ تمۍ سند اتھہ چھہ محنت کرنہ نش انکار کران۔\n26. سُہ چُھ سارِوٕے دۅہس لالچ سٍتـ̡ لالچـ̡ تھاوان: مگر نیک چُھ دِوان تہٕ دِوان نہٕ۔\n27.\\tبدکار سُند قربانی چھُ مکروہ کُن: کوتاہ زیادٕ، {ییلہ} سُہ بدکار ذہنس سٍتۍ انان؟ {with...: Heb. بدکاری منز؟}\n28.\\tاکھ اپُز گواہ گژھہِ ختم سپدُن، مگر یُس شخص بوزان آسہِ سُہ چُھ مسلسل کتھ کران۔ {A...: Heb. اپزُک گواہ}\n29.\\tبدکار چُھ پَنُن بُتھ سخٕت کَران، مگر {یێلہِ} سُہ چُھ پَنُن وَتھ دِوان۔ {ڈایریکٹ: یا، غور کٔرتھ}\n30. خداوند سٕندِس خلاف چُھہ نہٕ کانہہ حکمت، نہ سمجھ تہٕ مشورٕ۔\n31.\\tگُرِ {چُھ} جنگہٕ کِس دۅہہٕ خٲطرٕ تیار کرنہٕ آمُت: مگر خداوند سٕنز حفاظت {چُھ}۔ {حفاظت: یا، فتح}","1. اکھ {اصل} ناو {چُھ} بٔڈ دولت، {تہٕ} رۄپہٕ تہٕ سۄنہٕ بجایہ محبتہٕ سان پسندیدٕ۔ {محبت...: یا، احسان چُھ بہتر وغیرہ}\n2. امیر تہٕ غریب چھِ اَکہٕ وٹہٕ مِلان: خداوند چُھ یِمن سارِنٕے ہُند بناون وول ۔\n3.\\tاکھ ہوشیار انسان چھہ بدی ہند پیش گویی کران تہ پانس چھہ پوشہ تھاوان: مگر سادہ انسان چھہ پتھ کُن نیران تہ سزا دِوان۔\n4. انکسار سٍتـ̡ {تہٕ}خداوند سٕندِ خوفہٕ سٍتـ̡ چُھہ دولت، عزت تہٕ زندگی سٍتـ̡ ۔ {از...: یا، انکساری ہند انعام، وغیرہ}\n5.\\tکُنہِ تہِ پھیُرِ ہٕندِس وتہِ منز: یُس پنُن روح رژھراوان آسہِ سُہ آسہِ تِمن نِش دور۔\n6. أکِس شُرِس تربِیت دِیِو تِتھٕ پٲٹھۍ: تہٕ ییلہ سُہ بُزرگ آسہِ، سُہ گژھِ نہٕ اَمہِ نِش نیرُن۔ {ٹرین...: یا، کیٹیچیز} {منز...: ہیب۔ تٔمۍ سٕنٛدس طریقس منٛز}\n7.\\tامیر چھُ غریبَن پیٹھ حکوٗمت کران، تہٕ قرٕض دار چھُ قرض دِنہٕ وٲلِس سُند خادم۔ {قرض دِنہٕ وول: ہیب۔ سُہ انسان یُس لینڈِتھ دِوان چھُ}\n8.\\tیُس بدکاری کرِ، سُہ گژھہِ باطل تہٕ تٔمۍ سٕندِس شرارتُک لٔر گژھہِ ناکام۔ {لاٹھ...: یا، پننہِ شرارت ہٕنزِ لٔرِ سٍتۍ گژھہِ سُہ کھٮ۪نہٕ}\n9. یٔمِس أچھ سٍتـ̡ سٍتـ̡ برکت آسہِ۔ تکیازِ سُہ چُھ پنٕنۍ روٹی غریبن دِوان۔ {سُہ یہ...: ہیب۔ اچھ گُڈ آف اچھ}\n10. کُنہِ آ، جھگڑا تہٕ ملامت گژھہِ ختم۔\n11.\\tیُس دِل پاکیزگی پسند کران آسہِ، {تکیازِ} بادشاہ آسہِ تسُند دوس۔ {for...: یا، تہٕ تٔمۍ سٕندِس وٹھس منز فضل چُھ}\n12.\\tخداوند سٕنزِ أچھ چھے علمس رژھراوان تہٕ سُہ چھُ نافرمان سٕندِس کلامَس ختم کران۔ {الفاظ: یا، معاملات}\n13.\\tسُہ چھُ وَنُن زِ اَمہِ وِزِ چھُ سٕہہ سٕندِس سٍتـ̡\n14.\\tعجیب زنانن ہُند اوس اکھ سرٛوٚن کھۄد: یُس خداوند سٕندِ سٍتـ̡ نفرت آسہِ سُہ گژھہِ اَتھ مَنٛز وسُن۔\n15.\\tبیوقوفی چھیہ شُرۍ سٕندِس دلس منز بند۔ {مگر} اصلاح ہٕنز لٔر کرِ أمِس نِش دور۔\n16.\\tیُس غریبن پیٹھ ظلم کرِ، تہٕ یُس امیرن دِوان چُھ، سُہ گژھہِ یٔقیٖنی طور محتاج۔\n17. پَنُن کَن کٔرِو نمُن، تہٕ بوٗزِو دانشمندَن ہٕنز کلام، تہٕ پَنُن دِل کٔرِو میانہِ عٔلمہٕ سٍتـ̡ استعمال۔\n18.\\tتکیازِ یہ چھہ اکھ خۅش کن چیز اگر تم پانس اندر تھٲوِتھ تھٲوِو۔ تِم گژھن تُہٕندِس وٕٹھس منز فِٹ۔ {اندر...: ہیب۔ پننہِ یٔڈ منز}\n19. یێلہِ چُھہ تُہُند بھروسہٕ خداوند سٍتـ̡ آسُن، مے چُھہ ژے از تہِ زانمُت۔ {حتیٰ کہ...: یا تہِ کرو بھروسہ}\n20. کیا مے چُھہ نہٕ ژے مشورن تہٕ علمس مَنٛز بہترین کتھ لیچھمٕژ،\n21.\\tیُتھ بہٕ ژے حقیقتٕکۍ کلامَن ہُند یقین زانہٕ دِتھ۔ یُتھ زن ژے تِمن سٍتـ̡ {تِمن خٲطرٕ...: یا تِمن خٲطرٕ یِم ژےٚ سوزان چھِ؟}\n22.\\tغریبس نہ لوٹُن، تکیازِ سُہ چُھہ غریب: نہ کرِ دروازس منز مُصیبت زدہ سٍتـ̡ ظُلم:\n23.\\tیِکیازِ خداوند کرِ تِہٕندِس مقصدس سٍتـ̡ وُچھِتھ تہٕ تِمن ہُند روح کرِ خراب یِمو تِمن ہٕندِس سٍتـ̡ خراب کٔرِ۔\n24. کٲنسہ ناراض نفرس سٍتۍ کرو نہ دوستی۔ تہٕ أکِس غٲلب نفرس سٍتۍ گژھِو نہٕ ژیہ گژھُن:\n25. یێلہِ گژھہِ تٔمۍ سٕنزِ وتہٕ ہیچھناوٕن، تہٕ پنہٕ نِس روحس سٍتـ̡ پھنس۔\n26.\\tتِمن منز گژھ نہٕ یِمن منز اَتھٕ دِنہٕ یِنہٕ وٲلۍ، {یا} یِمن منز قرضن ہٕندِ ضامن آسہِ۔\n27.\\tاگر نہٕ تۅہہِ کانہہ معاوضہ چُھ، سُہ کیازِ تُہند بسترٕ ژٔٹِتھ؟\n28.\\tقدیم نشان ہٹٲوِو نہٕ، یُس تہندیو مٲلیو مقرر کورمُت چھُ۔ {لینڈ مارک: یا، باؤنڈ}\n29.\\tژیہ چھکھ اکھ انسان پننس کاربارس منز محنتی وچھان؟ سُہ گژھہِ بادشاہن برونہہ کنہِ کھڑا روزُن۔ سُہ گژھِ نہٕ مطلب {مرد} برونہہ کُن کھڑا گژھُن۔ {مطلب...: ہیب۔ مبہم مرد}","1.\\tییلہ ژیہ کُنہِ حکمرانس سٍتۍ کھٮ۪نہٕ خٲطرٕ بِہِتھ، غور کرِو پانس برونہہ کُن کیا چھُ:\n2.\\tتہٕ اگر ژیہ بھوک دِنہٕ آمُت چھُو، تہٕ پننِس حلقس پیٹھ تھپھ کٔرِتھ۔\n3.\\tتٔمۍ سٕندِس لذیذ سٍتۍ گژھ نہٕ خۅش گژھُن: تِکیازِ تِم چھِ دھوکہٕ دِنہٕ آمُت۔\n4.\\tمحنت کٔرِو نہٕ امیر آسنہٕ خٲطرٕ: پننہِ عقلہٕ نِش کٔرِو بند۔\n5. کیا ژیہ کٔرِو تتھ چیزس پیٹھ نظر یُس نہٕ چُھ؟ {دولت} کیازِ چھہ یقینا پانس پکھہ بناوان۔ تِم چھِ عقاب سٕندۍ پٲٹھۍ جنتس کُن وٕڑان۔ {سیٹ...: ہیب۔ پنٕنۍ أچھ وُڑن}\n6. یٔمِس بد نظر آسہِ تٔمِس سٕنز روٹی مہٕ کھیٚیُن، تہٕ نہ کرٕ تٔمۍ سٕندِس لذیذ مازٕچ خواہش۔\n7.\\tیُتھ زن سُہ پننِس دِلس مَنٛز سوچان چُھ، تِتھے پٲٹھـ̡ چُھہ سُہ چُھہ: کھیٛو تہٕ پیو، سُہ چُھہ ژے ونان مگر تٔمۍ سُند دِل {چُھ} نہٕ ژےٚ سٍتـ̡ سٍتـ̡ ۔\n8.\\tیُس ژیہ کھیوٚو، سُہ گژھہِ اُلٹی کٔرِتھ تہٕ پَنٕنۍ مٔٹھۍ کَلام۔\n9.\\tبیوقوف سٕندِس کنن منز گژھ نہٕ کتھ کرنہٕ، تکیازِ سُہ کرِ تُہنزِ کلامٕچ حکمتٕچ حقارت ۔\n10. پرٛون لینڈ مارک ہٹٲوِو نہٕ؛ تہٕ یِمن ہٕندِس کھہس منز اژُن نہٕ: {لینڈ مارک: یا، پابند}\n11. تِہٕندِس نجات دِنہٕ وٲلِس {چُھ} طاقتور سٍتـ̡ سُہ کرِ تِہُند مقدمہٕ ژےٚ سٍتـ̡ کَرنہٕ۔\n12. پَنُن دِل کٔرِو ہِدایتَس سٍتـ̡ تہٕ پَنٕنـ̡ کَن کٔرِو علمہٕ کِس کلامَس سٍتـ̡ استعمال۔\n13. شُرِس نِش گژھِ نہٕ اصلاح کٔرِتھ، تِکیازِ اگر ژے أمِس لٔرِ سٍتـ̡ مار دِیہِ، سُہ گژھِ نہٕ مَرُن۔\n14. ژے دِیُکھ أمِس لورِ سٍتـ̡ مارُن، تہٕ دِیُن أمِس جہنم نِش نجات دِنہٕ۔\n15. میانہِ نیچو، اگر چانہِ دِل عقلمند آسہِ، میون دِل تہِ گژھہِ خۅش۔ {حتیٰ کہ...: یا، بہٕ تہِ کرٕ خوشی}\n16. آ، میٲنۍ لگام گژھہِ خۅش، ییلہ چانہِ وٹھ صحیح کتھ کرِ۔\n17. پَنُن دِل گژھہِ نہٕ گۅنہگارن سٍتـ̡ حسد کٔرِتھ، بلکہ روزُن سارِوٕے دۅہس خداوند سٕندِس خوفس مَنٛز۔\n18.\\tیقینا چھہ اکھ اند۔ تہٕ تہنز وۅمید گژھِ نہٕ ختم کرنہٕ۔{اختتام: یا، انعام}\n19.\\tبوزو میانہِ نیچو، تہٕ بٔنِو دانا تہٕ پَنُن دِل وتہِ وَتہِ وَتھ کَرُن۔\n20. شراب بِبرَن منٛز گژھِ نہٕ ماز کھٮ۪نہٕ والٮ۪ن مَنٛز: {مازُک: حب۔ تہندِ مازُک}\n21.\\tشرابس تہٕ لالچ گژھہِ غریبی ہُند شکار: تہٕ نندر گژھہِ انسانس لٔگِتھ پوشہٕ۔\n22.\\tپننِس مٲلِس سٍتـ̡ بوزُن یُس ژے زامُت چُھ، تہٕ بُزرگ گژھنہٕ وِزِ کٔرِو نہٕ پننہِ ماجہِ سٕنز حقارت ۔\n23.\\tحقیقژ ہینہ تہ نہ کٕنُن۔ {تہِ}حکمت، تہٕ ہدایت، تہٕ سمجھ۔\n24.\\tنیک سُند مول گژھہِ سٮ۪ٹھاہ شاد تہٕ یُس عقلمند بچہٕ پٲدٕ کرِ، سُہ گژھہِ أمِس سٍتـ̡ خۅش سپدُن۔\n25. تُہُند مول تہٕ تُہٕنٛز موج گژھِ خۄش، تہٕ یُس ژےٚ زیٚنہٕ آسہٕ سُہ خۄش۔\n26. میانہِ نیچو، پنُن دِل دِیُن تہٕ پَنٕنۍ أچھ گٔژھ میانہِ وتہِ وُچھان۔\n27.\\tکُنہِ تہٕ اکھ عجیب زنانہٕ {چِھ} اکھ تنگ گڑھ۔\n28.\\tسۅ تہِ چھیہ شکارس منز روزان تہ انسانس مَنٛز چھہ زیادتی کران۔ {یِتھ کٔنۍ...: یا، بطور ڈاکو}\n29. کُس چُھ مصیبت؟ کُس چُھ غم؟ کُس چُھ تنازعہٕ؟ کُس چُھ کُس چُھ کُس چُھ؟ کُس چُھ بے وجہ زخم؟ کُس چُھ أچھ وۄزل؟\n30.\\tتِم یِم شرابس منز واریاہس کالس روزان چھِ۔ تم یم رلہٕ مِلہٕ شراب ژھارنہٕ خٲطرٕ گژھان چھِ۔\n31.\\tشرابس وُچھِو نہٕ ییلہ سُہ وۄزُل آسہِ، ییلہ سُہ پیالہ منز پنن رنگ دِوان چھُ، {ییلہ} یہ پانس سیتۍ پکناوان چھُ۔\n32.\\tٲخرس پیٹھ چھہ یہ ناگ ہیو ژٹان تہ اڈرس ہندۍ پاٹھۍ ڈنگہ لگان۔ {an...: یا، اکھ کاکیٹریس}\n33. چانہِ أچھ وُچھن عجیب زنانہٕ، تہٕ تُہند دِل کرِ غلط کتھہٕ کٔرِتھ۔\n34.\\tآ، تۅہہ گژھہِ سُہ یُس سمندرس منز بٔرِتھ آسہِ، یا یُس مستولس پیٹھ بٔرِتھ آسہِ۔ {درمیان...: ہیب۔ سمندرُک دل}\n35.\\tتِمو دِژ میہ مار، {ژیہ وَنُن، تہٕ بہٕ اوسُس نہٕ بیمار۔ تِمو دِژ میہ مار، {تہٕ} میہ باسیوو {یہ} نہٕ: بہٕ کر بیدار؟ بہٕ کَرٕ بییہِ اکہِ لٹہِ یہِ ژھانڈان۔ {میہ کوٚر محسوس...: ہیب۔ میہ ٲس نہ یہ خبر}","1. بدکار نفرن سٍتـ̡ گژھہِ نہٕ حسد تہٕ تِمن سٍتـ̡ روزنُک خواہش۔\n2.\\tتِمن ہُند دِل چھُ تباہی ہُند مطالعہ کران، تہٕ تِہٕندِس وَٹھ چھِ شرارتٕچ کتھ کران۔\n3. حکمت سٍتـ̡ چُھ اکھ گرٕ بناونہٕ آمُت۔ تہٕ سمجھنہٕ سٍتۍ چُھ یہ قایم سپدان:\n4. تہٕ علمہٕ سٍتـ̡ گژھن خانہٕ سارِنٕے قٕمتی تہٕ خۅش گَژھن سٍتـ̡ بٔرِتھ۔\n5.\\tعقلمند انسان {چُھ} مضبوط۔ آ، علمُک انسان چھُ طاقت ہُران۔ {مضبوط: ہیب۔ چُھ طاقتس منز} {اضافہ...: Heb. طاقت دِوان مضبوط}\n6.\\tتکیازِ عقلمند مشورٕ سٍتـ̡ کٔرِو تُہۍ پنُن جنگ: تہٕ مشیرن ہٕندِس تعدادس مَنٛز چُھ محفوٗظ۔\n7. حکمت چھے بیوقوفس خٲطرٕ واریاہ تھوٚد: سُہ چُھ نہٕ دروازس منز پنُن بوش کھولان۔\n8.\\tیُس بد کار کرُن آسہِ تس گژھہِ شرارتی قرار دِنہٕ۔\n9.\\tبیوقوفی ہُند خیال {چُھ} گۅناہ: تہٕ کُنُن {چُھ} انسانس خٲطرٕ مکروہ ۔\n10. {اگر} مُصیبت کِس دۅہس منز بیہوش گژھِو، تُہند طاقت {چُھ} کم۔ {لوٚکٹ: ہیب۔ تنگ }\n11.\\tاگر تۅہہ مارنہٕ خٲطرٕ تیار تہٕ یِم مارنہٕ خٲطرٕ تیار چھِ، تہٕ یِم مارنہٕ خٲطرٕ تیار چھِ۔\n12.\\tاگر ژیہ ونان، وچھو، اسہِ ٲس نہ یہ خبر۔ یُس دِلس پیٹھ غور کران چُھ، سہ چھا نہٕ اتھ پیٹھ غور کران؟ تہٕ یُس تُہند روح رژھراوان چُھ، سُہ چُھ نہٕ پتاہ {یہ}؟ تہٕ کیا سُہ {نہ} پننین کامین مطٲبق {پرٮ۪تھ کٲنسہ} انسانس پیش کرُن؟\n13.\\tمیانہِ نیچو، کھیوٚو ماچھ، تکیازِ یہ چھہ اصل۔ تہٕ شہد چھُ، {یُس} تُہندِ ذوق خٲطرٕ موٚدُر چھُ: {to...: Heb. تُہٕندِس تالس پیٹھ}\n14.\\tتێلہِ گژھہِ حکمت ہُند عٔلِم تہٕ تێلہِ گژھہِ نہٕ تُہٕندِس روحس سٍتـ̡ یێلہِ تہٕ یێلہِ تہٕ تێلہِ میلہِ اَمہ سٍتـ̡ ثواب تہٕ تُہٕنز وۅمید گژھہِ نہٕ ختم کرنہٕ۔\n15.\\tاے بدکار {انسان}، صالحن ہٕندِس مکانس سٍتـ̡ پیارُن نہٕ۔ تٔمۍ سٕنز آرام گاہ گژھِ نہٕ خراب کٔرِتھ:\n16.\\tیِہ چُھہ عادل انسان سَتھ لٹہِ پٮ۪وان، تہٕ دُبارٕ وُتھان چُھ، مگر بدکار گژھہِ شرارتس مَنٛز۔\n17.\\tییلہ تُہند دُشمن پیوٚو تہٕ پَنُن دِل گژھہِ نہٕ خۅش گژھُن:\n18.\\tیِہ گژھہِ خداوند وُچھِتھ تہٕ سُہ کرِ أمِس نِش ناراض تہٕ سُہ کرِ أمِس نِش پنُن غصہٕ۔ {یہ چھہ ناپسند...: ہیب۔ یہٕ چُھ تٔمۍ سٕنزٕ نظرن منٛز بُرٕ آسان}\n19. بد سٍتـ̡ گژھ نہٕ پانس بد کارس سٍتـ̡ پریشان کرُن، تہٕ نہ گژھ بدکارن سٍتـ̡ حسد۔ {پریشان...: یا، بدکارن سٍتۍ نہ روزُن}\n20. کیازِ بد سٍتـ̡ گژھہِ نہٕ کانہہ اَجر میلہِ۔ بدکارن ہٕنز شمع یِیہِ ژھیتہٕ کرنہٕ۔ {موم بتی: یا، چراغ}\n21.\\tمیانہِ نیچو، خداوند تہٕ بادشاہس سٍتـ̡ کھوژُن: {تہٕ} تِمن سٍتـ̡ گژھ نہٕ مداخلت یِمن بدلاونہٕ آمٕژ چھِ: {تِم...: عبرانی۔ چینجرز}\n22. تِہُند مصیبت گژھہِ اچانک وُتھ؛ تہٕ یمن دۄشوٕنی ہٕنٛز بربادی کُس چُھ پتہٕ؟\n23.\\tیم {چیز} تہِ چھہِ دانشمندن سٍتۍ تعلق تھاوان۔ {فیصلس منز نفرن ہُند احترام کرُن چُھ نہٕ اصل۔\n24. یُس بدکارن ونان چُھ، تُہۍ چُھہ نیک ۔ أمِس کٔرِن لوٗکھ لعنت، قومن کرِ أمِس نفرت:\n25.\\tمگر یُس ملامت کرِ تِمن ہٕندِ خٲطرٕ گژھہِ خۅش تہٕ تِمن ہٕندِ خٲطرٕ میلہِ رژھ رژھ نعمت۔ {اکھ اصل...: ہیب۔ نیکی ہٕنٛز برکت}\n26.\\t{پرٮ۪تھ کانہہ انسان} چُھس بوسہ دِنہٕ یُس صحیح جواب دِیہِ۔ {یہ...: ہیب۔ یُس صحیح لفظن ہند جواب دِوان چھُ}\n27. پَنٕنۍ کٲم کٔرِو تیار تہٕ بَنٲیِو پانَس خٲطرٕ مٲدانَس مَنٛز۔ تہٕ پتہٕ بناو پنُن مکانہٕ۔\n28.\\tپننِس ہمساین خلاف گژھِ نہٕ بغٲر وجہٕ گواہ بنُن۔ تہٕ چپنہٕ نِس چپنہٕ سٍتـ̡ دھوکہٕ دِنہٕ۔\n29.\\tیہ نہ ونُن، بہٕ کٔرٕ تس سٍتـ̡ یُتھ تٔمۍ میانہِ سٍتـ̡ کورمُت چُھس: بہٕ کٔرٕ أمِس سٕندِ کامہِ مُطٲبق دِنہٕ۔\n30.\\tبہٕ ووت سُہ سُند کھہٕ تہٕ انسان سٕندِس انگورس کُن یُس سمجھ نِش خالی اوس۔\n31.\\tتہ یہ سورے اوس کانٹو سٍتۍ بٔڈۍمٕتۍ، {تہٕ} کٔرِتھ ٲس اتھ بُتھِس ؤلِتھ، تہٕ اَمہ کِس کٔنِس دیوارس ٲس پھُٹمٕژ۔\n32.\\tامہ پتہ وُچھ میہ {تہٕ} وُچھمُت {یہ} تہٕ میہ وُچھ {یہِ} تہٕ دِژ ہدایت۔ {غور کرنہٕ...: ہیب۔ میون دل سیٹ کٔر}\n33. {توتہِ} رژھ کھنڈ نندر ، رژھ کھنڈ نندر ، رژھ کھنڈ اتھہ پھیُرُن:\n34.\\tیِتھے پٲٹھـ̡ گژھہِ تُہٕنز غریبی یُس سفر کرِ۔ تہٕ تُہند یژھ ہتھیار بند انسان۔ {an...: Heb. ڈھالُک آدمی}","1. یِم {چِھ} سُلیمان سٕندِ محاورٕ تہِ، یِم یہوداہ کِس بادشاہ حزقیاہ سٕندِس مردو نقل کٔرۍ۔\n2.\\tکانہہ چیز ژوٗرِ تھاوُن چھُ خدایہ سُند جلال مگر بادشاہن ہُند عزت} چھُ کانہہ معاملہٕ ژھانڈُن۔\n3. تھزرٕ خٲطرٕ آسمان، تہٕ زمینہٕ سرٛنٮ۪ر خٲطرٕ، تہٕ بادشاہن ہُند دِل چُھ نہٕ ژھانڈنہٕ لایق۔ {is...: Heb. تَتہِ چھُنہٕ کانٛہہ تلاش}\n4.\\tرۅپہِ منزہ کڈُن تہ تتہِ نیرِ اکھ بانہٕ۔\n5. بادشاہس برونہہ کُن کٔرِو بدکار نِش تہٕ تٔمۍ سُند تخت گژھہِ نیکی سٍتـ̡ قایم کرنہٕ۔\n6.\\tبادشاہ سٕندِس حضورس منز گژھ نہٕ پنُن پان برونہہ کُن، تہٕ بٔڈِس انسانس سٍتـ̡ کھڑا گژھُن: {Put...: Heb. پَنُن جلال کٔرِو نہٕ کٔرِتھ}\n7.\\tبہتر چھہ یہ وننہ یُن، ییتہِ گژھہِ یور وُچھن؛ تمہ کھوتہ زیادہ گژھہِ ژیہ شہزادہ سنزِ موجودگی منز بۅن کُن تھاونہ یُس چانہِ اچھن وچھمُت آسہِ۔\n8.\\tکوشش کرنہٕ خٲطرٕ گژھ نہٕ جلدی کٔرِتھ، نتہٕ ژیہ پتاہ زِ ٲخرس پیٹھ کیا کرُن، ییلہِ تُہند ہمساین ژیہ شرمسار کرِ۔\n9. پننِس معاملس پیٹھ کٔرِو پننِس ہمساین سٍتـ̡ بحث۔ تہٕ بییِس نِش گژھِ نہٕ کانہہ راز دریافت کٔرِتھ: {اکھ راز...: یا، راز ہُند}\n10.\\tیُس بوزان آسہِ سہ گژھہِ ژیہ شرمسار تہ تۅہہِ گژھہِ نہ پتھ کُن۔\n11.\\tاکھ لفظ چھہ رۅپہ ہنزن تصویرن منز سوننہِ ہندۍ سیبۍ۔ {فٹلی...: ہیب۔ تٔمۍ سٕندِس پہین پیٹھ کتھ کٔرِتھ}\n12.\\t﴿یِتھ﴾ سۅنہٕ ہُند اکھ بالہٕ تہٕ عمدہ سۄنہٕ سُند زیور، {یِتھٕ کٔنِتھ} فرمانبردار کنن پیٹھ اکھ دانشمند۔\n13.\\tیِتھے پٲٹھـ̡ فصلہٕ وِزِ شینہٕ ہٕندِس سردی سٍتـ̡ چُھہ تِمن سٍتـ̡ اکھ وفادار قاصد یُس أمِس سوزان چُھ، تکیازِ سُہ چُھ پننین مالکن ہٕندِس روحس تازٕ کران۔\n14.\\tیُس تہِ اپُز تحفہٕ دِوان چھُ، سُہ چُھ اوٚبرٕ تہٕ واو ہٕندِس پٲٹھۍ۔ {of a...: Heb. اپزُک تحفہٕ منز}\n15.\\tواریاہس کالس برداش کٔرِتھ چھہ اکھ شہزادہ راضی سپدان، تہ نرم زبان چھیہ اڈجہ پھٹراوان۔\n16.\\tژیہ چھکھ ماچھ لوٚبمُت؟ یوتاہ کھیوٚو تیوٗت چانہِ خٲطرٕ کٲفی آسہِ، نتہٕ گژھہِ تۅہہ بٔرِتھ تہٕ اُلٹی کٔرِتھ۔\n17.\\tہمساے سٕندِس گَرٕ منزٕ کٔرِو پَنُن کھوٚر پَنُن کھوٚر؛ متان گژھہِ سُہ تۅہہِ نِش تنگ تہٕ تۅہہِ سٍتۍ نفرت۔ {پتھ کُن...: یا، چانہِ کھۅر گژھہِ کم از کم اژُن} {تھکاوٹ...: ہیب۔ ژے سٍتۍ بھر}\n18.\\tیُس انسان پننِس ہمساین خلاف جھوٹ گوٲہی دِوان چُھ، سُہ چُھ اکھ تلوار تہٕ اکھ تیز تیر۔\n19.\\tمصیبت وِزِ أکِس بے وفا انسانس پیٹھ بھروسہ کرُن چھُ دندٕ پھُٹمُت تہٕ کھوٚر نیبر نیران۔\n20. {یِتھ} یُس سردٕ موسمس منز پلو تُلِتھ چُھ، {تہٕ یِتھٕ پٲٹھۍ} نائٹرس پیٹھ سرکہ تُلِتھ، تِتھے پٲٹھۍ چُھ سُہ یُس گۄبٕرِ دِلس گیوان چُھ۔\n21. اگر تُہند دُشمن فاقہٕ آسہِ، تمِس دِیُن کھٮ۪نہٕ خٲطرٕ روٹی دِیُن۔ تہٕ اگر أمِس پیاس آسہِ، تیٚلہِ دِیُن أمِس چیٚنہٕ خٲطرٕ آب دِنہٕ۔\n22. تِکیازِ تُہۍ دِیُن أمۍ سٕنٛدِس کلَس پٮ۪ٹھ نارٕکۍ کولہٕ ڈھیر، تہٕ خداوند دِیہِ تۄہہِ انعام۔\n23.\\tشمٲلی واو چھُ روٗد ژٔلِتھ ژٔلِتھ: تَتھ کٔرِتھ چھُ اکھ غصہٕ ہُند بُتھ، اکھ غیبت زبنہٕ۔ {ڈرایوتھ...: یا، اَنُن روٗد: یِتھے پٲٹھۍ چھُ غیبت زبان اکھ غصہٕ ہُند بُتھ}\n24.\\tیہ چھہ مکانہ کس کونس منز روزُن بہتر، لڑایہِ زنانہِ سٍتۍ تہٕ کُنہِ وسیع مکانس منز۔\n25. {یِتھ} چھُ أکِس ترشِس روحس سرد آب، تِتھہ کٔنۍ چھُ دوٗرِ مُلکٕچ خوشخبری۔\n26.\\tاکھ نیک انسان یُس بدکارس برونہہ کُن پیوان چُھہ تہٕ اکھ بدکار چشمہٕ تہٕ اکھ بدکار چشمہٕ۔\n27.\\t{یہ چھُنہ} زیادٕ ماچھ کھیوٚن چُھہ نہٕ اصل: لہذا {انسانہٕ} پنُن جلال ژھانڈُن {چُھنہ} جلال ۔\n28.\\tیُس نہٕ پننِس روحس پیٹھ کانہہ حکمرٲنی آسہِ، سُہ چُھ اکھ شہر {یعنی} پھُٹمُت، {تہٕ} دیوارٕ ورٲے ۔","1.\\tریتہٕ کالہِ منز شیٖن تہٕ فصلس منز روٗد پٮ۪وان، تِتھے پٲٹھۍ چھُنہٕ بیوقوفس خٲطرٕ عزت لایق۔\n2.\\tیتھے پاٹھۍ جاناوار پھیران چھہِ، یتھہ پاٹھۍ وُڈان چھہِ، تتھے پاٹھۍ گژھہِ نہ بد دعا یُس بے وجہ سپدِ۔\n3.\\tگُرِ خٲطرٕ اکھ کوڑ، گُرِ خٲطرٕ اکھ لگام، تہٕ بیوقوف سٕندِ کمرس خٲطرٕ اکھ لور۔\n4.\\tکٲنسہِ بیوقوفس سٍتـ̡ مہٕ جواب دِیُن، نتہٕ گژھہِ تٔمِس ہِش تہِ۔\n5.\\tبیوقوفس کٔرِو تٔمۍ سٕنزِ حماقت مطٲبق جواب، تاکہ سُہ گژھہِ پننِس غرورس منز عقلمند۔ {مغرور: ہیب۔ اچھ}\n6. یُس بیوقوف سٕندِ اتھہٕ سٍتـ̡ پیغام سوزان چُھ، سُہ چُھہ کھۅر ژٹان {تہٕ} چُھہ نۄقصان چُھ۔ {نقصان: یا، تشدد}\n7.\\tلنگن ہنزن زنگن چھیہ نہ برابر: لہذا چھہ بیوقوفن ہندس ٲسس منز اکھ تمثیل۔ {are...: Heb. تُلنہٕ آمُت}\n8.\\tیِتھٕ پٲٹھۍ یُس غلیلِس منز کنہِ کٔنہِ گٔنڈِتھ چُھ، تِتھے پٲٹھۍ چُھ سُہ یُس بیوقوفس عزت دِوان چُھ۔ {bindeth...: یا، کنن ہندس ڈھیرس منز اکھ قیمتی پتھر تھوو}\n9.\\t{یتھہ پاٹھۍ} اکھ کانٹہ چھہ شرابس اتھس منز کھسان، تتھے پاٹھۍ چھہ بیوقوفن ہندس ٲسس منز اکھ تمثیل۔\n10. یُس عظیم {خدا} یُس سارِنٕے چیزن بنوومُت چُھ، سُہ چُھ بیوقوفس انعام دِوان تہٕ ناکارن دِوان یُس انعام۔ {عظیم...: یا، اکھ بٔڈ انسان چُھ سارِنٕے غمگسار کران، تہٕ سُہ چُھ بیوقوفس کرایہ دِوان، سُہ چُھ نافرمان تہٕ کرایہ دِوان}\n11.\\tیتھہ پاٹھۍ ہوُن پننہِ الٹی کُن واپس یوان چھُ، بیوقوف چھہ پننہِ حماقتس کُن واپس۔ {واپس پننِس حماقتس کُن: ہیب۔ تٔمۍ سٕنز حماقت دہراونہٕ}\n12.\\tژیہ وچھکھ اکھ عقلمند انسان پننِس غرورس منز؟ {أمِس کھۅتہٕ چھُ بیوقوفٕچ زیادٕ وۅمید ۔\n13.\\tکُنہِ سٍتـ̡ چُھہ وَتہِ سٕہہ سٍتـ̡ وَنان۔ سڑکن منز چُھ اکھ شیر {چُھ}۔\n14.\\tیتھے پاٹھۍ چھہ دروازہ امۍ سندس بسترس پیٹھ پھیران، تتھے پاٹھۍ چھہ کُنہِ بسترس پیٹھ کُنہِ\n15.\\tکُنہِ یہِ چھُ أمِس دُبارٕ پننِس ٲسس تام اننہٕ خٲطرٕ غم۔ {یہ چھہ غم...: یا، سہ چھہ تھکھ گومت}\n16.\\tسُہ چھُ پننِس غرورس منز سَتن نفرن ہٕندِ کھۅتہٕ زیادٕ عقلمند آسان یُس کانہہ وجہ پیش کٔرِتھ۔\n17.\\tیُس نیران چُھ، {تہٕ} تٔمِس سٍتـ̡ ہُندِس سٍتـ̡ رٔٹِتھ {تہٕ} سُہ چُھہ ہُنـ̡ ہُند کُن رٔٹِتھ رٔٹِتھ ۔ {مداخلت: یا، شرارت}\n18.\\tبحیثیت اکھ پاگل {انسان} یُس آتش برانڈ، تیر تہٕ موت تراوان چُھ، {آتش برانڈز: ہیب۔ نار، یا، چنگاری}\n19.\\tتیلہ چھہ انسان پننس ہمساین دھوکہ دِتھ ونان زِ بہٕ چھُس نہٕ کھیلس منز؟\n20.\\tییتہِ نہ کانہہ لٔکر آسہِ، تتہِ چھہ نار نیران: ییتہِ نہ کانہہ افسانہ نگار آسہِ، تتہِ چھہ یہ کشمکش ختم گژھان۔ {ییتہِ نہ...: ہیب۔ لٔکرِ ورٲے} {افسانہٕ: یا، سرگوشی} {Ceaseth: Heb. خاموش چُھ}\n21. {As} کول {چِھ} زالنہٕ خٲطرٕ، تہٕ لٔکرِ نارس خٲطرٕ؛ تَوَے چھُ اَکھ متنازعہ شخٕص یُس کشمکش پٲدٕ کَرُن۔\n22.\\tافسانہ نگار سٕندۍ لفظ چھہِ زخمن ہٕندۍ پٲٹھۍ، تہٕ یِم چھِ یٔڈ کِس اندرمس حصس منز وسان ۔ {اندرم...: ہیب۔ چیمبرز}\n23.\\tدزُن وُٹھ تہٕ بدکار دِل چھُ رۅپہٕ سٍتۍ ؤلِتھ کُنہِ برنہٕ ہٕندۍ پٲٹھۍ۔\n24.\\tیُس نفرت کران چُھہ سُہ چُھہ پننِس وٹھہٕ سٍتـ̡ دھوکہٕ دِوان تہٕ پانس اندر دھوکہ دِوان۔ {dissembleth: or, is known}\n25.\\tییلہ سُہ صحیح کتھ کرِ، تٔمِس کٔرِو نہٕ پژھ کٔرِتھ، تِکیازِ تٔمِس دِلس مَنٛز چھِ سَتھ مکروہ کُن۔ {کتھ کٔرتھ...: ہیب۔ تٔمۍ سٕنز آواز چھے مہربان بناوان}\n26.\\tیێمہِ سٕنزِ نفرتُک دُعا چُھہ دِنہٕ آمُت، تٔمۍ سٕنز بدکاری گژھہِ پورٕ جمٲژ برونہہ کُن ظٲہر کرنہٕ۔ {by...: یا، خفیہ منز}\n27.\\tیُس تہِ کھۅنہٕ کھٔنِتھ سُہ گژھہِ اَتھ مَنٛز پَسُن، تہٕ یُس کنہِ کُ\n28.\\tاکھ اپُز زبان چھیہ نفرت کران یُس اتھ سٍتۍ مبتلا آسہِ۔ تہٕ اکھ خوشامد کرن وول اوس بربادی کران۔","1. پگہہ تام گژھ نہ پانس پیٹھ فخر کرُن۔ تکیازِ ژیہ چھیہ نہ پتاہ زِ اکھ دۅہ کیا ہیکہِ برونہہ کُن۔ {to...: Heb. پگہہ دۅہس تام}\n2.\\tبییس انسانس گژھہِ تۅہہِ تعریف کرُن، نہ چانہِ پننہِ ٲس۔ اکھ اجنبی، تہٕ نہ تُہند پنُن وُٹھ۔\n3.\\tاکھ کنہِ چھہ گوٚب، تہ سیکہِ وزن۔ مگر بیوقوف سُند قہر {چُھ} یمن دۄشوٕنی کھوتہٕ زیادٕ گوٚب۔ {ہیو: ہیب۔ وزن}\n4.\\tغصہ {چھُ}ظالمانہ، تہٕ غصہ {چھُ} ظالمانہٕ۔ مگر حسدس برونہہ کُن کُس ہیکہِ کھڑا گژھِتھ؟ {شرارت...: ہیب۔ غصہ چھہ ظلم، تہ غصہ چھہ اکھ وۅتلاو} {حسد: یا، حسد؟}\n5. کھُلہٕ ملامت {چُھ} خفیہ محبتہٕ کھوتہٕ بہتر۔\n6.\\tوفادار چھہِ یار سٕندِ زخم۔ مگر دُشمن سٕندِ بوسہ چھِ دھوکہٕ دِوان۔ {دھوکہٕ: یا، سنجیدٕ، یا، اکثر}\n7.\\tپورٕ روح چھہ شہد کُنہِ مگر فاقہٕ وٲلِس روحس خٲطرٕ چھُ پرٮ۪تھ تلخ چیز موٚدُر۔ {ناپسندیدہ: ہیب۔ ٹریڈتھ انڈر فوٹ}\n8.\\tیتھے پاٹھۍ چھہ اکھ جاناوار یُس پننہِ گرِ منزہ پھیران چھہ، تتھے پاٹھۍ چھہ انسان یُس پننہِ جایہ نشہِ پھیران چھہ۔\n9.\\tمرہم تہٕ عطر چھِ دِل خۅش کران: یِتھے پٲٹھۍ چھُ انسان سٕندِس یارس سٕنز مٹھاس دِل مشورٕ سٍتـ̡ دِل دِوان۔ {by...: ہیب۔ روح سٕندِ مشورٕ سٍتۍ}\n10.\\tپنُن دوس تہٕ پننِس مٲلہِ سُند یار، گژھ نہٕ تراوُن۔ نہ گژھ پننہ آفت کہ دۅہہ پننس بٲے سٕندِس گرس منز: {تکیازِ} ہمسایہ {یعنی} دور بٲے کھۅتہٕ بہتر چھُ۔\n11.\\tمیانہِ نیچو، عقلمند روزُن تہٕ میون دِل خۅش کرُن، یُس بہٕ میہ ملامت کرِ۔\n12. اکھ ہوشیار {انسان} چُھ بدی ہُند پیش گویی کران، {تہٕ} چُھ پنُن پان ژوٗرِ تھاوان۔ {مَگَر} سادٕ پاس دِنہٕ آمُت، {تہٕ } چھُ سزا دِنہٕ یِوان۔\n13.\\tتٔمۍ سُند پلو رٔٹِتھ یُس أکِس اجنبی زنانہِ ہٕندِ خٲطرٕ ضامن آسہِ، تہٕ تٔمِس نِش کٔرِو أکِس اجنبی زنانہِ ہٕندِ خٲطرٕ گروی ۔\n14. یُس پننِس دوستس بَڑِ آوازِ سٍتـ̡ برکت دِیہِ، سُلہٕ وۅتھان چُھ، سُہ گژھہِ أمِس خٲطرٕ لعنت۔\n15.\\tوارہ رودۍ دۅہس منز اکھ مسلسل تراوُن تہ اکھ متنازعہ زنانہ چھیہ ہِشی آسان۔\n16.\\tیُس یُس أمِس ژوٗرِ تھاوان چُھ، سُہ چُھ واو تہٕ دچھنہِ اتھہٕ ہُند مرہم ژوٗرِ تھاوان، {یُس} چُھ پانہٕ وُچھان۔\n17. ششتٕر چُھ ششتٕر تیز کَران۔ تہ چھہ انسان پننس یارس سُند بُتھ تیز کران۔\n18.\\tیُس تہِ انجیر کُلِس رچھِ، سُہ گژھہِ اَمیُک پھل کھٮ۪ن، یُس پننِس آقا سُند انتظار کرِ، سُہ گژھہِ عزت کرنہٕ۔\n19.\\tیتھے پاٹھۍ چھہ آبہِ بُتھِ کُن بُتھِ، تِتھے پٲٹھۍانسان سُند دِل تہِ چھُ۔\n20. جہنم تہٕ تباہی چِھ نہٕ زانہہ پورٕ آسان۔ لہذا چھہ نہ انسان سنزِ اچھ زانہہ تہِ مطمئن سپدان۔ {زانہہ: ہیب۔ نہٕ}\n21. رۄپہٕ خٲطرٕ چُھہ بٹھہٕ تہٕ سۄنہٕ خٲطرٕ بھٹ۔ تَوَے چھُ اَکھ شخٕص تٔمِس تعریفَس مَنٛز۔\n22.\\tیودوَے ژے کٕنکہٕ سٍتـ̡ بیوقوف سٍتـ̡ کٕنکہٕ سٍتـ̡ بیوقوف سٍتـ̡ کُنہِ کُنہِ سٍتـ̡ بێوُن دِنہٕ یِنہٕ سٍتـ̡ تٔمِس سٍتـ̡ بێوقوفی ہٕندِس سٍتـ̡ دِنہٕ یِنہٕ سٍتـ�\n23.\\tپنہٕ نِس کھورِ ہُند حال زاننہٕ خٲطرٕ روٗزِو محنتی، {تہٕ} پَنٕنٮ۪ن کھیٚلہٕ وُچھِو۔ {وچھو...: ہیب۔ پنُن دِل سیٹ کرُن}\n24. دولتس خٲطرٕ چُھ نہٕ ہمیشہٕ خٲطرٕ: تہٕ کیا تاج چُھ پرتھ نسلس خٲطرٕ برقرار تھاوان؟ {دولت: ہیب۔ طاقت} {to...: Heb. نسل تہٕ نسلہٕ خٲطرٕ؟}\n25.\\tگاسہ چھہ ظٲہر سپدان، تہ نرم گاسہ چھہ پانس سیتۍ واٹھ دِوان، تہ بالن ہندۍ جڑی بوٹی چھہِ جمع گژھان۔\n26.\\tکٹہٕ کۅکرِ تہٕ ژھاوٕل چھِ کھہہٕ ہُند قٕمتھ ۔\n27.\\tتہٕ ژے گژھہِ ژھاوُن ہُند دۄد پننہِ کھٮ۪نہٕ خٲطرٕ، پننہِ گرٕ کِس کھٮ۪نہٕ خٲطرٕ، تہٕ پننہِ کورِ ہٕندِ خٲطرٕ کٲفی دۄد۔ {مینٹیننس: ہیب۔ زندگی}","1.\\tبدکار چھہ ژلان ییلہ نہ کانہہ انسان تعاقب کران چھہِ: مگر نیک چھہِ شیرہ ہیو بہادر۔\n2.\\tکُنہِ زمینہِ ہٕندِس خلاف ورزی کِس سٍتـ̡ واریاہ {چھِ} اَمہ کِس شہزادہٕ: مگر أکِس سمجھدار سٍتـ̡ {تہٕ} عٔلِم سٍتـ̡ روزِ حالتُک طویل۔ {by...: یا، سمجھ تہٕ دانشمند نفرن ہٕندِ ذریعہٕ گژھن تِم یِتھے پٲٹھۍ طویل}\n3.\\tغریبن پیٹھ ظلم کرُن چھہ سہ چھہ اکھ وسوُن روٗد ہیو یُس نہ کانہہ غذا تراوان چھہ۔ {کُس...: ہیب۔ کھیٚنہٕ ورٲے}\n4.\\tیُس شریعت تراوان چھہِ تم چھہِ بدکارن ہٕنز تعریف کران، مگر یُس شریعت مانان چھہِ تم چھہِ تمن سٍتـ̡ مقابلہ کران۔\n5. بد انسان چِھ نہٕ فیصلہٕ سمجھان: مگر یُس خداوند سُند تلاش کران چُھ، تم چِھ سارِنٕے چیزن سمجھان۔\n6.\\tیُس غریب، یُس پننہِ سیدِ سیتۍ پکان آسہِ، سہ چھہ بہتر یُس پننہِ وتہِ منز بدکار آسہِ، حالانکہ سہ امیر آسہِ۔\n7.\\tیُس شریعت راے تھاوان چُھ، سُہ چُھ عقلمند نیچو آسان، مگر یُس فساد کرن والٮ۪ن ہُند سٲتھی آسہِ، سُہ چُھ پننِس مٲلِس شرم کران۔ {چھہ اکھ ساتھی...: یا، فیڈ گلٹنز}\n8.\\tیُس سود تہٕ ناجائز نفع سٍتۍ پنُن مال ہُرراوان چُھ، سُہ کرِ تٔمِس خٲطرٕ جمع یُس غریبن پیٹھ رحم کرِ۔ {ناانصافی...: ہیب۔ اضافہٕ ذریعہٕ}\n9.\\tیُس شریعت بوزنہٕ نِش کُن پھیُرِ، تٔمۍ سٕنز دُعا تہِ گژھہِ مکروٗر۔\n10.\\tیُس یُس نیک شخصس بد کار سٍتـ̡ گمراہ کرِ، سُہ گژھہِ پننِس کھۅنہِ مَنٛز پییہِ، مگر نیک شخصس آسہِ نیکی چیزن ہٕندِس قبضس منز۔\n11.\\tامیر شخص چھہ پننِس غرورس منز دانشمند۔ مگر غریب یُس سمجھ آسہِ سُہ چھُ أمِس ژھانڈان۔ {پنُن...: ہیب۔ اچھ}\n12.\\tییلہ نیک انسان خوش سپدان چھہِ، {تتہِ} چھہ عظیم جلال سپدان: مگر ییلہ بدکار وۅتھان چھہِ، انسان چھہ پوشہ آسان۔ {پوشیدٕ: یا، ژھانڈنہٕ}\n13.\\tیُس پنہٕ نِس گۅنہٕ ہُند اقرار کرِ، سُہ گژھہِ نہٕ کامیاب سپدِ، مگر یُس اقرار کرِ تہٕ تراوِ سُہ گژھہِ رحم کرنہٕ۔\n14.\\tخوش چھہ سُہ انسان یُس ہمیشہ کھوژان آسہِ، مگر یُس دِل سختی کرِ، سُہ گژھہِ شرارتس مَنٛز۔\n15. {As} اکھ گڑبڑ شیر تہٕ اکھ رینج ریچھ۔ {یِتھٕ کٔن} چھُ غریبَن ہُند اکھ بدکار حُکُمران۔\n16.\\tیُس شہزادہ سمجھُن یژھان چُھ، سُہ تہِ چھُ اکھ بوٚڈ ظٲلم تہِ: {مگر} یُس لالچ نفرت کرِ، سُہ گژھہِ پننین دۅہن زیٹھراوُن۔\n17.\\tیُس انسان {کٲنسہِ} شخصہٕ سٕندِس خونس سٍتـ̡ ظلم کرِ، سُہ گژھہِ کھۅڈس کُن ژلُن۔ کانہہ تہِ مرد گژھہِ نہ تس ٹھہراونہ۔\n18.\\tیُس یُس سیدِ پٲٹھـ̡ پکان چُھ، سُہ گژھہِ نجات دِنہٕ، مگر یُس یُس پنہٕ نِس وتہِ سٍتـ̡ گٔژھِتھ آسہِ۔\n19.\\tیُس پَنٕنہِ زمینہٕ کَرِ تٔمِس آسہِ سٮ۪ٹھاہ روٹی حٲصِل کٔرِتھ، مگر یُس بیکار پَتہٕ روزِ، تٔمِس آسہِ غریبی ہٕندِس سٍتـ̡ غریب۔\n20.\\tوفادار انسان گژھہِ نعمتو سٍتـ̡ بٔرِتھ، مگر یُس امیر بننس منز جلدی کرِ، سُہ گژھہِ نہٕ معصوم آسُن۔ {معصوم: یا، غیر سزا}\n21.\\tشخصن ہُند احترام کرُن چُھ نہٕ اصل: تکیازِ روٹی ہٕندِ ٹُکرٕ خٲطرٕ کرِ انسان زیادٕ۔\n22.\\tیُس امیر گژھنس منز جلدی کران چُھ، سُہ چُھ نہٕ بد نظر تہٕ یہِ سُہ چُھہ نہٕ یہِ سوچان زِ غریبی ییہ أمِس سٍتـ̡ ۔ {جلدی...: یا، بد نظر چھے امیر گژھنس جلدی کران}\n23.\\tیُس پتہٕ کٲنسہِ انسانس ملامت کرِ، تس میلہِ زبانہِ سٍتـ̡ خوشامد کرن وٲلِس کھوتہٕ زیادٕ عنایت حٲصل۔\n24.\\tیُس تہٕ یُس پننِس مٲلِس یا ماجہ ہُند لُٹان چُھ، تہٕ وَنُن چُھہ زِ یہِ چُھہ نہٕ کانہہ زیادتی ۔ یۅہے {چُھ} أکِس تباہ کرن وول سُند سٲتھی۔ {اکھ تباہ کار: ہیب۔ اکھ انسان تباہ کران}\n25.\\tیُس مغرور دِل آسہِ سُہ چُھ کشمکش پٲدٕ کران: مگر یُس خداوند سٍتـ̡ بھروسہٕ کرِ، سُہ گژھہِ موٚٹُر بنہٕ۔\n26.\\tیُس پننِس دِلس پیٹھ بھروسہٕ کرِ، سُہ چُھ بیوقوف آسان، مگر یُس عقلمندی سان پکان چُھ، سُہ گژھہِ نجات دِنہٕ۔\n27.\\tیُس غریبن دِیہِ تس گژھہِ نہ کٔمی، مگر یُس پنٕنۍ أچھ ژوٗرِ تھاوان آسہِ، تس گژھہِ واریاہ لعنت۔\n28.\\tییلہ بدکار وۅتھان چھہِ، انسان چھہ پانس ژوٗرِ تھاوان، مگر ییلہ تم مران چھہِ، نیک چھہ ہُران۔","1. سُہ یُس اکثر ملامت کرنہٕ آمُت چُھ، سُہ گژھہِ اچانک تباہ کرنہٕ یُن، تہٕ سُہ یُس علاج ورٲے سپدِ۔ {یہ...: ہیب۔ ملامت کرن وول انسان}\n2. ییلہِ نیک لوگ اِقتدارس منز آسان چھِ، لوٗکھ چھِ خوش گژھان: مگر ییلہِ بدکار حکومت کران چھِ، لوٗکھ چھِ ماتم کران۔ {منز...: یا، اضافہٕ}\n3. یُس حکمتُک محبت کران چُھ، سُہ چُھ پننِس مٲلِس خۅش کران، مگر یُس زن طریٖقن سٍتـ̡ صحبت تھاوان چُھ، سُہ چُھ پنُن مال خرچ کران۔\n4. بادشاہ چُھ فیصلہٕ سٍتـ̡ زمینہٕ قایم کران: مگر یُس تحفہٕ میلان چُھ، سُہ چُھ سُہ الٹان۔ {وہ...: ہیب۔ نذراتن ہُند اکھ انسان}\n5.\\tیُس انسان پننِس ہمساین خوشامد کران چُھ، سُہ چُھ پننین کھۅرن خٲطرٕ جال پھہلاوان۔\n6.\\tبدکار سٕندِس گُزارس مَنٛز چُھ اکھ پھندٕ آسان، مگر نیک چھُ گٮ۪وان تہٕ شاد سپدان۔\n7.\\tنیک چھہ غریبن ہند سبب سمجھان: {مگر}بدکار چھہ نہ یہ زانان۔\n8. حقارت آمیز انسان چھِ أکِس شہرس جالس منٛز انان: مگر عقلمند {مرد} چھِ غصہٕ ژوٗر کران۔ {انن...: یا، اکھ شہرس نار دِیُن}\n9.\\tاگر کانہہ عقلمند کٲنسہِ بیوقوف شخصس سیتۍ بحث کرِ، چاہے سہ غصہ آسہِ یا اسُن، تیلہِ چھہ نہ کانہہ آرام سپدان۔\n10.\\tخونٕکۍ پیاسہٕ چھِ راست سٍتـ̡ نفرت: مگر عادل چھِ تٔمۍ سٕندِس روحس ژھاران۔ {خونٕکۍ پیاس: ہیب۔ خونٕکۍ مرد}\n11.\\tبیوقوف چھہ پنن سورے ذہنس کُن کتھ کران، مگر اکھ عقلمند {انسان} چھہ یہ تمہ پتہ پانس منز تھاوان۔\n12.\\tاگر کانہہ حکمران اپُز بوزان آسہِ، تٔمۍ سٕندِ سٲری خادم چھِ بدکار آسان۔\n13. غریب تہٕ دھوکہ دہی انسان چھِ اکوٹہٕ سمکھان: خداوند چُھ دۄشوٕے أچھ گاش کران۔ {دھوکہٕ دِنہٕ وول...: یا، سود خور}\n14.\\tیُس بادشاہ یُس وفاداری سان غریبن ہُند فیصلہ کرِ، تٔمۍ سُند تخت گژھہِ ہمیشہٕ خٲطرٕ قایم کرنہٕ۔\n15.\\tلٔر تہٕ ملامت چھے حکمت دِوان: مگر یُس شُر پانس کُن تراوان چُھ، سُہ چُھ ماجہ شرمندہ کران۔\n16. یێلہِ بدکارن ہُند تعداد چُھہ بٔڑِتھ سپدان تہٕ گُرِ ہُند سُہ چُھ ہُران۔\n17. پَنُن نیچو کٔرِو ٹھیٖک تہٕ سُہ دِیہِ ژےٚ آرام دِنہٕ۔ آ، سُہ دِیہ چانہِ روحس خۅش۔\n18.\\tییتہِ نہٕ کانہہ وژن آسہِ، لُکھ چھُ ختم سپدان: مگر یُس شریعت رژھراوان چُھ، سُہ چُھ خوش گَژھان۔ {فَرٕش: یا، چُھ ننگہٕ بناونہٕ آمُت}\n19.\\tخادم گژھہِ نہ لفظو سٍتۍ درست کرنہٕ، تکیازِ سُہ سُہ کرِ نہٕ جواب۔\n20.\\tژیہ وچھکھ کانہہ انسان یُس پننین کلامَن منز جلد بازی کران چھُ؟ {أمِس کھۅتہٕ چھُ بیوقوفٕچ زیادٕ وۅمید ۔ {الفاظ: یا، معاملہٕ؟}\n21.\\tیُس شُرۍ سٍتـ̡ پنُن نوکر نازک پٲٹھـ̡ پٲدٕ کرِ، سُہ گژھہِ پَنُن نیچو بنہٕ۔\n22.\\tاکھ شرارت وول انسان چھہ کشمکش کران تہ اکھ غصے وول انسان چھہ سرکشی کران۔\n23.\\tانسان سُند غرور کرِ أمِس پست مگر عزتٕ کرِ عاجزن ہٕندِس روحس رژھراونہٕ۔\n24.\\tیُس تہِ ژوٗرس سٍتـ̡ شریک آسہِ، سُہ چُھ پننِس روحس سٍتـ̡ نفرت کران: سُہ چُھہ بد دعا بوزان تہٕ سُہ چُھہ نہٕ بد دعا کران۔\n25.\\tانسانہٕ سُند خوف چُھ پھانس ہُند پھانس انان، مگر یُس تہِ خداوند سُند بھروسہٕ کرِ، سُہ روزِ محفوٗظ۔ {محفوظ: ہیب۔ تھزرس پیٹھ سیٹ کٔرتھ}\n26. واریاہ چھِ حکمران سٕنز عنایت ژھاران۔ مگر {پرٮ۪تھ کُنہِ} انسان سُند فیصلہ چُھ خداوند سٕندِ طرفہٕ یِوان۔ {حکمران سُند...: ہیب۔ حکمران سُند بُتھ}\n27.\\tبدکار انسان چھہ عادل سندِ خاطرہ مکروہ تہ یُس بدکارن ہندِ خاطرہ مکروہ چھہ۔","1.\\tیعقوب سٕندِس نیچوِس آگور سٕندِ کلام، {حتیٰ کہ} پیشن گویی تہِ: انسانس کٔر اِتھیلس سٍتـ̡ تہٕ اِتھیل تہٕ یوکل سٍتـ̡ تہِ،\n2.\\tیقینا بہٕ چھُس {کٲنسہِ} انسان سٍتۍ زیادٕ وحشی، تہٕ چھُس نہٕ کٲنسہِ انسانس سٍتۍ سمجھان۔\n3. میہ چھہ نہ حکمت ہیچھمژ، نہ چھہ مقدس سند علم۔ {ہیو: ہیب۔ زانہ}\n4. کُس چُھ آسمانس مَنٛز کھسُن، یا ووت ووٚتھ؟ کٔمۍ چُھ پننین مٹھین منز واو جمع کورمُت؟ آبس کُس چھہ پلوس منز بند کورمُت؟ زمینہِ ہندۍ سٲری اندۍ کٔمۍ چھہِ قایم کٔرۍمٕتۍ؟ تٔمۍ سُند ناو کیا چُھ، تہٕ تٔمۍ سٕندِس نیچوۍ سُند ناو کیا چُھ، اگر ژیہ ؤنتھ ہیکو؟\n5. خدایہ سُند پرٮ۪تھ کانہہ کلام چُھ پاک: سُہ چُھ تِمن ہٕندِ خٲطرٕ اکھ ڈھال یُس تِمن پیٹھ بھروسہ کران چُھ۔ {خالص: ہیب۔ پاکیزہ}\n6.\\tتٔمۍ سٕندِس کلامس مَنٛز گژھِ نہٕ اضافہٕ، نتہٕ سُہ کرِ تۅہہِ ملامت تہٕ ژے گژھہِ اپُز لبنہٕ۔\n7. میہ چھیہ ژیہ نِش زٕ {چیز} منگان۔ میہ کٔر نہ میہ مرنہٕ برونہہ کُن: {انکار...: ہیب۔ میہ نش گژھ نہٕ روک}\n8.\\tمیہ نِش دوٗر کٔرِو باطل تہٕ اپُز: مے دِیُن نہ غریبی تہٕ نہ دولت۔ میہ کھیوٚن کھیوٚن میانہِ خاطرہ آسان: {آسان...: ہیب۔ میانہِ الاؤنس}\n9. یێلہِ بہٕ پوٗرٕ گٔژھِتھ تہٕ تێہہ نِش انکار کٔرِتھ ونُن، خداوند کُس چُھہ؟ نتہٕ بہٕ گژھہٕ غریب، تہٕ ژورِ نِنہٕ، تہٕ پننِس خدایہ سُند ناو رٔٹِتھ {بیکار}۔ {انکار...: ہیب۔ ژیہ کٔرِتھ کٔرِو\n10.\\tکٲنسہِ نوکرس پیٹھ گژھ نہ پننِس آقا سُند الزام لگاونہٕ، نتہٕ سُہ کرِ تۅہہِ بد دُعا تہٕ تۅہہِ گژھہِ قصوروار لبنہٕ۔ {الزام...: ہیب۔ پننہِ زبانہِ سٍتۍ گژھ نہ تکلیف دِنہٕ}\n11.\\tاکھ نسل چھہ یُس پننس مٲلس لعنت کران چھہ تہ ماجہ چھہ نہ دُعا کران۔\n12.\\t{اَکھ نسل چھُ} یُس پننین نظرن منز پاک چھُ، تہٕ {توتہِ} چھُنہٕ تِمن ہٕنزِ گندگی نِش واش سپدان۔\n13.\\tاکھ نسل، اے تِہٕنزِ أچھ کوتاہ تھدِ چھِ! تہٕ تِہٕنٛزِ ٹٲرۍ چھِ تُلنہٕ یِوان۔\n14.\\tاکھ نسل چھُ، یمۍ سٕندِ دند تلوارِ ہٕندۍ پٲٹھۍ، تہٕ تِہٕندِس دندٕ چھُرِ ہٕندِس دندٕ سٍتۍ غریبن ہٕندِس زمینہٕ نِش کھٮ۪نہٕ خٲطرٕ، تہٕ محتاجن نِش کھٮ۪نہٕ خٲطرٕ۔\n15.\\tگُرِس چھِ زٕ کورِ، {روُن}، دِو، دِو۔ تریہ {چیز چھہِ} یم زانہہ مطمئن چھہِ، {ہاں}، ژور {چیز} چھہِ نہ ونان، {یہ چھہ} کافی: {یہ چھہ...: ہیب۔ دولت}\n16. قبر؛ تہٕ بنجر رحم؛ زمین {یُس} چُھ نہٕ آبہٕ سٍتۍ بٔرِتھ۔ تہٕ نار {یُس} چُھ نہٕ ونان، {یہٕ چُھ} کافی۔\n17.\\tیُس اچھ {پننِس} مٲلِس سٍتۍ ٹھٹھہٕ کران چھُ، تہٕ ماجہ ہٕنز اطاعت کرنس حقارت کران چھُ، وادی ہٕندِس کۅکر کٔرِن سُہ تُلِتھ تہٕ جوان گُرِ کھٮ۪ن۔ {وادی: یا، نالہٕ}\n18.\\tتریہ {چیز یم میانہِ خاطرہ سیٹھا حیرت انگیز چھہِ}، آ، ژور یم نہ میہ پتاہ چھہِ:\n19. ہوہس منز عقاب سُند وتھ؛ کنہِ پتھرس پیٹھ ناگ سٕنز وتھ؛ سمندرس منز جہازچ وتھ؛ تہٕ أکِس مردٕ سٕنز وَتھ دٔرِس سٍتۍ۔ {درمیان: ہیب۔ دِل}\n20.\\tیۅہے چھہ زناکار زنانہِ ہند طریقہ۔ سۅ چھیہ کھیوان تہ ٲسس صاف کران تہ ونان زِ میہ چھیہ نہ کانہہ بدکاری کٔرمژ۔\n21.\\tترٮن چیزن ہندِ خاطرہ چھہ زمین پریشان تہ ژورن {یُس} یہ ہیکہِ نہ برداشت کٔرتھ:\n22.\\tخادم سٕندِ خٲطرٕ ییلہ سُہ بادشاہت کران چُھ؛ تہٕ بیوقوف ییلہ سُہ ماز سٍتۍ بٔرِتھ آسہِ؛\n23.\\tأکِس مکروہ زنانہٕ سٍتـ̡ ییلہ سُہ خاندر آسہِ۔ تہٕ اکھ دٲیرٕ یۄس پننہٕ مالکن ہٕنٛز وٲرث چھ۔\n24.\\tژور {چیز یم زمینس پیٹھ کم چھہِ} مگر تم چھہِ {زیادہ} عقلمند: {زیادہ...: حب۔ عقلمند، عقلمند بناوُن}\n25.\\tچیونٹۍ چھہِ نہ مضبوط لُکھ آسان، توتہِ چھِ تِم ریتہٕ کالہِ پنُن ماز تیار کران۔\n26.\\tکونِس {مگر چِھ} کمزور لُکہٕ، توتہِ چھِ تِم پَنُن گرٕ بناوان کَنہِ پَنِس پَنٕنـ̡ ۔\n27.\\tٹِڈیَن چُھنہٕ کانہہ بادشاہ، توتہِ چھِ تِم سارِنٕے جمٲژ ہٕندِس سٍتـ̡ نیران۔ {by...: ہیب۔ یکوٹہٕ جمع گٔیہٕ}\n28. مکھرِ چُھ پننیو اتھو سٍتۍ تھپھ کٔرِتھ، تہٕ چُھ بادشاہن ہٕندِس محلس منز۔\n29.\\tتریہ {چیز} چھہِ یُس اصل پٲٹھۍ، آ، ژور چھہِ گژھنس منز خوبصورت:\n30.\\tاکھ شیر {یُس} درندن منز سارِوٕے کھۄتہٕ طاقتور چُھ، تہٕ کُنہِ تہِ خٲطرٕ چُھ نہٕ پھیران۔\n31. اکھ گرے ہاؤنڈ۔ اکھ ژھاوُل تہِ؛ تہٕ اکھ بادشاہ، یٔمِس خلاف چُھنہٕ کانہہ وُتھنہٕ آمُت۔ {گرے ہاؤنڈ: یا، گُر: ہیب۔ کمرس منز گرٹ}\n32.\\tاگر ژیہ بیوقوفی کٔرِتھ پانس تھپھ کٔرِتھ یا اگر بد خیال کورمُت آسہِ، تیلہِ تھووُن پننِس ٲسس پیٹھ اتھہٕ۔\n33.\\tیقینا دۄدٕ سٍتـ̡ چُھہ تھنہٕ سٍتـ̡ تھپھ نیران، تہٕ نَس سٍتـ̡ چُھہ خوُن نیران۔","1. بادشاہ لیموئیل سٕندۍ کلام، سُہ پیشن گویی یُس تٔمۍ سٕنزِ ماجہِ أمِس ہیٚچھناوٕ۔\n2. کیا چُھ، میون نیچو؟ تہٕ کیا، میانہِ رحمُک نیٚچُو؟ تہٕ کیا، میانین وعدن ہند نیچو؟\n3. پَنُن طاقت دِیُو نہٕ زنانن تہٕ نہ دِیُن پَنٕنۍ وَتھ یُس بادشاہن تباہ کران چھُ۔\n4. {یہِ} چُھنہٕ بادشاہن ہٕندِ خٲطرٕ، اے لیموئیل، {یہِ چُھنہٕ بادشاہن ہٕندِ خٲطرٕ شراب چیٚنہٕ﴾۔ نہ شہزادن ہٕندِ خٲطرٕ:\n5.\\tیِم گژھن چیٚن، تہٕ شریعت مٔشِد گژھن تہٕ کٲنٛسہِ تہِ مُتٲثِر سُند فیصلہٕ رُکاونہٕ یِن۔ {prevert: Heb. alter} {of any...: Heb. مصیبت کین سارنٕے نیٚچوۍ}\n6. یُس مرنہٕ خٲطرٕ تیار چُھ، تٔمِس دِیُن شراب۔ {of...: ہیب۔ روحُک تلخ}\n7.\\tسُہ گژھہِ پَنُن غریبی مٔشِل کٔرِتھ، تہٕ پَنُن مُصیبت یاد تھاوُن نہٕ۔\n8.\\tتِمن سارِنٕے سٍتـ̡ یِمن ہٕندِس سٍتـ̡ تباہی ہٕندِس سٍتـ̡ مُقرر کرنہٕ آمُت چُھ، پَنُن چُھہ گونگـ� {یتھہ پاٹھۍ...: ہیب۔ تباہی ہٕندۍ نیٚچو}\n9. پَنُن چُھہ کھولُن، نیکی سٍتـ̡ کٔرِو تہٕ غریبن تہٕ محتاجن ہٕندِ سٍتـ̡ وُچھِو۔\n10. نیک زنان کُس ہیکہِ ژھٲنڈِتھ؟ تٔمۍ سٕندِ قٲمتس خٲطرٕ {چُھ} روبی کھوتہٕ واریاہ زیادٕ۔\n11. تٔمِس خانٛدار سُند دِل چُھ أمِس پیٹھ پژھ تھاوان، یُتھ زن أمِس گژھہِ نہٕ غنیمتٕچ ضرورت۔\n12. سُہ کرِ أمِس سٲرۍسٕے دۅہہٕ نیکی تہٕ بُرٕ کَرِ نہٕ۔\n13.\\tسۅ چھے ییر، تہٕ فلکس ژھانڈان تہٕ پننہ مرضی سٍتۍ کٲم کران۔\n14.\\tسۅ چھے سوداگرن ہٕندِس جہازس ہٕندۍ پٲٹھۍ۔ سُہ چُھ دوٗرِ پیٹھٕ پنُن کھٮ۪ن انان۔\n15.\\tسۅ چھے رٲژ وُتھان تہٕ گرس ماز تہٕ پننین کورٮ۪ن دِوان۔\n16.\\tسُہ چُھہ کھہٕ وُچھان، تہٕ چُھہ اَتھٕ سٍتـ̡ سُہ انگور باغ لاگان۔ {بٔنِتھ: ہیب۔ taketh}\n17. سُہ چُھ پنٕنـ̡ کمر مضبوطہٕ سٍتـ̡ رٔٹِتھ پَنٕنـ̡ نٔر مضبوٗط کَران۔\n18.\\tأمِس چُھ سمجھان زِ تٔمۍ سُند مال چُھہ اصل: تٔمۍ سٕنز شَم بَژ چھے نہٕ رٲژ ژھیتہٕ گَژھان۔ {سۅ...: ہیب۔ سۅ چکھ چکھ}\n19.\\tسۅ چھیہ اتھہ کُن تھپھ کٔرتھ تہ اتھہ چھہ ڈِسٹافس تھپھ کران۔\n20. سُہ چُھ غریبن کُن اتھہٕ بڑاوان؛ آ، سۅ چھیہ ضرورت مندن تام اتھہ واتان۔ {سۅ...: ہیب۔ سُہ چُھ پھٔہلِتھ}\n21.\\tسۅ چھیہ نہ پننس گرس منز شینس کھوژان: تکیازِ تمۍ سندِ گرس منز چھہ سرخ پوشہ لٔگتھ۔ {سکارلیٹ: یا، ڈبل گارمنٹس}\n22. سُہ چُھ پانس ٹیپسٹری ہُند پردٕ بناوان۔ تٔمۍ سُنٛد پلو چھُ ریشم تہٕ جامنی رنگ۔\n23.\\tتٔمۍ سُند خانٛدار چُھ دروازس مَنٛز زاننہٕ یِوان، یێلہِ سُہ زمینہٕ کِس بزرگن مَنٛز بِہتھ چُھ۔\n24. سُہ چُھ عمدہ کُن بناوان، تہٕ کٕنان۔ تہٕ سوداگرس کٔرِتھ کٔرِتھ دِوان۔\n25.\\tطاقت تہٕ عزت چھِ تٔمۍ سٕندِس لباس۔ تہٕ سۅ گژھہِ یِنہٕ وٲلِس وقتس منز خوش۔\n26. سُہ چُھ عقلہٕ سٍتـ̡ بوش کھولان۔ تہٕ تٔمۍ سٕنزِ زبانہِ منز چُھ رحمتُک قانون۔\n27.\\tسُہ چُھ پننِس گرٕ کِس طریقس پیٹھ نظر تھاوان، تہٕ سُہ چُھ نہٕ بیکار روٹی کھیوان۔\n28.\\tتٔمۍ سٕندِ شُرۍ چھِ وۅتھان تہٕ أمِس بابرکت ونان چھِ۔ تٔمۍ سُند خانٛدار {تہِ}، تہٕ سُہ چُھ تٔمۍ سٕنز تعریف کران۔\n29.\\tواریاہو کوریو چھے نیکی کٔرمٕژ، مگر تُہۍ چھِو یِمن سارِنٕے سٍتـ̡ سٍتـ� {ہا...: یا، چھُ دولت حٲصل کٔرمٕژ}\n30. احسان {چُھ} دھوکہٕ دِنہٕ آمُت، تہٕ خوبصورتی {چُھ} بیکار: {مگر} زنانہٕ {یُس} خداوند سُند خوف آسہِ، تٔمِس گژھہِ تعریف کرنہٕ۔\n31.\\tأمِس دِیُن تٔمِس اتھن ہُند پھلہٕ۔ تہٕ دِیُن پنٕنۍ کٲم دروازن منز أمِس تعریف۔"];
